    T = "Книга Ура",
  },
  [10130] = {
    D = "Орки Скверны получили новый приказ – готовить войска и боевую технику к наступлению.$B$BОплот Чести хотят зажать в тиски и армия боевого командира Некрогга должна сформировать западный фланг.$B$BЕсли Оплот атакуют с запада, когда гарнизон будет занят обороной восточных стен, то вряд ли мы сумеем отбиться. Единственная наша надежда – вывести из строя западный фланг еще до начала сражения.",
    O = "Убейте 10 стражников, 10 берсерков и 5 послушников клана Изувеченной Длани. О выполнении задания доложите лейтенанту Амади, которая будет ждать вас в западной сторожевой башне Оплота Чести.",
    T = "Западный фланг",
