  [10301] = {
    D = "Хотя я рад получить обратно большую часть компендиума Краса, он бесполезен без Халцедонового ока. Видишь ли, Крас хорошо сознавал всю силу заклинаний, записанных в книге, и предпринял шаги, чтобы обезопасить их от любопытных глаз.$B$BТолько знающий маг может использовать око, чтобы открыть тайны Компендиума.$B$BВо время атаки Кель'таса одна из его лейтенантов, рушительница чар Маратиль, захватила око и унесла его в Форт Ярости Солнца, находящуюся к северо-востоку от этой башни. Несомненно, она думала, что это милая побрякушка.",
    O = "Заберите Халцедоновое око у Рушительницы Чар Маратиль, находящейся в Форте Ярости Солнца.",
    T = "Открыть Компендиум",
  },
  [10302] = {
    D = "Радиоактивные силовые ядра Экзодара – настоящая беда для местной фауны и флоры. Например, рядом с ними появились странные, невиданные твари.$b$bМожет быть, им можно чем-то помочь, но в настоящий момент они так расплодились, что представляют собой серьезную угрозу.$b$bОтправляйся и сократи их число. Может быть, тем временем я что-нибудь придумаю.",
    O = "Убейте 8 неустойчивых мутаций и вернитесь к ботанику Таэрикс на месте крушения в долине Аммен.",
    T = "Неустойчивые мутации",
  },
  [10303] = {
    D = "Останови... нашествие... эльфов крови. Узнай... что они замышляют!$b$bОни у хребта... у меня за спиной.",
    O = "Убейте 10 эльфов крови-разведчиков и вернитесь к Толаану на Хребет Теней долины Аммен.",
    T = "Эльфы крови",
