  [10304] = {
    D = "С твоей помощью мы отыскали решение наших проблем гораздо быстрее, чем я надеялся.$b$bДругой работы для тебя у меня нет. Остальным займутся мои ученики.$b$bПоговори с воздаятелем Алдаром на другой стороне корабля.",
    O = "Поговорите с воздаятелем Алдаром на месте крушения в долине Аммен.",
    T = "Воздаятель Алдар",
  },
  [10305] = {
    D = "Этот потрепанный, но все еще прочный том – не книга заклинаний, как можно было бы ожидать от фолианта, принадлежащего магу Кирин-Тора. Страницы тома покрыты рукописными строчками историй и цветными иллюстрациями.$B$BПохоже, этот том старше своей бывшей владелицы и вполне может быть фамильным наследием. Мощная привязанность к этой книге – возможно, последняя нить, привязывающая Белмару к руинам Кирин'Вара. Быть может, возвращение книги на ее законное место на полке дарует свободу неупокоенному духу Белмары.",
    O = "Найдите апартаменты клятвопреступницы Белмары на Пути Волшебника и верните книгу на полку. Затем поговорите с комендантом Смертехроном в деревне Кирин'Вар.",
    T = "Клятвопреступница Бельмара",
  },
  [10306] = {
    D = "Этот плащ, несомненно работы высших эльфов; он превосходно сшит даже по меркам Кирин-Тора. Символы и буквы, вышитые на ткани плаща, не имеют, с твоей точки зрения, никакого смысла, однако явно указывают на то, что плащ наделен магическими свойствами.$B$BБыть может, этот предмет привязывает своего бывшего владельца к этому миру. Если так, то возвращение этого плаща в гардероб в апартаментах кудесника Люминрата может оборвать связь духа с этим миром и даровать душе бывшего владельца плаща покой.",
    O = "Найдите апартаменты кудесника Люминрата на Пути Волшебника и верните плащ в его гардероб. Затем поговорите с комендантом Смертехроном в деревне Кирин'Вар.",
    T = "Кудесник Люминрат",
  },
  [10307] = {
    D = "Глядя на эту шляпу, ты задаешься вопросом, мог ли кто-то из магов Кирин-Тора носить этот головной убор. Судя по виду шляпы, похоже, что в ней постоянно разгуливал гном.$B$BТы пытаешься проверить шляпу, но не обнаруживаешь у нее никаких магический свойств, кроме слабого побуждения потанцевать.$B$BДолжно быть, этот предмет, милый сердцу покойного мага, – последнее, что привязывает его дух к деревне. Если положить шляпу на вешалку в апартаментах Колиена, его дух, возможно, обретет свободу.",
    O = "Найдите апартаменты Кольена Ледоплета на Пути Волшебника и верните шляпу на вешалку. Затем поговорите с комендантом Смертехроном в деревне Кирин'Вар.",
    T = "Кольен Ледоплет",
