  [10326] = {
    D = "",
    O = "",
    T = "Больше знаков Кил'джедена",
  },
  [10327] = {
    D = "",
    O = "",
    T = "Знак Кил'джедена",
  },
  [10328] = {
    D = "Что-то в этих манагорнах беспокоит меня, $n. Технология наару чрезвычайно развита, Келю потребовались бы годы только для того, чтобы начать постигать ее.$B$BСбор сведений относительно этого вопроса очень труден, так как армия Кель'таса очень дисциплинирована и уничтожает все свидетельства письменного общения.$B$BНам сообщили, что Манагорн Даро подвергается нападению мана-тварей. Возможно, что из-за необходимости обороняться там еще не успели уничтожить инструкции. Забери их и принеси мне.",
    O = "Отправляйтесь в Маногорн Даро и заберите военные инструкции Ярости Солнца и чародейские инструкции Ярости Солнца. По завершении задачи возвращайтесь к экзарху Орелису.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.",
    T = "Инструкции Ярости Солнца",
  },
  [10329] = {
    D = "За время твоего отсутствия у меня состоялась дружеская дискуссия с Алдорами. Манагорны выглядят точь-в-точь как несколько измененные технологии наару из Крепости Бурь. Судя по всему, в большинстве конструкций наару существовал предохранитель, позволявший в случае аварии отключить их навсегда.$B$BОбычно это действие выполнялось с панели управления через кристалл доступа. И знай, что согласно принесенному тобою списку персонала, подобный кристалл находится в руках некоего типа, известного как надзиратель Тередис. Завладей этим кристаллом и посмотри, что сумеешь сделать.",
    O = "Вернитесь в Манагорн Б'наар и заберите кристалл доступа у надзирателя Тередиса. Используйте его на панели управления Манагорна Б'наар, чтобы выключить его, затем сообщите об этом патрону шпионов Талодиену. $B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.",
    T = "Отключить Манагорн Б'наар",
  },
  [1033] = {
    D = "Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.$B$BСлеза Элуны – это такой камень, который можно найти только в одном месте – у обмелевшего озера Ирис, уничтоженном при извержении вулкана Громовой Вершины. Оно находится к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, $n, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!",
    O = "Найдите Слезу Элуны.",
    T = "Слеза Элуны",
  },
  [10330] = {
    D = "Талодиен рассказал нам, что тебе удалось отключить Манагорн Б'наар. Он ожидает, что здесь произойдет то же самое, и просил нас высмотреть, у кого находится кристалл для доступа к панели управления. Мы уверены, что кристалл доступа находится у надзирателя Сейланны.$B$BОтправляйся туда и доверши дело. Больше нет необходимости в кражах; заполучи кристалл, начни отключение, убей техников, которые попытаются тебя остановить, и возвращайся.$B$BПоспеши, скоро ищейки Келя отыщут нас.",
    O = "Заберите кристалл доступа Коруу у надзирателя Сейланны. Используйте его на панели управления Коруу, чтобы отключить манагорн, затем вернитесь к Каледису Сияющему Рассвету.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.",
    T = "Отключить Манагорн Коруу",
  },
  [10331] = {
    D = "Тебе случайно не попадался на глаза тяжелый кузнечный молот – нигде там не валяется? Я принес его с собой, чтобы закончить ковать подковы для лошадей старины Армолина, но что-то никак не могу найти.$B$BЯ обыскал весь амбар полдюжины раз, но так и не нашел. Может, кто-то из учеников забрал его и отнес обратно в кузницу? Ты не сходишь туда, чтобы удостовериться? Кузница находится на северо-востоке от башни на Городской площади.",
    O = "Заберите кузнечный молот у Кирин'Варских учеников и отнесите обратно ученику Андретану в деревню Кирин'Вар.",
    T = "Необходимые инструменты",
  },
  [10332] = {
    D = "Наконец-то мое изделие, дающее право на звание подмастерья, готово! Не могу дождаться, чтобы официально предъявить его мастеру Ронсусу.$B$B*Ученик смотрит на вас, пока вы описываете ему, как достали молот.*$B$BОни на тебя напали? Все сразу? Да они сошли с ума!$B$BНу и что же нам делать, $n? Мне горько говорить об этом, но, возможно, понадобится убить мастера Ронсуса. В этом случае я останусь единственным кузнецом в Кирин'Варе, но, думаю, меня хватит, чтобы справиться с работой.",
    O = "Ученик Андретан из деревни Кирин'Вар просит вас убить призрак Ронсуса, мастера-кузнеца поселения.",
    T = "Мастер-кузнец Ронсус",
  },
  [10333] = {
    D = "Скажи, $n, не можешь ли ты оказать мне еще одну услугу?$B$BМоя напарница осуществляет работу непосредственно на месте, и ей, вероятно, приходится нелегко. Ты ее не проведаешь?$B$BЯ уверен, что Мамаша Колесун оценит твою помощь. Просто не обращай внимания на ее колкости.$B$BОна отстаивает наши интересы в восточной части этих земель. Ты найдешь ее в заповеднике \"Срединные земли\" на заставе.",
    O = "Поговорите с Мамашей Колесун, находящейся на заставе в заповеднике \"Срединные земли\" в Пустоверти.",
    T = "Помощь Мамаше Колесун",
  },
  [10334] = {
    D = "Где же, где же моя Бесси? После нападения я обыскал все поля и Церковный двор, но ее нигде не было!$B$BВсе, что мне осталось от нее – это вот этот старый колокольчик. Когда она слышала его звон, то обычно прибегала, но мои руки уже совсем ослабли. Даже для того, чтобы звонить в колокольчик.$B$BЯ одолжу тебе колокольчик Бесси, если ты согласишься пойти в поле и звонить в него как можно громче. Быть может, Бесси просто ждет, пока в колокольчик позвонят погромче и подольше.",
    O = "Найдите Бесси в полях близ Часовенного холма деревни Кирин'Вар в Пустоверти.",
    T = "Колокольчик для коровы",
  },
  [10335] = {
    D = "Я намереваюсь отправиться в Руины Фаралона, чтобы начать там раскопки. Проблема в том, что это место кишит демонами. $B$BМожет быть, ты проведешь для меня кое-какую подготовительную работу?$B$BВ северо-восточной части руин находятся три точки, где нужно разместить геодезические знаки. Каждый – поблизости от дренейского знамени.$B$BВозвращайся, когда установишь все три знака.",
    O = "Разместите три геодезических знака, затем возвращайтесь к Зефириону на Штормовую Вершину в Пустоверти.",
    T = "Исследование руин",
  },
  [10336] = {
    D = "Несколько недель назад Пылающий Легион вторгся в Руины Фаралона, нарушив наши планы относительно раскопок в поисках артефактов.$B$BА сегодня я узнал, что один из их повелителей Ужаса, Кулутас, убил своих собратьев из Пылающего Легиона и с тех пор призывает демонов, которые служат ему.$B$B$C, я прошу тебя отправиться в эти руины, находящиеся к северо-востоку отсюда, и уничтожить кишащих там демонов.",
    O = "Убейте 10 псов Кулутаса и 5 злобоглазов Кулутаса.",
    T = "Приспешники Кулутаса",
  },
  [10337] = {
    D = "Осознав, что Бесси все еще смотрит на тебя, ты жестом указываешь туда, где находится Таделл. Ты считаешь, что обещание выполнено – корова благополучно прибыла домой. Но еще не закончив говорить, ты осознаешь, что корова все равно не сможет понять ни единого слова. $B$BПожав плечами, ты готовишься сопровождать скотину, пока она не вернется к Таделлу.",
    O = "Благополучно сопроводите Бесси к ее владельцу, Таделлу.",
    T = "Когда коровы возвращаются домой",
  },
  [10338] = {
    D = "Так на Манагорн Даро совершено нападение, и войска Ярости Солнца теряют контроль? Какая дилемма. Если Даро падет, то падет и Крепость Бурь. Единственная загвоздка... если Крепость Бурь будет разрушена, взрыв, вероятно, уничтожит то немногое, что осталось от этой проклятой земли.$B$BСмерть Кель'таса – это хорошо. Смерть всех остальных... полагаю, не очень. Мне больно просить тебя об этом, но отправляйся в Манагорн Даро и отключи его прежде, чем он загорится. Кристалл доступа находится у надзирателя Атанеля.",
    O = "Вернитесь в манагорн Даро и заберите кристалл доступа у надзирателя Атанеля. Используйте его на панели управления Манагорна Даро, чтобы выключить его, затем сообщите об этом патрону шпионов Талодиену. $B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.",
    T = "Отключить Манагорн Даро",
