  [10339] = {
    D = "Прямо на юг отсюда ты найдешь полигон Братства Эфириум. Братство находится там, к чему-то готовясь... Возможно, к нападению на Ультрис.$B$BОднако мы не можем упускать шанс, |3-6($c). Нужно пробиться через их оборонительный периметр и захватить их учебную базу.$B$BКогда ты уничтожишь их солдат и капитана Зовакса, отыщи передатчик Эфириума Зета и используй его, чтобы связаться со мной для получения дальнейших указаний.",
    O = "Командир Амир просит вас уничтожить 5 убийц из Эфириума, 5 штормовиков из Эфириума, 2 ученых Эфириума и капитана Зовакса из Эфириума, затем включить передатчик Эфириума Зета.",
    T = "Братство Эфириум",
  },
  [1034] = {
    D = "Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже ее мучить, хвала богине. Но... лихорадка все еще сжигает ее.$B$BОрендил рассказал мне о морозной пыли, которую находят среди руин Звездной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси ее мне.$B$BРуины Звездной Пыли находятся на юге, $n. Да ускорит твой шаг Элуна!",
    O = "Принесите 5 горстей звездной пыли Пельтуру в Астранаар.",
    T = "Руины Звездной Пыли",
  },
  [10340] = {
    D = "$n, ты $gпроделал:проделала; на фронте большую работу, и отлично $gуправился:управилась; с тем бронированным грифоном... Я думаю, что нашел для тебя еще одно дело.$B$BНовое задание ждет тебя на Парящей заставе. Это передовой пост Громового Молота, этакий плавучий кусок земли рядом с Вратами. Там немного неуютно, но я верю, что тебе хватит смелости. Все будет отлично.$B$BПоговори с командиром звена Даби'ри, пусть он отправит тебя на Парящую заставу. Как прибудешь, доложись Грунтогу Громовому Молоту.",
    O = "По приказу командира передовой Кингстона поговорите с командиром звена Даби'ри, доберитесь на грифоне до Парящей заставы и отчитайтесь Рунтогу Громовому Молоту.",
    T = "Парящая застава",
  },
  [10341] = {
    D = "Принесенные тобой новости радуют меня, $n. Тебе не только удалось пробраться в Манагорн Даро незамеченным – это также дает отличную возможность нанести удар по армии Келя.$B$BИспользуй это нападение мана-тварей в свою пользу и перебей всех отбившихся от основного отряда солдат Ярости Солнца, на которых наткнешься.$B$BВ отличие от Талодиена, я не вижу ничего забавного в бессмысленном убийстве своих сородичей, но тактическое преимущество слишком ценно, чтобы отказаться от такого случая.",
    O = "Убейте 8 кудесников, 6 лучников и 4 центурионов клана Ярости Солнца. После завершения задачи вернитесь к магистру Ларинне, находящейся в Зоне 52.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.",
    T = "Лежачего не бьют – лежачего пинают",
  },
  [10342] = {
    D = "Я делаю неплохие деньги, продавая выпивку местным пьяницам. Но мне нужно кое-что еще!$B$BКомандующий ракетами постоянно говорит мне, что не может усовершенствовать ракетное топливо, необходимое, чтобы запустить Х-52.$B$BМы можем решить эту мелкую проблему вместо него.$B$BДля начала мне нужно извлечь нефть из кожи местных глиношкурых камнедеров! Она образует концентрированную, пусть даже несколько взрывчатую, основу для смеси, придуманной мною.$B$BКамнедеров, равно как и их кожу, можно найти повсюду около лиловых скал.",
    O = "Соберите 5 кусков кожи глиношкурых и отдайте Бутсу в Зоне 52 в Пустоверти.",
    T = "Добыча кожи глиношкурых",
  },
  [10343] = {
    D = "Атака Кель'таса на Кирин'Вар началась с громового раската и яркой вспышки света в офицерском квартале в северо-западной части поселения. Разрушения там были наиболее страшными, а после ухода эльфов крови начали происходить странные вещи. $B$BСущества, состоящие из чистой маны, буквально хлынули на деревню из этого района. Пока что мы справляемся с ними, как можем, однако я надеюсь, что если у меня будет больше сведений об этом оружии Кель'таса, я сумею прекратить вторжение мана-тварей.",
    O = "Обыщите кишащий мана-тварями район деревни Кирин'Вар в поисках фрагмента мана-бомбы и принесите его лейтенант-колдуну Моррану.",
    T = "Бесконечное вторжение",
  },
  [10344] = {
    D = "За старшего здесь командир звена Грифонгар. Если ты в первый раз на Парящей заставе, то следует доложить ему о прибытии.$B$BЕго можно найти во-он там, где-то среди остатков той башни.",
    O = "Поговорите с командиром звена Грифонгаром на Парящей заставе.",
    T = "Командир звена Грифонгар",
  },
  [10345] = {
    D = "Ты видишь эти трупы, |3-6($r)? В этом убийстве повинен Арконус. Он высосал их досуха, оставив лишь мертвую плоть. Но не дай виду этих трупов обмануть тебя! Внутри них скрываются пожаратели плоти, готовые наброситься на любого, кто подойдет поближе.$B$BУ меня есть приказ – оставаться здесь, пока не прибудет подмога. Однако ты можешь взять мой поджигатель и уничтожить эти высохшие трупы, которыми забита шахта. Так или иначе, миссия должна быть выполнена!",
    O = "Примените поджигатель Протектората к 12 высохшим трупам. Когда задача будет завершена, верните поджигатель Протектората посланнику Араксису, находящемуся у входа в шахту Зеон.",
    T = "Усеял мертвыми костями...",
  },
  [10346] = {
    D = "$n, ты $gпоказал:показала; себя отличным всадником на грифоне, так что можешь участвовать и в дальнейших вылазках к Косогору Бездны. Что скажешь, |3-6($c)? Хочешь еще полетать?",
    O = "Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по просьбе грифоньера Ветрорева с Парящей заставы на Полуострове Адского Пламени.",
    T = "Возвращение на Косогор Бездны",
  },
  [10347] = {
    D = "$n, $gготов:готова; к очередной вылазке к Косогору Бездны? Если мы прекратим постоянные атаки на Легион, то они так укрепят свои позиции, что потом на севере мы не отобьемся от демонов.$B$BЧто скажешь, |3-6($c)? Хочешь слетать еще раз на Косогор Бездны и размолоть в пыль все, что попадется?",
    O = "Уничтожьте 20 ган'аргов-батраков, 5 мо'аргов-надзирателей и 5 пушек Скверны по просьбе командира звена Бракка из Гибели Сквернобота на Полуострове Адского Пламени.",
    T = "Возвращение на Косогор Бездны",
  },
  [10348] = {
    D = "Я слышал, что группа \"друидов\" из Азерота заинтересовалась эффектами технологии наших сфер. $B$BПредставители Кенарийской экспедиции желают получить доступ к растениям, растущим внутри экосфер, в особенности к одному из них, именуемому \"кремовый колокольчик\" и известному своими целительными средствами. Густые заросли их встречаются вокруг более крупных растений в заповеднике \"Срединные земли\".$B$BЯ поделюсь с тобой доходами, если ты соберешь этой травки для первой партии товара.",
    O = "Соберите 15 \"кремовых колокольчиков\" и вернитесь к Мердаду на Заставу срединных земель.",
    T = "Новые возможности",
  },
  [10349] = {
    D = "Отнеси этот кусок хрусталя Галандрии, землепряду. Знаешь, вы с ней похожи. Все время пытаетесь что-то там расследовать и придумать.$B$BПо-моему, она слишком много думает.$B$BОтдай ей этот кристалл, и я даже не сомневаюсь, что она тут же нагрузит тебя работой. Будешь выяснять, что же там все-таки происходит.",
    O = "Отнесите осколок алого хрусталя землепряду Галандрии Ночной Бриз на Кенарийскую заставу на Полуострове Адского Пламени.",
    T = "Землепряд",
  },
  [1035] = {
    D = "Лихорадка Релары прошла, но она еще очень слаба. Я не верю, что только время вернет ей былую силу. Мне кажется, тут нужна мощь лунного камня.$B$BМы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники.$B$BИх предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты $Gдолжен:должна; отнять лунные камни у Оракула.$B$BИ, боюсь, для этого тебе придется его убить.",
    O = "Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар.",
    T = "Зеркало Небес",
  },
  [10350] = {
    D = "Хотя я многому тебя научила, пришло время передать тебя более умелому учителю.$B$BБехомат наставлял меня, когда я была совсем неопытным воином, и именно ему я хочу доверить твое обучение. Я уже сообщила о твоем прибытии, и он ждет тебя.$B$BТы отыщешь его в центре Террасы воинов, в самой высокой части Торгового ряда в Экзодаре.",
    O = "Поговорите с Бехоматом в Торговом ряду Экзодара.",
    T = "Бехомат",
  },
  [10351] = {
    D = "Должно быть, горных великанов привлекают сюда эманации этого гигантского кристалла, которые затем и сводят их с ума.$B$BВряд ли мы сможем убрать отсюда кристалл – он слишком велик, и уничтожить его тоже не получится. Но есть один способ заглушить его излучение.$B$BЯ создала Круг на гряде к северо-западу от кристалла. Опусти туда это семечко, и пусть его сила исцелит землю с помощью дождя, растений и насекомых.$B$BОстерегайся, $n, я чувствую чужеродное вмешательство... так не должно быть!",
    O = "Посадите Семя Возрождения в Круге землепряда, чтобы исцелить землю вокруг кристалла. После этого возвращайтесь к землепряду Галандрии Ночной Бриз на Кенарийскую заставу и расскажите о том, что получилось.",
    T = "Целительная сила природы",
  },
  [10352] = {
    D = "",
    O = "",
    T = "Пожертвование – шерсть",
  },
  [10353] = {
    D = "Араксес и я были отправлены в Ультрис два дня назад. Наша миссия: найти и уничтожить повелителя Бездны Арконуса. Мы проследили его до этой шахты и обнаружили, что он высасывает энергию из существ, обитающих в этом регионе.$B$BВо время последовавшей перестрелки мы с Араксесом потеряли друг друга из вида. И вот я застрял здесь, тяжело раненный. Наша миссия в опасности!$B$BЕсли ты сможешь избавиться от Арконуса, наше командование будет тебе признательно. В том случае, если ты возьмешься за эту миссию, я помогу тебе – дам тебе в охранники свое отражение.",
    O = "Посланник Иасикс, находящийся у входа в шахту Зеон, просит вас убить Арконуса Ненасытного и вернуться к командиру Амиру на заставу стражи Протектората в Пустоверти.",
