  [10416] = {
    D = "Чародейские фолианты – это вам не просто книжки про магию. В них содержится большая сила, и я научился сосредотачивать ее в одной-единственной чародейской руне.$B$BЕсли вам попадется чародейский фолиант, то я с радостью обменяю его на такую руну, но фолианты бывают только у очень могущественных существ. В Запределье ими обычно владеют эльфы крови, последователи Келя, но вообще эти книги могут попасться где угодно.",
    O = "Принесите чародейский фолиант Ворен'талю Провидцу в Шаттрат.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.",
    T = "Преобразование силы",
  },
  [10417] = {
    D = "Где бы Консорциум ни заявил о своем присутствии, мы приходим туда со своей технологией экосфер. Защитное поле позволяет нам работать в тщательно контролируемой благоприятной атмосфере, поскольку окружающая среда часто бывает враждебной. $B$BСуровые условия Пустоверти и обитающие здесь существа причиняют вред оборудованию, генерирующему наши сферы; в особенности пострадал генератор, находящийся к востоку отсюда. Я запустил там диагностику, надеясь понять, что можно сделать, дабы уменьшить ущерб. Не можешь ли ты снять показатели диагностики и доставить их мне?",
    O = "Заберите результаты диагностики и доставьте их Мердаду на Заставу срединных земель.",
    T = "Провести диагностику",
  },
  [10418] = {
    D = "Обыскивая район в поисках того, что причинило такой ущерб нашему оборудованию, я заметил детали генератора защитного поля на дне маленького озера к северу отсюда. Не знаю, почему кроколисков так заинтересовало оборудование, но мы должны устранить эту проблему.$B$BМнение Консорциума по этому вопросу ясно. Если дело доходит до выбора между оборудованием и кроколисками, животным придется уступить. Думаю, ты не откажешься взяться за это дело.",
    O = "Мердад, находящийся на Заставе срединных земель, просит вас убить 8 шипастых кроколисков.",
