  [10419] = {
    D = "",
    O = "",
    T = "Чародейские фолианты",
  },
  [1042] = {
    D = "Нет, у меня не сохранилось записей о пребывании Велинды Песни Звезд в Темнолесье... Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в таверне, если ты понимаешь, о чем я.$b$bА вот о волко-людях я слышал, и не раз. Только недавно Калор явился в город, неся целую связку их голов. Он работает на Карвинов, которые охотятся на демонов и прочих чудовищ. Поговори с Джонатаном, главой их дома.",
    O = "Поговорите с Джонатаном Карвином в Темнолесье.",
    T = "Семья Карвин",
  },
  [10420] = {
    D = "Этот храм – одно из самых священных мест в Запределье. Сила Света здесь настолько велика, что может очистить предметы, сильнее других пострадавшие от Скверны.$B$BЕсли тебе попадутся латные перчатки Скверны, – а это наверняка произойдет после нескольких схваток с демонами, – принеси их мне, и я продемонстрирую тебе всю очищающую силу Света.",
    O = "Принесите латные перчатки Скверны Ишане в Шаттрат.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.",
