  [10548] = {
    D = "Помнишь – я рассказывала тебе о том жирном торговце, что искал это кольцо? Как оказалось, за кольцом охотился его сын-археолог, и кончил он не слишком хорошо. То есть его убили, отрезали голову и засушили ее.$b$bИ пусть это звучит цинично, расчетливо и даже жестоко, но торгаш готов отвалить кучу денег за голову сына. Работа как раз для тебя!$b$bСтупай на восток, пока не упрешься в развалины тролльских поселений Зеб'Тела и Зеб'Нова. Ты $Gдолжен:должна; найти ее в одном из тамошних сундуков.",
    O = "Эраланна из Транквиллиона просит вас найти усохшую голову археолога в одном из сундуков Зеб'Телы или Зеб'Новы.",
    T = "Горькая правда",
  },
  [10549] = {
    D = "Помнишь – я рассказывала тебе о том жирном торговце, что искал это кольцо? Как оказалось, за кольцом охотился его сын-археолог, и кончил он не слишком хорошо. То есть его убили, отрезали голову и засушили ее.$b$bИ пусть это звучит цинично, расчетливо и даже жестоко, но торгаш готов отвалить кучу денег за голову сына. Работа как раз для тебя!$b$bСтупай на восток, пока не упрешься в развалины тролльских поселений Зеб'Тела и Зеб'Нова. Ты $Gдолжен:должна; найти ее в одном из тамошних сундуков.",
    O = "Эраланна из Транквиллиона просит вас найти усохшую голову археолога в одном из сундуков Зеб'Телы или Зеб'Новы.",
    T = "REUSE",
  },
  [1055] = {
    D = "Воссозданный жезл у вас в руках. Шаэл'дрин захочет услышать о ваших успехах.",
    O = "Вернитесь к Шаэл'дрин у лунного колодца.",
    T = "Раэна – санитар Ясеневого леса",
  },
  [10550] = {
    D = "Я не лгал тебе. Это яйцо просто потрясающее. Где тебе посчастливилось его раздобыть?$B$BТеперь, если тебе понадобится еще кровопийка, ты знаешь, где меня найти и что мне надо.$B$BВот тебе пучок этой травы, отнеси ее своему покровителю.",
    O = "Отнести пучок Кровопийки Бораку сыну Оронока на мост возле Лагеря Затмения, в Долине Призрачной Луны. .",
