  [10646] = {
    D = "Ты $gдоказал:доказала; свою преданность, $n. Прости мне мою недоверчивость и подозрительность, но в этом мире опасно полагаться на первое впечатление – внешность часто бывает обманчива.$B$BКогда будешь $gготов:готова;, я расскажу тебе о Варедисе.",
    O = "Выслушайте рассказ Алтруиса.",
    T = "Ученик Иллидана",
  },
  [10647] = {
    D = "Разыскивается – МЕРТВЫМ:$B$BУварос – бич Долины Призрачной Луны.$B$BПо приказу властителя Ор'барокха, тварь скверны – Уварос – должен быть убит, а его грива отделена от тела в знак выполнения этого задания. Доставьте пламенеющую гриву этого чудовища военному глашатаю Сардону Чистому Удару – и вас ждет награда.$B$BВ последний раз Увароса видели возле Руки Гул'дана, в самом сердце Долины Призрачной Луны к востоку от Деревни Призрачной Луны.",
    O = "Убейте Увароса и доставьте его пламенеющую гриву военному глашатаю Сардону Чистому Удару в Деревню Призрачной Луны в одноименной долине.",
    T = "Разыскивается: Уварус, бич Долины Призрачной Луны",
  },
  [10648] = {
    D = "Разыскивается – МЕРТВЫМ!$B$BУварос – бич Долины Призрачной Луны.$B$BПо приказу тана Йорегара, тварь скверны – Уварос – должен быть убит, а его грива отделена от тела в знак выполнения этого задания. Доставьте пламенеющую гриву этого чудовища военному глашатаю Пивное Брюхо, и вас ждет награда.$B$BВ последний раз Увароса видели возле Руки Гул'дана, в самом сердце Долины Призрачной Луны к северо-востоку от цитадели Громового Молота.",
    O = "Убейте Увароса и доставьте его пламенеющую гриву военному глашатаю Пивное Брюхо в Цитадель Громового Молота в Долине Призрачной Луны.",
    T = "Разыскивается: Уварус, бич Долины Призрачной Луны",
  },
  [10649] = {
    D = "Меня радует твое желание остановить Варедиса и его последователей, но сейчас тебе с ним не справиться. Сначала нужно найти артефакт, который наделил Варедиса его силой.$B$BХодят слухи, что в Темном лабиринте в Аукиндоне есть некто по имени Черносерд Проповедник. Он владеет Книгой Имен Скверны. Только она поможет тебе противостоять Варедису.",
    O = "Проберитесь в Темный лабиринт в Аукиндоне и добудьте у Черносерда Проповедника Книгу Имен Скверны. После этого вернитесь в Награнд к Алтруису.",
    T = "Книга Имен Скверны",
  },
  [1065] = {
    D = "Нам придется прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании. Но только без кровопролития.$B$BУ одного моего коллеги может найтись то, что нам как раз для этого случая и нужно. Его зовут Лидон, он живет в городе Мельница Таррен в предгорьях Хилсбрада, в далеком краю Лордерон.$B$BЧтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород. Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад.$B$BНайди Лидона и передай ему эту записку. Там написано, что нам от него нужно.",
