  [10815] = {
    D = "В этом журнале описаны недавние действия армии Иллидана. Также в нем объясняется, почему Вал'зарек так демонстративно использовал Путь Завоевания. Ему был поручен захват верховного генерала Ша'тар.$B$BЭтот генерал находился в пункте известном как Кровавый Дозор, расположенном в южном конце Пути Завоевания. Таинственная группа, называющая себя Кровавая Печать, обвиняется в его похищении. Если ты решишь разузнать больше об этом деле, захвати с собой подмогу.",
    O = "Найдите Марка Аврелиона, верховного генерала Ша'тар, в Кровавом Дозоре.",
    T = "Записи Вал'зарека: Предвестье Войны",
  },
  [10816] = {
    D = "Ты неплохо себя проявил против Падших в Баа'ри, $n. Посмотрим, как хорошо ты сработаешь против, самого страшного, – армии Иллидана. $B$BОрки Скверны из клана Призрачной Луны занимают Террасу Ата'мала, когда-то священное место, где кристаллы Ата'мала использовались на жреческих церемониях.$B$BМы думали, они прячут этот кристалл где-то неподалеку, но наша разведка не дала никаких результатов. Однако Орки Скверны находятся на святой земле дренеев, и с этим нужно что-то делать!",
    O = "Убейте для воздаятеля Алуумена 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.",
    T = "Восстановление Святых земель",
  },
  [10817] = {
    D = "Ты неплохо $gпоказал:показала; себя против сломленных из племени Пеплоустов, $n. Теперь у меня для тебя новое задание. $B$BНе так давно Святилище Звезд захватили иллидановы орки Скверны.$B$BНам известно, что это совершили орки из клана Призрачной Луны, которые сейчас занимают Террасу Ата'мала.$B$BПокажи им, что с Провидцами шутить не стоит.",
    O = "Убейте для Варена Исправителя 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.",
    T = "Великое воздаяние",
  },
  [10818] = {
    D = "$n, пока ты демон знает где $Gгеройствовал:геройствовала;, сюда прилетал ручной дракон барона Черногрива с посланием.$B$BТребует тебя лично. Как я понял, он хочет, чтобы ты $Gпомог:помогла; ему в его личной разборке с гронном.$B$BПонятно, что лучше тебя в Запределье ему не найти для этого дела, Но на твоем месте я оповестил бы парочку друзей и назначил бы им встречу у Круга Крови.",
