  [1106] = {
    D = "Я разрабатываю новый двигатель, с которым мой болид помчится быстрее ветра! Помчится так, что даже сможет взлететь! Осталось мне сделать поршни, которые выдержат очень, очень высокое давление. Все мои испытания провалились потому, что я не смог сделать достаточно крепких поршней!$B$BНо есть тот, кто может мне помочь.$B$BЕго зовут Мартек Изгой. Он отличный кузнец и знает о металлах больше других. Вот, отвези ему это письмо, я знаю, он поможет мне!$B$BПравда, живет он далеко – в Азероте, в Бесплодных землях, в одном лагере с гоблином!$B$BНайди его!",
    O = "Отнесите письмо Пшикса Мартеку Изгою в Бесплодные земли.",
    T = "Мартек Изгой",
  },
  [11060] = {
    D = "",
    O = "",
    T = "Кристалл с темными рунами",
  },
  [11061] = {
    D = "Второй магический настой можно добыть только в одном месте: Лагере Баш'ира. Это база астральных духов и они не очень любят чужаков, дак что добыть ее будет немного опасно.$B$BТы спрашиваешь, где лагерь Баш'ира? Ну, если ты полетишь на северо-северо-восток, чтобы далеко обогнуть Лагерь Легиона: Гнев, ты в конце концов его заметишь. Хрустальная кузница Лагеря Баш'ира находится в его северо-восточном конце.$B$BСпасибо, что помогаешь нам, $n. Это много значит для наших сынишек!",
    O = "Добудьте нестабильный настой волшебника.",
    T = "Отцовский долг",
  },
  [11062] = {
    D = "$n, мы думали – не посетишь ли ты наших друзей на севере на заставе Стражи Небес?$B$BНебесный командир Келлер и его Стража защищают там всех нас, и он просит нас прислать кого-нибудь, кто, по нашему мнению, мог бы помочь нам.$B$BИ это будешь ты!$B$BИди туда как можно скорее и, пожалуйста, передай ему наш поклон.",
    O = "Поговорите с небесным командиром Келлером на заставе Стражи Небес на вершинах Острогорья.",
    T = "Застава Стражи Небес",
