  [11073] = {
    D = "Послушайте... Я не обращал внимания на все ваши разговоры с пленником араккоа, $n, потому что ваше с ним сотрудничество может принести нам пользу.$B$BВидите ли... Если бы я помог вам с призыванием Терокка, здесь бы вспыхнул настоящий мятеж.$B$BТак что возьмите все, что вам дал Хаззик и следуйте своему плану. Мои люди прикроют вас, когда потребуется, но советую и вам привести с собой помощников. Боюсь, второго шанса вам не представится.",
    O = "Возьмите приготовленное Хаззиком Подношение Затерянного во Времени и отнесите его к груде черепов в центре Скеттиса. С помощью подношения призовите Терокка и сразитесь с ним, после чего вернитесь к небесному командиру Адарису.",
    T = "Падение Терокка",
  },
  [11074] = {
    D = "Потомки, которых держат в плену жрецы когтя из Скеттиса, упомянуты в этой книге: Охотница Геззарак, хрустальный гигант Каррог, еретик по имени Темный Крикун Аккарай и Ваккиз Ветрояр. Для того чтобы Терокк вернулся в этот мир, нужно будет убить их всех.$B$BДля этого вам потребуются свитки затерянных во времени араккоа – с помощью свитков вы сможете призвать потомков в специальных кругах в Скеттисе. Принесите мне какую-нибудь вещь от каждого из них, но помните, что все они очень сильны, и лучше бы вам позвать с собой друзей.",
    O = "Добудьте у затерянных во времени араккоа их свитки и отнесите их к груде черепов в центре круга призыва в Скеттисе. Вызовите и победите потомков врагов Терокка, после чего отнесите Хаззику коготь Аккарая, хребет Гарокка, чешую Векказа и коготь Геззарака.",
    T = "Кровные враги",
