  [11121] = {
    D = "<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.",
    O = "Поговорите с <QUESTGIVER> в <AREA>.",
    T = "ЕЖЕДНЕВНОЕ ИСПЫТАТЕЛЬНОЕ ЗАДАНИЕ (РЕЙД)",
  },
  [11122] = {
    D = "Хочешь помочь нам на Хмельном фестивале? У меня есть отличное задание. Садись на скакового барана и дуй в Каранос. Мне надо прихватить там кой-какие бочки.$b$bНа холме рядом с грудой бочек тебя дожидается Флинн Огневар. Когда ты подойдешь поближе, он кинет тебе бочку. Тащи ее сюда и отдавай Полу Янтарлену. Больше одной бочки разом тебе не поднять.$b$b$gГотов:Готова;?",
    O = "Возьмите бочку у Флинна Огневара в Караносе и верните ее Полу Янтарлену. Если баран сбежит от вас, возьмите еще одного у Нейла Рамштайна.",
    T = "Туда и обратно",
  },
  [11123] = {
    D = "Бедняга Джеймс так и не оправился после пожара в \"Последнем привале\" и гибели семьи. Мы с ребятами делаем все, что в наших силах, чтобы найти ублюдков, ответственных за это.$B$BЯ послал нашего лучшего следователя, инспектора Тарема, на пепелище, но одному там не справиться. Если вы поможете Тарему, мы этого не забудем. Видит Свет, мы все хотели бы помочь.$B$BДо таверны можно дойти по главной дороге, только будьте поосторожнее. В такую глухомань мои патрули не заходят.",
    O = "Поговорите с инспектором Таремом в таверне \"Последний привал\".",
    T = "Inspecting the Ruins",
  },
  [11124] = {
    D = "Если ты пойдешь по дороге на юг от деревни, а затем свернешь на запад к Степям, ты найдешь пепелище таверны \"Последний привал\".$B$BТерамор направил туда следователя, чтобы разобраться, с чего бы это вдруг таверна сгорела. У меня есть наблюдатель в тех местах, к тому же, я не очень верю в то, что людям удастся раскрыть, что же там произошло.$B$BЧто бы ты ни $gразузнал:разузнала;, не смей рассказывать об этом следователю. Мы сами со всем разберемся.",
