  [11125] = {
    D = "",
    O = "",
    T = "[PH] Новые внутренние земли – задание",
  },
  [11126] = {
    D = "Хорошо, что я встретила тебя, |3-6($c). Я прибыла в Терамор, чтобы помочь разобраться с проблемой дезертирства. Солдаты покидают свои посты, вражеские агенты проникли в город!$B$BОни распространяют лживую пропаганду, надеясь, что и другие присоединятся к ним! $B$BАгенты буквально повсюду – у всех сторожевых постов в городе и доках. Нужно их найти, выявить и дискредитировать! Пока мы не можем сделать большего, иначе только вызовем к ним больше доверия.",
    O = "Прогоните 5 дезертиров-подстрекателей и вернитесь к докам Терамора к Калии Гастингс.",
    T = "Чужой среди своих",
  },
  [11127] = {
    D = "Я бы ни за что не стал воровать у моих кузенов Громоваров. Они отличные ребята. Но бизнес есть бизнес, порой приходится идти на крайние меры. Поэтому черную работу за меня делают другие.$b$bМрачнобух Громовар – это один придурок из этого семейства. Он живет к югу от Луноречья, в холмах Западного Края. Ходят слухи, что Мрачнобух придумал новый рецепт эля. Я хочу заполучить его еще до выхода продукта на рынок. Ты ведь сможешь его добыть? А уж за мной не заржавеет. Ячменовары всегда платят по счетам.",
    O = "Украдите тайный рецепт Мрачнобуха из лагеря Мрачнобуха в Западном Крае и отнесите его Ячменовару на территории Хмельного фестиваля.",
    T = "<NYI>Тайны Громопойла",
  },
  [11128] = {
    D = "Вражеские агенты не просто заводят случайные беседы со стражниками. Мы нашли множество листовок с призывом к дезертирству, которые эти агенты умудрились провезти на корабле в доки.$B$BКорабль, что привез листовки, еще стоит в Тераморе, в дальнем доке. Если бы тебе удалось проникнуть на борт и выкрасть оставшиеся пропагандистские листовки, то их агенты утратили бы свое самое мощное оружие. Осторожнее! Команда – опытные каперы. Груз, скорее всего, держат в капитанской каюте.",
    O = "Доставьте дезертирскую пропаганду Калии Гастингс к докам в Тераморе.",
    T = "Пропагандистская война",
  },
  [11129] = {
    D = "Помоги мне, $n! Мой любимый щенок Кайл сбежал! Я знаю, он потерялся и теперь бегает вокруг деревни Кровавого Копыта, голодный и несчастный.$B$BПожалуйста, отыщи его и покорми. Он поест, утешится и вернется домой.$B$BНо сначала надо найти для него еду. Его любимое блюдо – нежное мясо долгоногов. Отправляйся на восток, там их – хоть пруд пруди. Убей одного из них и принеси его сочное мясо Кайлу. Как увидишь Кайла в городе – предложи ему мясо, и он непременно подойдет к тебе.",
    O = "Анаб Пшеничная Грива из деревни Кровавого Копыта в Мулгоре попросил найти его лучшего щенка, Кайла Бесноватого.$B$BПокормите Кайла нежным мясом долгонога и возвращайтесь к Анабу Пшеничной Гриве.",
    T = "Пропал Кайл!",
  },
  [1113] = {
    D = "Зачем мне редкий вид гуано, спросишь ты. Отвечаю. Я хочу выяснить в ходе эксперимента, какое воздействие окажут друг на друга два диаметрально противоположных химических вещества, особенно если оба смешать с токсичным реагентом, чтобы результаты были... погаже.$b$bВ северо-восточной части Тирисфальских лесов располагается Монастырь Алого ордена. В его стенах и за их пределами живут ненормальные последователи Алого ордена. Кого из них ты убьешь – меня не волнует, у всех могут быть нужные мне сердца.",
    O = "Опытный аптекарь Фаранелл из Подгорода просит принести ему 20 сердец Доблести.",
    T = "Сердца Доблести",
  },
  [11130] = {
    D = "Ходи сюда, $Gпарниша:лапуля;! Дай старине Жулю посмотреть на твои блестяшечки...$b$bХммм. Да-да, неплохо, но ты можешь добыть больше. Куда больше.$b$b*Жуль наклоняется к вам и шепчет.*$b$bСлавные блестяшечки – они повсюду, $n, только надо знать, где искать! Нынче тебе свезло так свезло – я знаю парня, который поможет тебе найти столько блестяшек, что и не унесешь.$b$bЗайди к моему старому приятелю, Бадду – он болтается близ Зул'Амана, и покажи ему вот это. Он поймет, что тебя послал старый Жуль, и он тебя посвятит в свою затею.",
    O = "Жуль хочет, чтобы вы взяли его записку и отнесли ее Бадду в Призрачные земли к Зул'Аману.",
    T = "Ой, блестяшечки!",
  },
  [11131] = {
    D = "Вы должны помочь нам! Всадник без головы напал на деревню! Кругом пожар! Дети в опасности!$B$BПожалуйста, $n, помогите пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!",
    O = "Переодетая попечительница сирот просит вас помочь потушить пожар в деревне. Когда пожар будет потушен, снова поговорите с попечительницей сирот.",
    T = "Гаси пожар!",
  },
  [11132] = {
    D = "Мои изыскания подтверждают слухи об огромном сокровище, спрятанном в Зул'Амане. Там для каждого найдется своя гора золота с холмиком! Но сначала ты $gдолжен:должна; заработать свою долю в этом пироге.$b$bНаша первая попытка достать эти сокровища пошла не так гладко, как я надеялся. Фактически, моя карта и те неумехи, которым я ее вручил, пропали без вести. Они отправились за троллем по имени Налоракк.$b$bЗабудь об этих неудачниках, мне нужна карта! Добейся успеха и ты войдешь в историю как тот, кто помог Бадду Недреку раскрыть тайны Зул'Амана.",
    O = "Разыщите карту Бадда Недрека на террасе верховного шамана Налоракка в Зул'Амане и верните ее хозяину.",
    T = "Все обещаешь и обещаешь",
  },
  [11133] = {
    D = "Я кое-что изменила в листовках, которые вы похитили у наших заклятых друзей в доках. Теперь любой, кто их прочтет, будет совершенно по-другому смотреть на них и их цели.$B$BЕсли мы подкинем побольше этих листовок страже, врагам будет очень нелегко снова угнездиться в наших стенах.$B$B<Калия вручает вам стопку подправленных листовок.> $B$BНе займетесь ли этим, пока я обдумываю очередной шаг?",
    O = "Калия Гастингс просит вас всучить подправленные листовки 6 тераморским стражникам. После этого вернитесь к Калии и доложите о выполнении задания.",
    T = "Дискредитация вражеской агентуры",
  },
  [11134] = {
    D = "Теперь, когда мы выжили вражеских подстрекателей из Терамора, пора закончить операцию. Мои местные осведомители доносят, что база вражеской агентуры находится на судне, вставшем на якорь у маленького острова к юго-востоку от доков.$B$BЕсли арестовать их лидера, Гависа Серого Щита, остальные сопротивляться не станут. Найдите его на борту и убедите сдаться. Скорее всего, для виду он немного побрыкается. Но когда поймет, что ему не светит, непременно покорится.",
    O = "Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора.",
    T = "Конец вражеской пропаганде",
  },
  [11135] = {
    D = "Ты $gпрогнал:прогнала; Всадника без головы, но пока существует Тыквовин, он будет возвращаться. Прошу тебя, $n, положи конец нашим несчастьям! Сил больше нет выслушивать безумные причитания Всадника! Сразись с ним, пока голова еще сидит на его плечах!$B$BОн покоится в Покинутом дворе Монастыря Алого ордена в Тирисфальских лесах. Найди его святилище тыквы и скажи такие слова:$B$BВсадник, встань$BПришла пора$BУмереть в последний раз!$B$BИди же, $n. И да пребудет с тобой Свет.",
    O = "Найдите святилище тыквы Всадника без головы.",
    T = "Всадник без головы",
  },
  [11136] = {
    D = "Донесения наших патрулей в последнее время приобретают тревожный характер. В них говорится о людях в красных банданах Братства Справедливости, что появились на Побережье Мрака, к северу от стен Терамора.$B$BОбломки корабля, найденные в тех местах, говорят о том, что они могли попасть сюда в результате кораблекрушения, но у нас слишком мало информации. Капитан Ваймор на Сторожевом посту – сторожевой башне к северу от города – ждет помощи в расследовании.",
    O = "Отрапортуйте капитану Ваймору на Сторожевом посту.",
    T = "Тревожные события",
  },
  [11137] = {
    D = "Мои разведчики донесли о кораблекрушении на северо-востоке побережья. Кораблекрушения здесь – дело обычное, но донесения говорят о том, что выжившие носят красные банданы Братства Справедливости!$B$BОни ремесленники и цеховики, но не мореходы. Что они делают на месте кораблекрушения на континенте, который не представляет для них интереса?$B$BГоворят, их предводитель живет на большом острове недалеко от побережья, к северо-востоку от города. Убей его и принеси все документы, какие удастся найти.",
    O = "Добудьте приказы Братства Справедливости у Гарна Маферса и принесите его капитану Ваймору на Сторожевой пост.",
    T = "Defias in Dustwallow?",
  },
  [11138] = {
    D = "Судя по формулировке добытого тобою приказа, создается впечатление, что первой целью Братства Справедливости будет найти и обезопасить тот самый непонятный груз.$B$BНа ШРУ в Тераморе одно время работал некий ныряльщик, занимавшийся подводными поисками, по имени Ренн Макжабр. Услышав о кораблекрушении, Ренн направился на север, чтобы заняться подводным поиском у острова, где нынче засело Братство Справедливости.$B$BЕсли мы хотим опередить бандитов, нам понадобится его помощь. Ищи Ренна в воде к северо-востоку от островка, прямо к северу от того большого острова, на котором ты уже $gуспел:успела; побывать.",
    O = "Доставьте приказы Братства Справедливости Ренну Макжабру к Побережью Мрака.",
    T = "Renn McGill",
  },
  [11139] = {
    D = "Дно отсюда до Алькаца усыпано обломками кораблекрушений. Братство Справедливости уже наняло ныряльщиков, которые рыщут по соседству. Мы добудем их снаряжение, оденем тебя и начнем охоту, но сначала придется кое-что \"позаимствовать\".$B$BПоищи на этом острове ящик со снаряжением для подводного плавания и что-нибудь для его починки. Когда все найдешь, неси мне, и я за минуту подготовлю тебе костюмчик!",
    O = "Принесите набор инструментов и поврежденное снаряжение подводника Ренну Макжабру в Пылевые топи.",
    T = "Secondhand Diving Gear",
  },
  [1114] = {
    D = "Ну вот, у меня есть все, что нужно. Осталось только отнести эти детали Пшиксу Медноштифу. Он уже давно их ждет – полагаю, он даже не заметит отсутствие одной маленькой детальки. Не стоит даже упоминать, что я ее забрал.$B$BЭта деталька совсем маленькая и ненужная.$B$BПравда-правда.",
    O = "Отнесите хрупкие детали машины Пшиксу Медноштифу на Мерцающую равнину.",
    T = "Заказ гномов",
  },
  [11140] = {
    D = "В общем, починил я тебе это снаряжение, так что некоторое время под водой продержишься. Но особо на него не рассчитывай.$B$BОбломки корабля разбросаны по дну – от самого восточного берега этого острова до Алькаца. Покуда хватит воздуха в водолазном шлеме, можешь искать под водой обломки между этим островом и Алькацом. Возьми этот набор для спасения имущества. Не подплывай слишком близко к Алькацу. Тамошние гидры – просто жуть!",
    O = "Принесите 6 поднятых со дна сундуков Ренну Макжабру в Пылевые топи.",
    T = "Recover the Cargo!",
  },
  [11141] = {
    D = "Вы должны безотлагательно оповестить леди Джайну о том, что нам удалось узнать! Бандиты перевозили пленника, и мы не знаем, кто это и жив ли он или она до сих пор!$B$BНо в одном нет сомнений, $n. Эти бандюги в петлю по мелочам не полезут. Наверняка их пленник – очень важная персона. Леди Джайна должна знать об этом больше, чем кто-либо другой. Найди ее на вершине башни магов в центре Терамора.",
    O = "Поговорите в Тераморе с леди Джайной Праудмур.",
    T = "Jaina Must Know",
  },
  [11142] = {
    D = "Похоже, догадка Ренна насчет острова Алькац оказалась верной. Нам надо обследовать этот остров, но, чтобы пробиться туда, потребуется целый вооруженный отряд.$B$BОборона Терамора сейчас не может позволить себе такую роскошь, поэтому я договорилась с Коссой Багровое Крыло, ученицей тераморского укротителя грифонов, чтобы она дала тебе одно из своих животных для обследования Алькаца с воздуха.$B$BТолько на острове Алькац можно найти намек на то, что Братство Справедливости причастно к похищению.",
    O = "Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе.",
    T = "Survey Alcaz Island",
  },
  [11143] = {
    D = "Я говорил с инспектором Таремом по поводу информации, добытой вами в развалинах таверны \"Последний привал\". Похоже, он уверен, что следы копыт и найденный вами там щит указывают на тауренский клан Зловещий Тотем.$B$BС учетом донесений об их активности на болотах, это вряд ли можно считать простым совпадением. Я отправляю тебя к капитану Дариллу, он у нас что-то вроде специалиста по делам этого клана. Ступай по дороге на север из города к Северной башне. Это вторая застава на дороге.",
    O = "Отрапортуйте капитану Дариллу в Северной башне.",
    T = "A Grim Connection",
  },
  [11144] = {
    D = "Пусть Зловещий Тотем и самое воинственное из тауренских племен, в организованности им не откажешь. Если таверну \"Последний привал\" подожгли действительно они, приказ об этом мог отдать лишь один из старейшин племени.$B$BНа северо-западе находится одно крупное поселение Зловещего Тотема, деревня Черного Копыта. Она служит им базой для нападений на нашу башню, но я готов поспорить, что там ты найдешь нужную информацию. Планы нападения должны были сохраниться у старейшин деревни.",
    O = "Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню.",
    T = "Confirming the Suspicion",
  },
  [11145] = {
    D = "Мы делаем все возможное, чтобы припереть к стенке этих налетчиков из племени Зловещего Тотема, но они продолжают нападать на город. Хуже того – они умудряются обнаруживать и захватывать в плен патрули, которые капитан посылает вести разведку и охранять дорогу.$B$BДумаю, что пленников держат в деревне Черного Копыта, что к северо-западу отсюда. Насколько мне известны повадки этих тауренов, наверняка ключи от камер пленников держат при себе охранники деревни. Мне все равно, что ты будешь делать, |3-6($c), просто спаси моих людей.",
    O = "Сержант Лукас из Северной башни просит вас спасти 5 тераморских пленников.",
    T = "Prisoners of the Grimtotems",
  },
  [11146] = {
    D = "Полоса болот к северо-востоку отсюда – гнездо особенно мерзких ящеров. Из-за них мы потеряли уже не одного беспечного солдата, и у меня появилась мысль натравить зверей на наших соседей из клана Зловещего Тотема.$B$BВозьми эту веревку и поймай с ее помощью несколько ящеров Кровавой Топи или крикунов Кровавой Топи. Впрочем, я бы не стал пытаться ловить этих тварей, пока не удастся хотя бы немного ослабить их в бою. А бой будет нешуточный.",
    O = "Сержант Лукас из Северной башни просит вас поймать 6 ящеров. Вы можете ловить как ящеров Кровавой Топи, так и крикунов Кровавой Топи.",
    T = "Raptor Captor",
  },
  [11147] = {
    D = "Теперь, когда у нас есть ящеры, следующий наш шаг – \"уговорить\" их напасть на неугодное нам племя в деревне Черного Копыта к северо-западу отсюда.$B$BУ меня тут осталось немного вырезки из... неважно, из кого. Это будет твоя приманка. Положи ее на землю у ветряной мельницы посреди деревни. А об остальном позаботятся ящеры, по крайней мере, я на это надеюсь.",
    O = "Сержант Лукас из Северной башни хочет, чтобы вы положили приманку на ящера близ ветряной мельницы в деревне Черного Копыта.",
    T = "Unleash the Raptors",
  },
  [11148] = {
    D = "Если снаряжение, которое ты $gобнаружил:обнаружила; в развалинах таверны, принадлежало воинам Зловещего Тотема, то наверняка в их лагере к северо-западу отсюда найдется еще больше.$B$BНам не удалось собрать достаточно информации о деревне Черного Копыта, но, судя по численности нападавшего отряда, там базируются значительные силы.$B$BСделай все, чтобы заполучить их снаряжение и сравнить с найденным в развалинах таверны.",
    O = "Капитан Дарилл из Северной башни хочет, чтобы вы принесли ему 7 предметов вооружения из деревни Черного Копыта.",
    T = "Arms of the Grimtotems",
  },
  [11149] = {
    D = "Я не могу выделить никого в помощь второй заставе клана Зловещего Тотема, но, кажется, знаю, кто может помочь вам. $B$BВ самом сердце Трясины, к югу отсюда, находится маленькая усадьба, владеет которой Табета. Она может показаться просто старой отшельницей, но на самом деле она волшебница и провидица, причем небезызвестная. Идите по дороге на юг до ее усадьбы и попросите помощи в поиске тех, кто ответственен за резню в таверне \"Последний привал\".",
    O = "Поговорите с Табетой в ее усадьбе.",
    T = "Tabetha's Assistance",
  },
  [1115] = {
    D = "Ну вот, гномам услугу оказали, пора и гоблинам помочь!$B$BГоворят, что гоблинского пилота, Назза Парового Котла, раньше звали не так. Интересно, почему он сменил имя? Наверное, это секрет, и, скорее всего, он дорожит этим секретом.$B$BЕсли кто и знает правду, то только Кразек из Пиратской Бухты, на южном мысу Тернистой долины. Поговорите с Кразеком и разузнайте у него про нашего пилота-гоблина.$B$BЕсли вам удастся добыть у него ценную информацию, то мы все сможем извлечь из нее прибыль.",
    O = "Поговорите с Кразеком в Пиратской Бухте, что в Тернистой долине.",
    T = "Сплетник",
  },
  [11150] = {
    D = "Незачем гадать, чтобы увидеть угрозу, которая исходит от моих \"соседей\". И если это та самая банда, что сожгла \"Последний привал\", как ты говоришь, то нужно действовать немедля.$B$BБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы, возле дороги. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.",
    O = "Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.",
    T = "Raze Direhorn Post!",
  },
  [11151] = {
    D = "Хотя, по мне, этот Зловещий Тотем – мухи надоедливые, не более, капитан Ваймс пожелает узнать о ваших делах. Отнесите ему известие, что вы выследили тех, кто замешан в сожжении таверны \"Последний привал\", и разобрались с ними.$B$BСемье Джима Хьяля это уже не поможет, но хоть в Зловещем Тотеме сто раз подумают, прежде чем лезть на тех, кого защищает Терамор.",
    O = "Поговорите с капитаном Гарраном Ваймсом в Цитадели в Тераморе.",
    T = "Justice for the Hyals",
  },
  [11152] = {
    D = "Как бы дать знать жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?$B$B*Капитан Ваймс достает маленький венок.*$B$BГоворят, что души все видят, даже если мы и не можем говорить с ними. Это малость, но если бы вы возложили этот венок на могилу семейства Хьяль, я был бы вам очень благодарен. Это один из самых больших могильных памятников на кладбище к северу от ворот Терамора.",
    O = "Капитан Гарран Ваймс из Цитадели хочет, чтобы вы возложили венок к памятнику семейства Хьяль.",
    T = "Peace at Last",
  },
  [11153] = {
    D = "Все наши корабли затоплены! Нам нужна твоя помощь, чтобы прорваться сквозь пиратскую блокаду в Пролив Кораблекрушений!$B$BВозьми эти кассетные бомбы и садись на дирижабль, который \"одолжил\" нам Боронайзер. На нем ты пролетишь прямо над палубами этих проклятых пиратов и раздашь им наши подарочки!$B$BТы – наша последняя надежда прорвать блокаду. Надеюсь, тебе удастся разнести их корабли в мелкие щепки!",
    O = "Возьмите кассетные бомбы Петрова и сбросьте их на корабли, убив 25 матросов абордажной команды и уничтожив 10 абордажных пушек. Как только задание будет выполнено, вернитесь к бомбардиру Петрову в Крепость Западной Стражи.",
    T = "Прорвать блокаду",
  },
  [11154] = {
    D = "Эй, ты! Да, ты... иди сюда, мне нужна твоя помощь!$B$BПетров послал меня сюда собирать гуано летучих мышей для кассетных бомб, которые он мастерит в крепости, но я не собираюсь соваться прямо в лапы смерти!$B$BКороче, темнолапые летучие мыши водятся только на Вырубках к северу отсюда, но с этой платформы я сойду только в направлении дома!$B$BА вот ты... ты можешь совершить этот подвиг ради меня! Правда? Ну пожалуйста!!!$B$BВот, держи хлопушки. Основная мысль такова: бросаешь их рядом с летучими мышами, и они гадят от страха!",
    O = "Соберите 10 кусков гуано темнолапых летучих мышей и отнесите их инженеру Фекнату к Стальным воротам.",
    T = "Пусть обделаются от страха!",
  },
  [11155] = {
    D = "После всех этих таинственных исчезновений домашнего скота нам не мешало бы озаботиться припасами. Иначе хищные звери станут нашей последней заботой!$B$BПоскольку я тут несколько занята приготовлением пищи, тебе придется отправиться на восток и поохотиться на черпорогов. Именно их нежное мясо я хочу сегодня приготовить. $B$BСмотри, не попадись им на рога!",
    O = "Шеф-повар Дымкотел поручила вам добыть 6 кусков мяса черпорогов и принести их ей в Крепость Западной Стражи.",
    T = "Снова суп из черпорога?",
  },
  [11156] = {
    D = "Клан Зловещего Тотема там, на заставе Дикого Рога, наглеет день ото дня. По ночам часто слышно, как они горланят песни о своих деяниях против тех, кто пытается тут осесть.$B$BОни твердо намерены выгнать нас из усадьбы Табеты, хотя она тут воспитала целое поколение учеников. Мы защищали усадьбу как могли, но ученик Гарион во время последнего налета был ранен.$B$BСтупай на заставу Дикого Рога и убей всех Зловещих Тотемов, каких встретишь! Нападения надо остановить.",
    O = "Убейте 12 тауренов из клана Зловещего Тотема с заставы Дикого Рога и вернитесь к ученику Морланну в усадьбу Табеты.",
    T = "Direhorn Raiders",
  },
  [11157] = {
    D = "$n, такое поручение я могу доверить только тебе. Нужно уничтожить яйца протодраконов и детенышей протодраконов в горящем лесу на юго-востоке! $B$BС тех пор, как мы прибыли сюда, в Пылающем Гнездовье не стихают пожары. Должно быть, это результат действия какой-то ужасной магии. В последнее время ситуация ухудшилась, и мои люди опасаются, что в ближайшие несколько недель мы все окажемся в огненной ловушке!$B$BОтправляйся туда и устрани угрозу, уничтожив яйца и детенышей протодраконов.",
    O = "Уничтожьте 15 яиц протодраконов и 15 детенышей протодраконов, после чего вернитесь к капитану Адамсу в Крепость Западной Стражи.",
    T = "В тисках зла",
  },
  [11158] = {
    D = "Что, боишься Брогга, малютка |3-6($r)? Не бойся. Гоблины Шестермути друзья Броггу, да и ты можешь с ним подружиться.$B$BБрогг ушел из Деревни Гиблотопь, когда новый вождь не стал мстить черным драконам, которые разрушили дом Брогга и убили много его старых друзей. Брогг пришел сюда, чтобы упокоить души убитых друзей и отомстить за них, но ему нужна помощь. Для обряда Броггу нужны магические перья – как те, что носят ящеры логова Кровавой Топи, что к западу от города.",
    O = "Принесите 5 перьев Кровавой Топи Броггу в Шестермуть.",
    T = "Bloodfen Feathers",
  },
  [11159] = {
    D = "Брогг закончил тотем, который принесет покой душам его друзей. Когда пришли дракониды, они убили всех в клане Каменных Молотов, кто не успел убежать. Броггу и властителю Мок'Морокку удалось скрыться. Вместе с другими выжившими они планировали напасть на драконидов.$B$BОднако этого так и не произошло, и теперь духи мертвых клана Каменного Молота не дают покоя Броггу и остальным. Отнеси этот тотем на север, к руинам Деревни Каменного Молота, и поставь рядом со скелетами огров, чтобы привлечь к себе духов. Победи духов, чтобы дать им успокоение.",
    O = "Брогг из Шестермути просит вас дать покой 10 духам клана Каменного Молота.",
    T = "Spirits of Stonemaul Hold",
  },
  [1116] = {
    D = "Вытащить информацию из Назза – дело непростое, $n. Очень непростое. Но, раз уж вы ради этого приехали аж с Мерцающей равнины, то... не хотите ли попутешествовать еще немного?$B$BСобрали бы для меня кое-что, пока я буду связываться со своими источниками, а?$B$BХм... Что бы вам такое поручить? А, вот: сонная пыль с дракончиков из Болота Печали. Да, сонная пыль – это именно то, что мне нужно.$B$BПринесите мне ее, $n, а я взамен поделюсь с вами необходимой информацией.",
    O = "Принесите 10 щепоток сонной пыли Кразеку в Пиратскую Бухту. Сонную пыль можно собрать с дракончиков на Болоте Печали.",
    T = "Сонная пыль в болоте",
  },
  [11160] = {
    D = "Когда пришли драконы и отняли старый дом Брогга, огры Каменного Молота бежали и все бросили, даже знамя клана.$B$BБрогг знает, что знамя хранится глубоко в могильном кургане огров Каменного Молота, но теперь он зовется Огненное логово. Брогг должен получить клановое знамя, чтобы отомстить драконам, которые убили его друзей.$B$BДревний курган клана Брогга, Огненное логово, кишащее драконидами, находится на северо-западе от Шестермути. Знамя глубоко в пещере. Будь осторожнее, $n.",
    O = "Добудьте знамя Каменного Молота и принесите его Броггу в Шестермуть.",
    T = "Banner of the Stonemaul",
  },
  [11161] = {
    D = "Чтобы сделать тотем для обряда, Броггу надо получить сущность тех тварей, что убили его друзей. Ненависть и злоба врагов Брогга будет питать пламя его мести.$B$BВыследи Огнегривых пеплохвостов, разведчиков или губителей, и прикоснись тотемом Брогга к их трупам. Только умирая, драконид испускает свою сущность.$B$BТвари, которых ты будешь искать, кишат в Огненном логове, к северо-западу отсюда, и в руинах Деревни Каменного Молота на севере.",
