  [11164] = {
    D = "Привет, $gчувак:чувиха;, ты тут типа $gновенький:новенькая;? Сделаешь для меня одну штуку?$B$BБадд затеял обновить свои личины лесных троллей. Говорит, что уже почти закончил, не хватает одной небольшой детали... Клыков.$B$BМое умение снимать шкуры тут абсолютно бесполезно...$B$BПринесешь мне десяток их клыков, а, $gдруг:подруга;?",
    O = "Соберите для Пригмона 10 клыков лесных троллей в Зул'Амане и принесите их ему в лагерь Бадда в Призрачных Землях.",
    T = "Клыкастые всадники",
  },
  [11165] = {
    D = "Послушай, $gпарень:подруга;, старине Пригмону нужно, чтобы ты $gсделал:сделала; еще кое-что.$b$bМой никчемный кузен Зунгам не может выбраться из Зул'Амана. Но тем не менее он жив – прошлой ночью я видел в небе его сигнальную ракету!$b$bСтоило бы конечно, бросить его там, чтобы не втягивал меня в свои дела, но он мне должен нехилую сумму денег.$b$bТак что сделай, что можешь, спаси его шкуру и принеси мне должок!",
    O = "Найдите Зунгама и помогите ему выбраться из Зул'Амана.",
    T = "Тролль в стане троллей",
