  [11300] = {
    D = "До Олуфа можно добраться только одним способом – перебить всех остальных гладиаторов. Иначе нам никогда не вернуть тайнопись. Так что не медли – ступай в Круг Правосудия. Если тебе удастся получить тайнопись, принеси ее Глоренфелду ко входу в эти катакомбы. $B$BА что я? Ты обо мне не беспокойся! Самое главное – найти связующее звено, которое откроет тайну происхождения всего человечества!",
    O = "Победите гладиаторов в Круге Правосудия, сразитесь с Олуфом Неистовым и заберите у него древнюю тайнопись.$B$BОтнесите тайнопись Глоренфелду ко входу в Катакомбы Утгард.",
    T = "Поражение на ринге",
  },
  [11301] = {
    D = "Малтус уже рассказывал тебе эти бредни про пивные бочонки и спятивших дворфов? $B$BНет, я не отрицаю того, что дворфы сошли с ума, но таскать у них пиво – дурная затея.$B$BЧто нам действительно надо – это мозги. Много мозгов. Скоро мы разгадаем эту тайну и, возможно, найдем новый компонент для создания чумы.$B$BВозьми эту пилу, отправляйся в Шепчущую теснину и убей несколько дворфов. Потом распили их черепные коробки, вынь мозги и принеси их мне.",
    O = "Аптекарь Грик из Аптекарского поселка просит вас принести ему 12 мозгов спятивших исследователей.",
    T = "Мозги! Мозги!",
