  [11317] = {
    D = "Мы отправились в Вырубки потому, что мне было видение про моего друга, ворга по имени Улклык. Он звал на помощь, и потому ты $gдолжен:должна; его найти.$B$BК сожалению, ты не можешь ходить среди воргов и общаться с ними, но я могу тебя научить.$B$BСначала тебе придется изгнать свое внутреннее смятение путем медитации. $B$BДалеко на северо-востоке, на Вершине Ледяного Клинка есть святилище. К нему ведет единственная тропинка, начинающаяся от западного подножия горы.$B$BОтправляйся туда, очисти свой дух и возвращайся ко мне.",
    O = "Ведун Странник Туманов у Стальных ворот посоветовал вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.",
    T = "Очищение",
  },
  [11318] = {
