  [11570] = {
    D = "Замок на моей клетке выглядит не особо прочным, но глупо было бы пытаться бежать без посторонней помощи.$b$bНе подсобишь ли мне выбраться из этих пещер? Нельзя терять ни минуты, |3-6($r)!$b$bКогда вернешься в приют, пожалуйста, дай королю знать, что со мной все в порядке. Он наверняка вознаградит тебя!",
    O = "Проводите Лургглбра в безопасное место и вернитесь к королю Мргл-Мрглу в Приют Зимних Плавников, чтобы сообщить ему хорошую новость.",
    T = "Бегство из пещер Зимних Плавников",
  },
  [11571] = {
    D = "Чтобы помочь, тебе нужно научиться говорить на диалекте Зимних Плавников. В этом нам помогут силы природы и магии.$B$BВозьми эту пустую ракушку. На дне заполненного водой рва внизу обитает Скольдер – элементаль ярости воздуха и воды.$B$BКогда сразишь ее, воспользуйся ракушкой для того, чтобы уловить волшебный пар над ее останками. Принеси наполненную ракушку мне, и тогда я смогу передать тебе знание языка Зимних Плавников.$B$BТебе повезло – один друг научил меня заклинанию подводного дыхания, которое очень тебе пригодится.",
    O = "Наполните ракушку, которую дал вам король Мргл-Мргл, над останками Скольдер. Верните наполненную ракушку короля Мрглу-Мрглу в Приют Зимних Плавников.",
    T = "Обучение коммуникации",
  },
  [11572] = {
    D = "Вернись к Старейшине Атуику в Камагуа. Надо предупредить его и остальных об угрозе, надвигающейся на них с моря. $B$B<Орфус вздрагивает.>$B$BЧтобы добраться до него, воспользуйся Древним подъемником. Но умоляю тебя, поторопись!",
    O = "Доставьте тревожные известия старейшине Атуику в Камагуа.",
    T = "Возвращение к Атуику",
  },
  [11573] = {
    D = "Приветствую тебя, $gпутешественник:путешественница;. Я – Тупобивень из племени Калу'ак. Твой народ зовет нашу расу \"клыкарр\". Недавно меня с помощником послали разведать причину странных явлений на одной из наших охотничьих троп. Но стоило нам приблизиться к западному кладбищу, известному как Заградительный холм, как на нас напали отряды нежити. Мне повезло – я смог добраться до этого лагеря, но судьба несчастного Орфуса мне не известна.$B$BНе $gмог:могла; бы ты отыскать его? Мы расстались возле Древнего подъемника, что к юго-востоку отсюда. Иди вдоль обрыва и убедись, что с ним все в порядке.",
