  [11600] = {
    D = "Горло Вильяма перерезано чем-то острым.$B$BПри дальнейшем осмотре тела нашлась лишь единственная зацепка для Лериссы – воинское удостоверение на имя Вильяма Аллертона.",
    O = "Отнесите воинское удостоверение Лериссе в Крепость Отваги в Борейской тундре.",
    T = "Последние новости о Вильяме Аллертоне",
  },
  [11601] = {
    D = "Возможно, бедный мистер Аллертон все-таки поможет нам отыскать моего пропавшего брата!$b$b<Лерисса достает объемистую книгу, смахивающую на ту, куда записывают рекрутов.>$b$bНу да, я ее позаимствовала, и что такого? Посмотрим, какого числа он поступил на службу?$b$bВильям видел Тассариана в списке рекрутов. Значит, они поступили почти одновременно... вот он!$b$bОн записался в... отряд С? Все прочие воинские подразделения носят названия городов Альянса...$b$bА кто еще состоит в этом отряде? Где они сражаются? Нужно разузнать. Может, хозяину таверны что-нибудь известно?",
