  [11625] = {
    D = "Пятьсот лет назад Азшара заключила в подводную темницу существо по имени Левирот. А теперь эти варвары хотят уничтожить труды нашей королевы!$B$BОни заняли наш город и начали приносить в жертву моих братьев, чтобы пробудить его! Когда наги кончились, они принялись за клыкарров. Их духи не будут ведать покоя!$B$BЯ помогу тебе, потому что это так или иначе поможет мне утолить мою месть. Их капитан, Рагнар, обитает в глубине Руин Терзающего Бича, в северо-восточной их части. Он владеет золотым трезубцем. Принеси мне его!",
    O = "Отправляйтесь к дальнему северо-восточному краю Руин Терзающего Бича. Убейте Рагнара Драккарлунда, завладейте трезубцем Наз'жана, а затем отнесите его Вихье на берег Терзающего Бича.",
    T = "Трезубец Наз'жана",
  },
  [11626] = {
    D = "Раж Наз'жан был императором Терзающего Бича, когда был пленен Левирот. Сама Азшара благословила его трезубец так, что он убил бы чудовище, если бы оно попыталось бежать.$B$BТеперь он у тебя, |3-6($r). Хотя мне это претит, я все же отомщу этим жестоким великанам.$B$BВозьми трезубец и отправляйся в глубины под Терзающим Бичом. Там, под ближайшим к северной части берега айсбергом, ты и найдешь Левирота.$B$BВонзи трезубец в его плоть и убей его! Возвращайся потом к тому, кто тебя послал; а я не желаю больше никогда тебя видеть.",
    O = "Найдите Левирота в водах под айсбергом, плавающим у северной окраины Руин Терзающего Бича. Воспользуйтесь трезубцем Наз'жана, чтобы убить Левирота, и возвращайтесь к Каруку, ожидающему вас на севере берега Терзающего Бича.",
    T = "Посланник",
