  [11639] = {
    D = "Властитель отказывается позволить шаману исцелить мои раны. Он говорит, что это послужит мне хорошим уроком и даст мне время поразмыслить над моим провалом.$B$BНо ты можешь отомстить за меня и за тех, кто пал у Магмота!$B$BЯ знаю, что говорящая с духами хочет, чтобы ты $gотправился:отправилась; туда ради спасения предсказателя.$B$BЭто совсем недалеко, к востоку отсюда. Иди, |3-6($c)... иди, убей магнатавров и их прислужников-снобольдов. Восстанови честь заставы!",
    O = "Убейте магмотов: 10 шаманов, 5 добытчиков, 3 сокрушителя и 3 жен Магмотрегара. Затем возвращайтесь к Орторошу на заставу Бор'горока.",
    T = "Месть в Магмоте",
  },
  [1164] = {
    D = "Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$b$bВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. И теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$b$bСами вещи мне уже не нужны. Теперь я жажду мести!$b$bУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта.",
