  [1186] = {
    D = "Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите еще немного помочь нашей команде, поговорите с Раззериком. Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования.$B$BОн, правда, малость двинутый, так что не удивляйтесь, если что.",
    O = "Поговорите с Раззериком на Мерцающей равнине, что в Тысяче Игл.",
    T = "Восемнадцатый пилот",
  },
  [11860] = {
    D = "",
