  [11864] = {
    D = "",
    O = "",
    T = "Вступление",
  },
  [11865] = {
    D = "Прежде к югу от нас вольно бродили стада карибу. Но тут появился Эрнестуэй, и все изменилось. Теперь карибу не знают ни минуты покоя, они постоянно пребывают в панике. Их преследуют охотники, расставляющие в тундре свои ловушки...$b$bЭрнестуэевы палачи недостойны того, чтобы жить, но и умирать им еще рано. Пусть сперва на своей шкуре ощутят те страдания, на которые они обрекают карибу! $b$bВот, возьми эту охапку искусственных шкур и накрой ими ловушки для карибу, что расставлены на юге. Пусть охотники сами попадутся в свои смертельные капканы!",
    O = "Используйте охапку искусственных шкур, чтобы поймать в ловушки 8 звероловов Эрнестуэя по просьбе Зазы из лагеря Д.Э.Г.О.Ж. в Борейской тундре.",
    T = "Им рано умирать",
  },
  [11866] = {
    D = "Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти, и получите в награду благословение друидов Д.Э.Г.О.Ж.!",
    O = "Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду.",
    T = "Уши мертвых врагов",
  },
  [11867] = {
    D = "Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти, и тогда вы получите в награду благословение друидов Д.Э.Г.О.Ж.!",
    O = "Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду.",
    T = "Коллекция ушей",
  },
  [11868] = {
    D = "У южного края утеса – вот где ты найдешь коварную предводительницу охотников на карибу. Она – дикарка, каких поискать, издевается над телами убитых животных: пьет их кровь и воет потом на луну!$B$BНайди эту убийцу – ее зовут Карина – и положи конец ее никчемному существованию.$B$BПодготовься как следует, $n. Карина Сортировщица купается в богатстве, которое Эрнестуэй щедро излил на нее!",
    O = "По заданию Заза из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Карину Сортировщицу.",
    T = "Сортировщица грядет!",
  },
  [11869] = {
    D = "К западу от нас находится озеро Кум'уа. Это, насколько нам известно, единственный пресный водоем в мире, где обитают гигантские моллюски.$B$BКонечно, прихвостни Эрнестуэя занялись там культивированием жемчуга. Их нужно остановить! Тем, кто покушается на жизнь целого вида, нужно преподать урок.$B$BОтправляйся к озеру Кум'уа и найди этих загребущих ловцов жемчуга. Убивай их, пока воды озера не покраснеют от крови! Возвращайся, когда покажешь им, где раки зимуют!",
    O = "По заданию иерофанта Сениуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте 10 загребущих ныряльщиков.",
    T = "Судьба моллюсков",
  },
  [1187] = {
    D = "Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперед! А вот я не боюсь.$B$BПосле того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива!$B$BЯ заказал сефориевый ускоритель у Шрива. Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях! А мне он нужен, как воздух!",
    O = "Найдите сефориевый ускоритель для Раззерика на Мерцающей равнине.",
    T = "Доработка Раззерика",
  },
  [11870] = {
    D = "Мы только что получили сообщение от Лиандры, что наемники, работающие на Эрнестуэя, переносят добро с берега на главный корабль Эрнестуэя. Несомненно, они рассчитывают разбогатеть на своем убийственном ремесле!$b$bЛиандра просит, чтобы мы отправили помощь в Покинутый предел, к югу отсюда, на побережье Борейской тундры.$b$bТоропись, Лиандра ждет тебя!",
    O = "Найдите иерофанта Лиандру в Покинутом пределе.",
    T = "Покинутый предел",
  },
  [11871] = {
    D = "На берегу, среди обломков кораблекрушения, валяются ящики и мешки с частями тел животных. Похоже, Эрнестуэй в сговоре с флибустьерами Северных морей. Эти грязные пираты перевозят добычу, которую кровожадные прихвостни Эрнестуэя добывают на побережье. Несомненно, все это добро завершает свой путь на плечах не слишком щепетильных богатеев по всему Азероту!$b$bТак вот, не бывать этому! Во всяком случае, пока мы на страже! Принеси мне весь груз, какой найдешь на берегу. Они его не получат!",
    O = "Добудьте 12 партий частей тел животных по просьбе иерофанта Лиандры из Покинутого предела в Борейской тундре.",
    T = "Пока мы на страже",
  },
  [11872] = {
    D = "Специалист по моллюскам? Ишь ты! Знаем мы таких специалистов!$b$bОтыщи и убей его! В последний раз его видели на месте кораблекрушения у берегов Покинутого предела.$b$bА когда выполнишь это, возвращайся к иерофанту Сениус в лагерь Д.Э.Г.О.Ж., к северу отсюда, и сообщи ей, что дело увенчалось успехом.",
    O = "Убейте специалиста по моллюскам К и возвращайтесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж.",
    T = "Гнусный специалист по моллюскам",
  },
  [11873] = {
    D = "Не будешь ли ты так $gлюбезен:любезна; отправиться на взлетную полосу и сообщить Выкрутеню, что я скоро появлюсь и доложу обо всем, как положено? Мой ветролет потерпел крушение, я прибуду, как только разберусь с этим.$b$bНе сомневайся, я позабочусь о том, чтобы Выкрутень знал, что я обязан тебе жизнью и спасением.$b$bХотел бы я знать, что сделал бы старик, если бы сам летел с нами, как в старые добрые времена. Мне его изрядно недостает...",
    O = "Вернитесь на взлетную полосу Выкрутеня и поговорите с Выкрутенем Разгоняйло.",
    T = "Новости для Выкрутеня",
  },
  [11874] = {
    D = "",
    O = "",
    T = "Upper Deck Promo – Верховая ракета",
  },
  [11875] = {
    D = "Войска наступательной группировки Расколотого Солнца воспользуются любым преимуществом, чтобы разбить союзников Кил'джедена. Мои коллеги из Штормграда создали масла, при помощи которых можно усиливать оружие и доспехи наших воинов.$B$BГлавный компонент – пыль Пустоты – изобилует в Запределье, если знать, где искать. Любой мастер-травник, специалист по снятию шкур или горняк, знающий приметы, может собирать ее по ходу дела. Она может найтись во всех травах, рудах и животных Запределья.",
    O = "Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат.",
    T = "Обретение преимущества",
  },
  [11876] = {
    D = "Какие величественные звери, правда?$B$B<Латориус указывает на мамонтов северной тундры.>$B$BДень ото дня их число уменьшается. Демоны, называющие себя охотниками, убивают их ради забавы и богатства.$B$B<Лицо Латориуса перекашивается от гнева.>$B$BА этот плач просто сводит меня с ума, $n. Эти звуки приносит ветер: к нам взывают малыши-мамонтенки, попавшие в жестокие ловушки охотников.$B$BВозьми этот молот и сокруши ловушки. Освободи детенышей!",
    O = "По заданию верховного друида Латориуса в лагере Д.Э.Г.О.Ж. в Борейской тундре освободите 8 мамонтят с помощью уничтожителя ловушек Д.Э.Г.О.Ж.",
    T = "Помоги тем, кто не может помочь себе сам",
  },
  [11877] = {
    D = "Развивая наступление на Кель'Данасе, мы обнаружили, что прихвостни Кель'таса планируют контратаку. Отдав приказ эльфам крови Ярости Солнца, что базируются в Пустоверти, напасть на нашу операционную группировку в Запределье, он надеется, что мы отвлечемся от Солнечного Колодца и оттянем войска.$B$BМы не должны этого допустить, $n. На передовой каждый клинок драгоценен.$B$BОтправляйся в Пустоверть и захвати их военные планы. Они могут оказаться у любого эльфа крови Ярости Солнца. Удачи, $n.",
    O = "Лорд Торвос из Шаттрата хочет, чтобы вы захватили планы нападения клана Ярости Солнца.",
    T = "План нападения клана Ярости Солнца",
  },
  [11878] = {
    D = "Ты $gпомог:помогла; освободить детенышей, попавших в ловушку, но многие из них все равно погибнут. Понимаешь, оставшись без матери, эти детеныши вынуждены будут заботиться о себе сами.$b$bНо выход есть! У них остается надежда на спасение!$b$bК северу отсюда, на равнинах у берегов Жгучих прудов, пасется Ку'нок Чудовище, древний и мудрый мамонт. Возьми этого осиротевшего детеныша и отведи его к Ку'ноку. Он обо всем позаботится!",
    O = "Отведите мамонтенка-сироту к Ку'ноку Чудовищу в Борейской тундре.",
    T = "Ку'нок обо всем позаботится!",
  },
  [11879] = {
    D = "В одиночку тебе не удастся убить существо, виновное в гибели моих сородичей. Но мамонты из тундры помогут тебе!$b$bСтупай на равнины и найди там могучего самца мамонта. Он позволит тебе сесть на него верхом и управлять им.Он привезет тебя на север, в Гнездо Кау, где обитает Кау. Вместе вы сумеете покончить с этим чудовищем!$b$bИстреби воинство Кау и отбери у него его драгоценную боевую алебарду.$b$bЕсли одержишь победу – возвращайся к Латориусу в лагерь Д.Э.Г.О.Ж.",
    O = "Убейте Кау Грозу Мамонтов и добудьте боевую алебарду Кау. Доставьте ее верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж. в Борейской тундре.",
    T = "Кау Гроза Мамонтов",
  },
  [1188] = {
    D = "Постойте-ка, что это? Шрив оставил включенным режим безопасности. Но это же ограничит мощность, которую я смогу выжать из этого ускорителя! Говорил же я ему, чтобы отключил! Плохо, плохо.$B$BВам придется отнести это в Гизмориум Прибамбасска и заставить Шрива все отключить!",
    O = "Отнесите сефориевый ускоритель Шриву в Прибамбасск, что в Танарисе.",
    T = "Безопасность превыше всего",
  },
  [11880] = {
    D = "Я уверен, что этот \"гном-изобретатель\" – чокнутый. Он все болтал о каких-то темных искажениях, что стали проявляться на Полях Духов вокруг Ошу'гуна в Награнде.$B$BПо его словам эти, кхм, мультифазовые... кхм, спектрографические очки позволяют носителю видеть эти искажения и снимать с них данные. Он настаивал, что запись этих данных имеет фундаментальное значение для нашей кампании у Солнечного Колодца. Я думаю, он сумасшедший, но мне приказано исследовать все, что может помочь. Не хочешь ли провести считывание кое-каких данных?",
    O = "Предвестник Харонем из Шаттрата просит вас при помощи мультифазовых спектрографических очков 6 раз провести считывание мультифазовых данных.",
    T = "Мультифазовый подход",
  },
  [11881] = {
    D = "Доводилось ли тебе видеть в небе ветролеты? Любопытнейшая гномская новинка!$b$bДавненько мне хотелось наложить лапу на эти машинки, и вот, наконец, представился удобный случай это сделать! Один из их разведывательных отрядов потерпел катастрофу у Жгучих прудов, в юго-западной части Поля Гейзеров.$b$bСвистни в этот свисток у одной из разбившихся машин, и к тебе прибежит моя верная ослица Дженни. Она послушно пойдет за тобой следом и понесет на себе обломки, но тебе следует ее защищать. Если на нее нападут, она начнет ронять груз.",
    O = "Помогите ослице Дженни добраться с места крушения к Феззиксу Штукельверту в деревню Таунка'ле, не растеряв груз.",
    T = "Ценный груз",
  },
  [11882] = {
    D = "Хочешь научиться кое-чему новому?$b$bНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в искусстве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с мастером-огнеглотателем в любой столице Альянса. Они тебя научат.",
    O = "Поговорите с мастером-огнеглотателем в любой из столиц Альянса.",
    T = "Игра с огнем",
  },
  [11883] = {
    D = "Хочешь научиться танцевать с огнем?$b$bЧто же, хорошо. Поговори с мастером огненного танца в любой из столиц Орды. Они тебе помогут.",
    O = "Поговорите с мастером огненного танца в любой из столиц Орды.",
    T = "Танцы с огнем?",
  },
  [11884] = {
    D = "К западу отсюда, на высоких утесах над озером Кум'уа, обитает презренное создание, известное под именем Недар. Самозваный \"Повелитель люторогов\" охотится в пустошах на раненых и молодых животных – люторогов, неспособных защититься от трусливых атак Неда. Чтобы добавить оскорбительности к истреблению, Нед взрастил своего собственного люторога, который служит ему и как ездовое животное, и как телохранитель.$B$BБольшая редкость – чтобы от Д.Э.Г.О.Ж. исходил призыв к смерти животного, но с порченым люторогом просто необходимо разобраться... Убей обоих и возвращайся ко мне.",
    O = "По заданию Киллинджера Смотрителя Логова из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Недара, \"Повелителя люторогов\", и его спутника, люторога по кличке \"Закуска\".",
    T = "Нед, \"Повелитель люторогов\"",
  },
  [11885] = {
    D = "Потомки, которых держат в плену жрецы когтя из Скеттиса, упомянуты в этой книге: Охотница Геззарак, хрустальный гигант Каррог, еретик по имени Темный Крикун Аккарай и Ваккиз Ветрояр. Для того чтобы Терокк вернулся в этот мир, нужно будет убить их всех.$B$BДля этого тебе потребуются свитки затерянных во времени араккоа – с помощью свитков ты сможешь призвать потомков в кругах призыва в Скеттисе. Принеси мне какую-нибудь вещь от каждого из них, но помни, что все они очень сильны, и лучше бы тебе позвать с собой друзей.",
    O = "Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттиса, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.",
    T = "Кровные враги",
  },
  [11886] = {
    D = "Как говорится, потехе свой час, |3-6($c), но и делу время.$b$bКогда начался праздник, мы получили донесение с Зорамского взморья по поводу резкого усиления активности культа Сумеречного Молота. История праздника восходит к тем самым силам, которым эти безумцы поклоняются, так что это не совпадение. Отправляйся ко входу в Непроглядную Пучину – прямо к югу от него лежат руины. Посмотри, не сможешь ли ты получить какую информацию от этих фанатиков. Если понадобится – выбей ее силой. Когда понадобится помощь проводника, воспользуйся этим маячком.",
    O = "Отправляйтесь в новый лагерь культа Сумеречного Молота к югу от входа в Непроглядную Пучину на Зорамском взморье, что в Ясеневом лесу, и добудьте сумеречную корреспонденцию, затем при помощи тотема-маяка свяжитесь с проводником из Служителей Земли.",
    T = "Необычная активность",
  },
  [11887] = {
    D = "Роясь в вещах убитого гнома, вы находите небольшой мешок с припасами, инструментами и удобным рулончиком гномской клейкой ленты. Возможно, этот мешок пригодится Феззиксу Штукельверту, когда придется собирать из обломков гномские ветролеты.$b$bЕсли принести Феззиксу несколько таких мешков, можно получить приличную награду!",
    O = "Соберите 7 гномских ремонтных наборов с тел погибших пилотов-разведчиков со станции Выкрутеня и принесите их Феззиксу Штукельверту в деревню Таунка'ле.",
    T = "Неприкосновенный запас",
  },
  [11888] = {
    D = "$R, вождь заставляет меня ждать... Время – это то, чего у Таунка'ле нет!$B$BО твоем мастерстве ходят слухи. Чем ждать, пока Гаррош пошлет подкрепление, лучше я попрошу тебя пойти и помочь моим соплеменникам.$B$BДеревня Таунка'ле находится далеко на северо-восток отсюда. Езжай по дороге на восток от крепости, поверни на север на перепутье. Немного погодя ты наткнешься на еще одно перепутье. Следуй по пути на восток, пройдя к югу, а затем к востоку от больших прудов вдоль Затопленных равнин.$B$BКогда прибудешь в деревню, поговори с ведуном земли и неба.",
    O = "Поговорите с ведуном земли и неба в деревне Таунка'ле.",
    T = "Поездка в деревню Таунка'ле",
  },
  [11889] = {
    D = "Мы неплохо держимся на передовых линиях против этих жуков. Правда, кое-кто из этих нахальных тварей может перелетать те самые передовые линии, и они сильно терзают наши внутренние оборонительные порядки.$b$bЯ реквизировал укрепленные рыболовецкие сети с наших гражданских кораблей. Если руки у тебя приспособлены для метания, с помощью этих сетей можно сдернуть врагов с неба. Нужно уменьшить их количество, чтобы наши силы сумели удержать крепость.",
    O = "По поручению сержанта Молотогора убейте вне стен Крепости Отваги 6 порабощенных Плетью изрыгателей огня с помощью укрепленной сети.",
    T = "Смерть с небес",
  },
  [1189] = {
    D = "Вот, я сделал то, что просил Раззерик. Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперед, а превратится в кучку пепла на треке.$B$BА нам бы совсем не хотелось искать потом девятнадцатого по счету пилота!",
    O = "Верните модифицированный сефориевый ускоритель Раззерику на Мерцающую равнину, что в Тысяче Игл.",
    T = "Безопасность превыше всего",
  },
  [11890] = {
    D = "У гномов на прудах к западу отсюда возникли какие-то проблемы. Поделом им, конечно, ведь они всю землю уже изгадили своими так называемыми изобретениями.$B$BЯ хочу, чтобы ты $gотправился:отправилась; к их насосной станции и $gразузнал:разузнала;, что ж там с ними приключилось. А потом возвращайся, расскажешь.",
    O = "Исследуйте область вокруг насосной станции Выкрутеня, а затем возвращайтесь к ведуну земли и неба в деревню Таунка'ле.",
    T = "Что там с ними?",
  },
  [11891] = {
    D = "Судя по всему, похоже, что к северо-западу от большого скопления служителей культа на Зорамском взморье есть еще один их лагерь, и они разговаривают... с гостями?$b$bЕсли подслушать эти разговоры, то многое можно узнать, |3-6($r). Возьми эту сферу. Она поможет тебе принять вид одного из крабов, которых полно на побережье. Подслушай разговоры служителей культа с этими \"гостями\" в северо-западном лагере и, если все пройдет удачно, вернись ко мне и расскажи, что удалось узнать.",
    O = "При помощи сферы Краба проникните в новый Сумеречный лагерь к западу от входа в Непроглядную Пучину на Зорамском взморье в Ясеневом лесу, затем вызовите проводника из Служителей Земли при помощи тотема-маяка.",
    T = "Невинный маскарад",
  },
  [11892] = {
    D = "Ты много $gсделал:сделала; для животных Борейской тундры, $n. Тебе удалось как следует отделать прихвостней Эрнестуэя и преподать им урок, который они нескоро забудут.$B$BГарольд Лейн, в наибольшей степени ответственный за массовую бойню в Награнде, оказался тем же человеком, что отвечает за операции Эрнестуэя в тундре. Он расположился у озера Кум'уа, к западу отсюда.$B$B<Латориус передает вам покрытый причудливой резьбой дубовый рог.>$B$BНайди Лейна и убей его. Если понадобится наша помощь – труби в рог.",
    O = "По поручению верховного друида Латориуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Гарольда Лейна.",
    T = "Убить Гарольда Лейна!",
  },
  [11893] = {
    D = "Я все пытаюсь объяснить этому глупому гоблину, что его машины ненадежны.$b$bВот сила стихий – дело другое! И когда мое ученичество окончится, я овладею всей их мощью. Однако и того, что я уже знаю, будет достаточно, чтобы помочь нашему другу Феззиксу.$b$bВозьми этот тотем духа ветра и установи его вблизи одного из паровых яростней к западу от деревни. Тотем вберет в себя энергию убитых элементалей. Вернись ко мне с заряженным тотемом, остальное я беру на себя.",
    O = "Дорейн Морозное Копыто из деревни Таунка'ле просит вас использовать тотем духа ветра, чтобы собрать энергию 10 паровых яростней.",
    T = "Сила стихий",
  },
  [11894] = {
    D = "Помнишь ту клейкую ленту, что ты мне $gпритащил:притащила;?$B$BНу вот, я нашел ей применение. Корпус этого ветролета пробит в стольких местах, что мне нужно обязательно укрепить его, если я хочу хоть когда-нибудь на нем полететь.$B$BДорейн – вон он, там стоит, – сказал мне, что таунка используют для изготовления водонепроницаемых контейнеров пропаренную кожу карибу. Болотные карибу тут в округе, возле деревни, повсюду живут, да и на Затопленных равнинах их хватает. Найди наилучшие шкуры и выделай их над паром на Полях Гейзеров.",
    O = "Принесите 5 пропаренных шкур Феззиксу Штукельверту в деревню Таунка'ле.",
    T = "Заплатки",
  },
  [11895] = {
    D = "Из твоего описания следует, что с этими металлическими созданиями несложно будет справиться. Но сначала тебе нужно справиться с бурей.$B$BПозади меня на гряде есть тотем. Когда будешь $gготов:готова;, сосредоточь на нем свою волю – и грянет шторм. Ты $gдолжен:должна; одолеть шторм и таким образом вобрать в себя его сущность.$B$BЕсли там есть еще кто-нибудь, можете сражаться сообща, этого достаточно. А потом, |3-6($c), возвращайся ко мне.",
    O = "Одолейте порыв шторма, затем возвращайтесь к ведуну земли и неба в деревне Таунка'ле.",
    T = "Одолеть бурю",
  },
  [11896] = {
    D = "Ты теперь носишь в себе ярость шторма! Я научу тебя концентрировать эту силу, чтобы выводить из строя роботов в прудах.$b$bВот, возьми этот молниевый жезл. Используй его против роботов механогномов, которых найдешь среди прудов на западе. Против самих механогномов использовать его не трудись – у Великой матери Тайги другие планы на их счет.$b$bА когда сила бури ослабит роботов, разбери их полностью!",
    O = "Уничтожьте 15 любых роботов, кроме механогномов, ослабленных воздействием ярости шторма, в области прудов вокруг насосной станции Выкрутеня.$b$bПосле этого вернитесь к ведуну земли и неба в деревне Таунка'ле.",
    T = "Уязвимы для молний",
  },
  [11897] = {
    D = "Силы Плети и не собираются отступать, $n. Эти проклятые воронки: они соединены с туннелями на всем пути к леднику Ледяной Короны, насколько нам известно.$B$BЕсли годы занятий горным делом меня чему и научили, так это тому, что без опорных балок туннели легко обвалятся после взрыва.$B$BВозьми эту взрывчатку и установи заряды у входов в воронки на хребте над побережьем, к западу отсюда. Возвращайся, когда обвалишь туннели.",
    O = "По поручению сержанта Молотогора используйте зажигательную взрывчатку, чтобы взорвать и обвалить воронки к юго-западу и северо-западу от Крепости Отваги.",
    T = "Заткнуть воронки!",
  },
  [11898] = {
    D = "В нижнем ярусе Храмового города находится серый алтарь, окутанный светом. Ступи на него, и ты войдешь в некрополь Наксанар.$b$bНо будь осторожнее, $n! Принца Валанара наверняка обороняют его личные вассалы, которые готовы отдать жизнь ради того, чтобы не дать тебе взойти на вершину некрополя.$b$bТебе нужно пробраться через некрополь к трону принца. Если ты не сумеешь одолеть его, $n, боюсь, моему народу никогда не удастся укрыться в надежных стенах Ледяной Пыли...",
    O = "Одолейте принца Валанара с его подручными, Вантрином Безжалостным и Лютионом Злобным, потом явитесь к вождю Зимней Стуже в деревне Таунка'ле.",
    T = "Прорыв",
  },
  [11899] = {
    D = "Механогномы, живущие в прудах к западу отсюда, являются для нас полной загадкой. Они появились там вскоре после того, как с насосной станции и из ее окрестностей исчезли гномы.$b$bОни неестественны и опасны, и лучше, чтобы их не было вовсе.$b$bВозьми этот Ловец Душ и используй его на останках механогномов, чтобы взять их души в плен. Когда ты вернешься, мы выпустим их на волю и посмотрим, что будет.",
    O = "Используйте ловца душ Великой Матери, чтобы захватить души 10 механогномов со станции Выкрутеня. Затем вернитесь к Великой Матери Тайге в деревне Таунка'ле.",
    T = "Души распроклятых",
