  [11906] = {
    D = "<По лицу шамана скатывается слеза.>$b$bЯ знаю, ты направляешься обратно к прудам, что на западе. Раз уж ты все равно там будешь, у меня есть для тебя поручение.$b$bГномы, которых не волнует судьба земли, загрязнили ее своей техникой. Я прошу тебя собрать валяющиеся на земле запчасти.$b$bПринеси их мне сюда. Я позабочусь о том, чтобы они были утилизованы должным образом прежде, чем мы уйдем отсюда навсегда.",
    O = "Соберите 15 запасных деталей Выкрутеня и доставьте их Стальным Глазам в деревню Таунка'ле.",
    T = "Очищение прудов",
  },
  [11907] = {
    D = "Известно, что у механизатора Механозода имеется четверо подручных, которые управляют роботами в прудах.$b$bИх необходимо уничтожить!$b$bНаши выносливые гонцы и снежные следопыты говорят, что, если открыть клапаны на Западной, Северной, Центральной и Южной станциях, то эти подручные тут же явятся, чтобы устранить помеху в работе.$b$bСтанции расположены вокруг вращающихся маячков в прудах вокруг насосной станции.$b$bТоропись, $n!",
    O = "Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Ведуну земли и неба в деревню Таунка'ле.",
    T = "Подручные Механозода",
