  [1193] = {
    D = "",
    O = "",
    T = "Сломанная западня",
  },
  [11930] = {
    D = "Путь через Трансборею на восток – единственная возможность добраться до Драконьего Погоста. Множество опасностей поджидает тебя во время путешествия через тундру. Опасайся Плети и ее влияния на зверей, населяющих эти земли. Пошли слухи даже о наших братьях и сестрах таунка, поднятых из мертвых и нападающих на караваны на пути к Драконьему Погосту! Защищай свой караван и доставь беженцев в безопасное место!$B$BВартук Дитя Льда ждет тебя за мостом, ведущим на Драконий Погост.",
    O = "Проводите эвакуированных жителей Таунка'ле через Трансборею на границу Драконьего Погоста, где их ждет Вартук Дитя Льда.",
    T = "Через Трансборею",
  },
  [11931] = {
    D = "Я чувствую определенную странность в здешних драконах, но значение рун, нанесенных на их тела, по-прежнему ускользает от меня.$B$BБез кодекса их интерпретация займет слишком много времени.$B$BНедалеко отсюда обитает один предатель ордена Кирин-Тор, Калерас, у которого, вероятно, есть экземпляр той книги, что мне нужна. У его приспешников есть руны, которые мне понадобятся для расшифровки.$B$BПоторопись, $gсмертный:смертная;. С каждым мгновением сила Малигоса прибывает.",
    O = "Добудьте Лазурный кодекс у инквизитора Калераса и 3 мерцающих руны у его чароплетов Хладарры и отнесите Релоразу за Маскировочный щит.",
    T = "Взломать шифр",
  },
  [11932] = {
    D = "Послушай меня, $n. Не хочу никого обидеть, но операция, во главе которой поставили Тассариана, была чистым самоубийством!$b$bГорстке наших бойцов было поручено атаковать самое крупное объединение Плети в этом регионе!$b$bМожет, я и идиот, но, на мой взгляд, штурмовать зиккурат Плети рядом с зачумленным нерубским городом с отрядом в десяток бойцов – это даже не смешно.$b$bЕсли ты все еще хочешь отыскать Тассариана, можешь отправиться на восток к клыкарру по имени Атаика. Он живет в Каскале, на северо-востоке. Ну, удачи тебе в твоем безумном предприятии!",
    O = "Поговорить с Атаикой в Каскале, к северо-востоку от Крепости Отваги.",
    T = "Дураки и трусы",
