  [11942] = {
    D = "Так сказал лич, $n. Тайну входа в Наксанар хранят верховные жрецы из Эн'кила.$B$BОтправляйся к Шпилю Крови, Шпилю Боли и Шпилю Порчи и убей жрецов.$B$BВозвращайся, когда в твоих руках окажутся три свитка.",
    O = "По поручению Тассариана, который находится у Стонущего зиккурата, отправляйтесь в храмовый город Эн'кила и раздобудьте свиток верховного жреца Талет-Ха в Шпиле Боли, свиток верховного жреца Наферсета – в Шпиле Порчи и свиток верховного жреца Андората – в Шпиле Крови.",
    T = "Слова могущества",
  },
  [11943] = {
    D = "Ты $gобнаружил:обнаружила; фрагмент особой тюрьмы, $n.$b$bПодобные клетки подручные Малигоса используют для содержания пленных магов и иных магических существ, но эта тюрьма предназначалась для... для кого-то более могущественного.$b$bЕсть надежда, что враг нашего врага окажется другом. Отыщи оставшиеся фрагменты клетки.$b$bСкорее всего, они находятся в руках самых доверенных приверженцев Малигоса.",
    O = "Добудьте тюремную обшивку у генерала Церулеана и энергетическое ядро у завоевателя Кровозмея по просьбе Релораза из лагеря под Маскировочным щитом.",
    T = "Магическая клетка",
  },
  [11944] = {
    D = "Наша ситуация почти безнадежна. Нам дали приказ занять Стонущий зиккурат с горсткой воинов.$B$BНам очень повезет, если нам удастся удержать эту позицию и не сдать ее Плети. Нас превосходят числом, многие из нас ранены, а бежать в случае чего здесь некуда.$B$BЕсли ты сможешь немного помочь нам, мы, наверное, смогли бы укрепить нашу позицию. Если ты убьешь некоторое количество нежити вокруг постройки, мы сдержим их продвижение.",
