  [12227] = {
    D = "Держи слабительное, |3-6($r).$b$bУчти – оно срабатывает мгновенно, так что сначала отыщи отхожее место и запрись там покрепче.$b$bВсе, иди за желудями!",
    O = "Андерхол из Приюта Янтарной Сосны просит вас взять слабительную настойку Андерхола и воспользоваться ближайшим туалетом, чтобы извлечь частично переваренные янтарные желуди.",
    T = "За дело!",
  },
  [12228] = {
    D = "",
    O = "",
    T = "Возвращение магии [PH]",
  },
  [12229] = {
    D = "Не так давно мы отправили на восток экспедицию, которую растерзали бешеные фурболги. Единственный выживший рассказал, что видел странную темную жидкость, вытекавшую из тела убитого нападавшего.$B$BМногие тысячи лет фурболги жили в мире друг с другом и с окружающими. Мне кажется, что их агрессивность как-то связана с этой темной жидкостью и со зловещей силой, которую мы обнаружили ранее.$B$BПожалуйста, принеси мне несколько образцов крови фурболгов. Ты найдешь их в Святилище Красного Клыка и Святилище Кровавого Сердца, которые находятся на востоке.",
    O = "Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас принести 8 образцов крови безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка.",
    T = "Возможная связь",
  },
  [12230] = {
    D = "Мне поручено уничтожить баллисты Алого Натиска. К сожалению, мы с аптекарями расходимся во мнениях касательно использования имеющихся ресурсов, так что мне просто нечем их уничтожить!$B$BК северо-востоку отсюда находятся Поля Падальщиков. Осадные мастера Плети со своей кузницей и полными повозками мяса большие мастера разрушения.$B$BК счастью для нас, они оставляют без присмотра свои бомбы.$B$BЯ хочу, чтобы ты $gраздобыл:раздобыла; их для меня. И мне все равно, где ты их достанешь: поднимешь с земли или отберешь у осадных мастеров.",
    O = "По поручению Стража смерти Молдера из Ядозлоби раздобудьте 6 осадных бомб.",
    T = "Кража у осадных мастеров",
  },
  [12231] = {
    D = "Возможно, фурболгов Седых холмов затронула та же скверна, что заразила Фордрассил. Иначе я не могу объяснить, почему после стольких лет мира они оказались вовлечены в страшную, братоубийственную войну.$B$BНа востоке отсюда есть тщательно охраняемые святилища, которые стали домом отпрыскам Урсока.$B$BОстается лишь уповать на то, что порча не возымела действие на наследников бога, Кодиан и Орсонна.$B$BРазыщи их и выслушай, что они могут нам поведать.",
    O = "Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца.",
    T = "Отпрыски медвежьего бога",
  },
  [12232] = {
    D = "Наконец-то у нас появился шанс ударить по их осадным машинам! Не облажайся!$B$BШучу.$B$BОтчасти.$B$B$C, ты $gдолжен:должна; уничтожить баллисты Нового Дольного Очага с помощью этих бомб.$B$BМы покажем Королевскому фармацевтическому обществу, как это делалось в старые добрые времена! Никаких замысловатостей, никаких сложных рецептов!",
    O = "По заданию Стража смерти Молдера из Ядозлоби уничтожьте 5 баллист Нового Дольного Очага с помощью осадных бомб.",
    T = "Бомбардировка баллист",
  },
  [12233] = {
    D = "Нет, нет... Оставь их себе.$b$bТы же не думаешь, что я заберу из после всего, что ты с ними $gсделал:сделала;?$b$bСлушай; вот что мы теперь должны предпринять...",
    O = "",
    T = "[Depricated]Высадить семена",
  },
  [12234] = {
    D = "Мне нужно знать, что замышляют в Новом Дольном Очаге.$b$bУкради их сегодняшние приказы, чтобы я могла это выяснить.$b$bСтупай на юг и осмотри аббатство, казармы и побережье – найди их текущие планы действий!$b$bЕсли вдруг заблудишься, казармы – это такое здоровенное здание рядом с кузницей.",
    O = "Украдите текущие приказы Алого Натиска в аббатстве, в казармах и на побережье по просьбе главы шпионов Репайн из Ядозлоби.",
    T = "Надо знать",
  },
  [12235] = {
    D = "Лорд Фордрагон возглавил сокрушительную атаку на Артаса у Врат Гнева. За это Артас направил против нас Наксрамас. В то время как Кел'Тузад скрывается в парящей цитадели, его военачальник, Тельзан, осаждает крепость Стражей Зимы. Нижняя часть поселения уже потеряна, и надежда вызволить выживших тает с каждой минутой.$b$bДействовать нужно быстро! Срочно обратись к командиру грифонов Урику на грифоньей площадке! Он поможет тебе быстро добраться до места.$b$bСтупай!",
    O = "Поговорите с командиром грифонов Уриком на грифоньей площадке в крепости Стражей Зимы.",
    T = "Наксрамас и падение крепости Стражей Зимы",
  },
  [12236] = {
    D = "Время пришло, $n. Возьми этот пепел и принеси его фурболгу, о котором упоминала Кодиан. Если он отправился на поиски Урсока, то его следы должны привести тебя к логову на севере Седой Пасти.$B$BУвы, ты не справишься без его помощи. $gОдному:Одной; тебе никогда не одолеть Урсока.$B$BКак только вы одержите победу над Урсоком, воспользуйся этим пеплом, чтобы очистить его дух. Даже если его физическое тело будет уничтожено, душа должна быть спасена.",
    O = "Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила.",
    T = "Урсок, медвежий бог",
  },
  [12237] = {
    D = "При помощи этого свистка ты можешь призвать грифона Стражей Зимы. Взбирайся на него и направляйся к руинам деревни Стражей Зимы, ныне известным как Поля Падальщиков, на юго-восток отсюда. Когда доберешься до полей, смотри в оба и ищи беспомощных селян крепости Стражей Зимы. Когда заметишь кого-то из них, опускайся ниже и с помощью грифона подбери несчастного. Привези спасенного сюда, на грифонью площадку.$B$BТам повсюду кишат воины Плети, так что не зевай! Удачи!",
    O = "Спасите 5 беспомощных селян крепости Стражей Зимы и возвращайтесь к командиру грифонов Урику в крепость Стражей Зимы.",
    T = "Полет защитника Стражей Зимы",
  },
  [12238] = {
    D = "Скоро Драк'Тарон будет очищен от этой мерзкой нежити и засияет во всей своей былой славе, а ты в награду за свои великие деяния обретешь великое сокровище!$b$bКогда доберешься до самой вершины, призови меня, чтобы я провел ритуал. $b$bУвы, но тебе снова придется заплатить за мой призыв. Ты $gдолжен:должна;! будешь забрать моджо у выживших.",
    O = "Дракуру просит вас выпить эликсир возле его жаровни в Драк'Тароне. Для использования эликсира вам понадобится пять настоев терпения.",
    T = "Очищение Драк'Тарона",
  },
  [12239] = {
    D = "В рядах Алого Натиска у меня есть шпионка. Мне нужно, чтобы ты $gпередал:передала; ей дневное задание, чтобы она могла спланировать следующую фазу нашей атаки.$B$BОна откликается на имя агента Скулли и находится там под личиной кладбищенского смотрителя Алого Натиска.$B$BВот это задание, отнеси ей и сделай то, о чем она попросит. Кладбище находится рядом с аббатством.",
    O = "Доставьте текущие приказы Алого Натиска агенту Скулли в Новый Дольный Очаг.",
    T = "Шпион в Новом Дольном Очаге",
