  [12555] = {
    D = "Ну вот! Одна катапульта-сетемет готова, так что можешь сбивать этих сеятелей чумы.$B$BПросто целься и стреляй. Сети должны нейтрализовать заклинания, поднимающие их в воздух, так что они просто рухнут на землю, как это случилось с Колрамасом.$B$BЭто даже как-то поэтично... мне нравится!",
    O = "По поручению специалиста Зубоколеса из Драк'Сотры сбейте 5 сеятелей чумы с помощью катапульты-сетемета.",
    T = "Оплетающие сети",
  },
  [12556] = {
    D = "Теперь, когда мы знаем, где найти Фаранна, осталось только выйти на бой против этого великого люторога. Ответь мне, $n: $gготов:готова; ли ты прикончить его? Конечно, слухи многое преувеличивают; но я уверен, что сила Фаранна действительно огромна.$B$BЕсли решишься сразиться с этим люторогом, отправляйся на север: там, за Колонной Солнечного Благословения, на северо-восточном берегу Неспокойного озера ты найдешь Фаранна. Может быть, он даже до Мерцающей колонны дошел. Принеси мне его рог: это будет доказательством того, что люторог мертв.",
    O = "Принесите рог Фаранна Хемингу Эрнестуэю в его лагерь.",
    T = "Охота на люторогов: смертельный удар",
  },
  [12557] = {
    D = "Как я понимаю, ты хочешь, чтобы я взял тебя в $gученики:ученицы;.$b$bПохвальное стремление, очень похвальное... $b$bЕсли когда-нибудь я соглашусь, я должен быть уверен, что ты сумеешь сориентироваться в моей лаборатории. У меня тут хранятся различные ингредиенты. И в больших, и в малых количествах.$b$bДавай проверим тебя, |3-6($c). Найди грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.$b$bЕсли найдешь, я серьезно подумаю над твоей просьбой.",
    O = "Отыщите в лаборатории Финкльштейна грязную болотную личинку, иссохшее крыло нетопыря, янтарный желудь и замерзшую змеиную слизь.",
    T = "Лабораторная работа",
  },
  [12558] = {
    D = "Шанго ждет, $n. Если ты $gпреуспел:преуспела; в искусстве следопыта, он не узнает, что ты ведешь на него охоту – а это преимущество.$B$BГоворят, что он более силен, свиреп и велик, чем любой другой терропард. Отправляйся на север, к западному берегу озера Горьких Волн; там, подле водопадов, питающих озеро, ты найдешь Шанго и сразишься с ним. Если добьешься успеха, принеси мне его шкуру.",
    O = "Принесите шкуру Шанго Баку Кантвеллу в лагерь Эрнестуэя.",
    T = "Охота на терропардов: прыжок",
  },
  [12559] = {
    D = "Итак, время пришло. Пора активировать Связующую спираль.$B$BПервый переключатель можно отыскать в Обители Творцов в западной части низины. $B$BНо берегись, $n. Титаны использовали Обитель для наблюдения за своими созданиями. Многие из их каменных творений все еще охраняют это место.",
    O = "Аватара Фрейи с водопадов Гласа Дождя хочет, чтобы вы отправились в Обитель Творцов и воспользовались активационным переключателем \"гамма\".",
    T = "Включение Связующей спирали: Обитель Творцов",
  },
  [12560] = {
    D = "Мангровые кроколиски умеют подолгу таиться в засаде: тут у них есть чему поучиться. Так что давай-ка придумаем для тебя подходящую маскировку. Возьмем травы, растущие по песчаным берегам реки и у озера.$B$BЛучше всего для этой цели подойдет песчаный папоротник. Он растет на песках возле разлома Морского Потока на юге, у озера Горьких Волн и водопада Горьких Волн на севере, а также за мангровыми зарослями на востоке, у озера Слияние рек.",
    O = "Принесите 5 листьев песочного папоротника Дебаар в лагерь Эрнестуэя.",
    T = "Охота на кроколисков: план",
  },
  [12561] = {
    D = "Такого не должно было случиться. Силы смерти атакуют колыбель жизни!$B$BЕсли ты здесь не для того, чтобы уничтожить прислужников Короля-лича, тогда уходи. Не отвлекай меня от моих обязанностей. Не гневи меня.",
    O = "Завоюйте доверие Фрейи: уничтожьте 6 чумных трупов и 10 острокостных опустошителей в Затерянных землях.",
    T = "Вопрос доверия",
  },
  [12562] = {
    D = "По данным нашей разведки, как только на полях Драк'Сотры появились эти элементали воды, шаманы Драккари сразу спустились с верхних ярусов Зул'Драка, чтобы взять их под контроль.$B$BЭто крайне тревожные известия, $gгосподин:госпожа;. Нельзя допустить, чтобы они получили в свое распоряжение элементалей воды.$B$BКомандир приказал перебить всех водопрядов Драккари. Отправляйтесь на юг, как только будете готовы.",
    O = "По заданию младшего лейтенанта Джакса из Серебряной заставы убейте 10 водопрядов Драккари.",
    T = "Элементали не для Драккари",
  },
  [12563] = {
    D = "Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!",
    O = "Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк'Сотре, застава капитана Гронделя – в Драк'Агале, а застава алхимика Финкльштейна – в Хеб'Валоке.",
    T = "Тролльский дозор",
  },
  [12564] = {
    D = "Да, мои люди крепки и выносливы, но они все-таки смертные.$b$bРаны и боль выводят их из строя. Такова суровая правда жизни.$b$bНо, к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$b$bВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.",
    O = "Соберите 5 распустившихся водяных маков на полях Драк'Сотры для капитана Брендона из Драк'Сотры.",
    T = "Тролльский дозор: обезболивающее снадобье",
  },
  [12565] = {
    D = "Мне радостно видеть, с каким рвением ваш Серебряный Авангард разбирается с Плетью, |3-6($r). Я хочу вам помочь.$B$BРаньше тролли драккари из этого когда-то великого города регулярно приносили жертвы своим богам, но сейчас они уже не почитают богов так, как прежде.$B$BЕсли сделать богам щедрое подношение, в ответ боги одарят тебя своей милостью.$B$BИзваяние Зим'Абвы находится прямо на юго-западе. Зим'Абва с радостью примет в дар от тебя артефакты Драккари – в знак того, что ты защищаешь Зул'Драк.",
    O = "По поручению мастера проклятий Убунго принесите 10 подношений Драккари к изваянию Зим'Абвы.",
    T = "Благословение Зим'Абвы",
  },
  [12566] = {
    D = "Я – выносливый гонец Наник из племени таунка. Меня послал сюда вождь лагеря Заиндевевшего Копыта на поиски союзников, которые могли бы присоединиться к нашей войне с врайкулами. Враги осадили нас с запада и юга, но хотя на каждого павшего таунка приходится десять мертвых врайкулов, мы не в силах изгнать захватчиков с наших земель.$B$BАптекарь Силлис пообещал прислать нам на помощь отважных |3-8($c). Не желаешь ли ты протянуть руку моим братьям и сестрам?$B$BСледуй по дороге на северо-запад, пересеки реку, и ты увидишь Лагерь Заиндевевшего Копыта у подножия гор.",
    O = "Поговорите с вождем Прахтотемом в Лагере Заиндевевшего Копыта.",
    T = "Помощь Лагерю Заиндевевшего Копыта",
  },
  [12567] = {
    D = "",
    O = "",
    T = "Благословение Зим'Абвы",
  },
  [12568] = {
    D = "Поверь мне, |3-6($r). Я знаю...$b$bДаже меня, Отрекшегося, уже начинает подташнивать от запаха горелой плоти. Как бы там ни было, наш святой долг – проследить за тем, чтобы наши собратья не стали приспешниками Плети.$b$bПолей этой жидкостью тела наших павших товарищей, чтобы нам не пришлось встретиться с ними на поле боя уже как с врагами.",
    O = "По поручению капитана Руперта полейте 5 павших пехотинцев Серебряного Авангарда в Драк'Сотре маслом для сожжения.",
    T = "Тролльский дозор: смертельная усталость",
  },
  [12569] = {
    D = "Самый большой кроколиск в долине, прозванный Прогрызателем за умение выбираться из ловушек, любит греться на солнце на отмелях Слияния рек. Это такое большое озеро в центре долины, к востоку от нашего лагеря.$B$BЯ хочу, чтобы ты $gнадел:надела; камуфляж, который я для тебя приготовила, и $gустроил:устроила; засаду на западном берегу Слияния рек. Если тебе удастся прикончить Прогрызателя – в чем я лично сомневаюсь, – принеси мне его челюсть.",
    O = "Принесите челюсть Прогрызателя Дебаар в лагерь Эрнестуэя.",
    T = "Охота на кроколисков: засада",
  },
  [12570] = {
    D = "Прости, прости! Не хотел втянуть тебя в неприятности!$B$B<Раненый Оракул долго смотрит на вас остановившимся взглядом.>$B$BТы меня спасаешь! Мы благодарим тебя. Теперь мы вернемся в деревню. Ты тоже идешь... ты можешь остаться с нами. Волосатые бывают очень злы...$B$BСкажи мне, когда соберешься идти, хорошо?",
    O = "Отведите раненого оракула в Прибежище Гласа Дождя и поговорите с верховным оракулом Су-сэем.",
    T = "Счастливое непонимание",
  },
  [12571] = {
    D = "Мы пришли сюда задолго до волосатых, и не покинем это место – место великой святости.$B$BМожет, в твоем сердце живет только добро, но все же мы отправим с тобой Лафу. Мы ни в чем не можем быть уверены, пойми нас.$B$BЭти змеи все время пытаются пожрать наших детенышей. Вы с Лафу должны остановить их, понимаешь? Особенно ту большую змею, что живет у северо-восточного водопада.",
    O = "Верховный оракул Су-сэй из Прибежища Гласа Дождя просит вас убить Ядоклыка и 10 императорских кобр.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Большая Скверная Змея должна уйти",
  },
  [12572] = {
    D = "Су-сэй говорит, мы идем с тобой. Ты только веди себя хорошо, ладно?$B$BО-о, о-о! Мы знаем! Су-сэй будет рад, если мы принесем больше подношений в святилище! Нам не придется идти далеко, возле деревни всегда можно что-то откопать... Присмотрись, и увидишь блеск в грязи!$B$BИдем! Идем! Подношения в святилище!..",
    O = "Соберите 6 драгоценных блестяшек, которые выкопает Лафу, и принесите их верховному оракулу Су-сэю в прибежище Гласа Дождя.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Боги любят блестящие штучки",
  },
  [12573] = {
    D = "У нас отличная мысль. Волосатые были твоими друзьями, может быть, они тебя слушать.$B$BМы хотим вот что: передай предложение мира шаману Векжику. Он там, на юго-западе, где река становится водопадом. Скажи волосатым: войны не хотим. Скажи: хотим дружбу.$B$BТы $gхороший:хорошая:r; |3-6($r). Мы верим, что ты все сделаешь правильно.",
    O = "Верховный оракул Су-сэй из Прибежища Гласа Дождя хочет, чтобы вы пошли к шаману Векжику и предложили ему мир. Вернитесь к Су-сэю с ответом.$B$BЕсли потеряете мешок с жуками Лафу, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Заключение мира",
  },
  [12574] = {
    D = "<Верховный оракул Су-сэй некоторое время смотрит на ваш лоб, а потом начинает говорить.>$B$BСу-ган просит помощи. Мы думаем, что их, возможно, снова атаковали волосатые.$B$BМы посылаем на помощь тебя и Джалута... идите вдоль западной реки, пока не доберетесь до убежища Шепота Тумана. Сделайте то, что вам скажет Су-ган... если волосатые будут злы, бейте их по носу: они этого не любят.$B$B<Верховный оракул Су-сэй замолкает и смотрит на ваш лоб до тех пор, пока вы не уходите.>",
    O = "Отправляйтесь в убежище Шепота Тумана и поговорите с Призывателем туманов Су-ганом.$B$BЕсли вы потеряете любимый кристалл Джалута, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Так скоро?",
  },
  [12575] = {
    D = "Так вот эти волосатые приходят и разбивают синие кристаллы у великого камня тумана! Много-много дождя, молнии, вреда... Синий – неправильный кристалл для великого камня тумана! Невежественные волосатые...$B$BПосле молнии, волосатые похитили большое сокровище, что мы нашли в море-озере. Нам нужно вернуть сокровище назад, дать его великому камню тумана! Камень тумана сердит после того, что сделали волосатые!$B$BОдин, кто взял сокровище, его зовут Тартер... нет, Тиктак... нет, нет... Тартек! Да, точно – Тартек! Он пошел к этому их лагерю, на север. Верни нам сокровище!",
    O = "Убейте полководца Тартека и добудьте сокровище Шепота Тумана по просьбе призывателя туманов Су-гана.$B$BЕсли вы потеряете любимый кристалл Джалута, поговорите с верховным оракулом Су-сэем в Прибежище Гласа Дождя.",
    T = "Потерянное сокровище Шепота Тумана",
  },
  [12576] = {
    D = "С тех самых пор, когда волосатые появились тут, мы пытались быть добры с ними, но они платят нам злом за добро.$B$BМы привыкли к тому, что они глупы – вреда от них не много. Но теперь они вредят нашим святилищам. Это плохо. Святилищам нельзя причинять вред. Великие камни здесь с давних времен; с тех самых пор, когда Великие создали нас.$B$BМы не знаем, что делать, если великому камню Тумана причинят вред. Отправляйся в лагерь волосатых на севере... пусть они остановятся, пусть не возвращаются больше!",
    O = "Убейте 8 копьеносцев племени Бешеного Сердца и 6 падальщиков племени Бешеного Сердца по просьбе Призывателя туманов Су-гана из убежища Шепота Тумана.$B$BЕсли вы потеряете любимый кристалл Джалута, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Тяжелая рука",
  },
  [12577] = {
    D = "Ты $gхороший, сухокожий:хорошая, сухокожая;. Народ Шепота Тумана в безопасности, лохматые больше нас не беспокоят.$B$BИди в прибежище Гласа Дождя и скажи Су-сэю, что ты $gсправился:справилась;.",
    O = "Возвращайтесь в прибежище Гласа Дождя.",
    T = "Пора домой!",
  },
  [12578] = {
    D = "Не думал, что ты появишься вовремя – но, видно, я ошибся. Пошлю Мульда к мохобродам – нужно им врезать за то, что эти глупые не пришли смотреть на святилище. Их деревня на востоке, вверх по хребту, к северо-востоку от разрушенной колонны.$B$BТы иди с Мульдом! Мульд очень умный... ты его слушай.",
    O = "Отправляйтесь в деревню Мохобродов и поговорите с Мульдом.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Разгневанный горлок",
  },
  [12579] = {
    D = "Я всегда подозревал, что колонны являются причиной того, какая погода стоит в долине; я также всегда думал, что именно они хранят нас от нежити. И, похоже, получил подтверждение...$B$BНе так давно я услышал взрыв: тогда обрушилась колонна Жизненной Силы. Почти мгновенно изменилась погода: начался снег, которого мы прежде никогда не видели.$B$BК великому камню Мха тогда принесли кристаллы жизненной силы, и снег прекратился. Быть может, если сейчас мы сделаем то же самое, это поможет прогнать нежить.",
    O = "Мульд хочет, чтобы вы собрали 10 осколков Жизненной Силы, но при этом держались подальше от пещеры внутри самой колонны.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Жизненная Сила для мохобродов",
  },
  [1258] = {
    D = "Еще один компонент моего нового рецепта – мясо гигантского краба. Крабы, которые водятся в Пылевых топях, – их называют костлявыми скальными крабами – отлично подойдут!$b$bКлешни этих крабов – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные. К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше.$b$bТак что отправляйся на охоту в скалы, на берегах Терамора!",
    O = "Принесите 12 безупречных крабьих клешней Моргану Штерну в Терамор.",
    T = "...с крабами",
  },
  [12580] = {
    D = "Возможно, еще не все мохоброды погибли... они не заслужили того, чтобы их перебили, как животных.$B$BМы отомстим за это подлое убийство – и, может быть, еще успеем кого-нибудь спасти.",
    O = "Мульд хочет, чтобы вы спасли 6 мохобродов-жертв из деревни Мохобродов, хотя некоторые из них, возможно, уже мертвы.$B$BЕсли вы потеряете резиновый мячик Мульда, поговорите с верховным оракулом Су-сэем в прибежище Гласа Дождя.",
    T = "Спаситель мохобродов",
  },
  [12581] = {
    D = "Может, кристаллы и помогут защититься от нежити, но нужно сделать еще одну вещь.$B$BНужно найти предводителя нежити и прикончить его: тогда некому будет вести на нас их войско. Если мои подозрения справедливы, он прячется где-то внутри упавшей колонны...$B$BПо крайней мере, то, что именно туда тащат мертвые тела, говорит о чем-то подобном.$B$BЯ разложу осколки, как надо, и передам новости Су-сэю... а ты пока что поищи другую помощь.",
    O = "Убейте Артруиса Бессердечного.$B$BМульд не сможет отправиться с вами.",
    T = "Бремя героя",
  },
  [12582] = {
    D = "",
    O = "",
    T = "Защитник племени Бешеного Сердца",
  },
  [12583] = {
    D = "Я знаю, что один из сеятелей чумы разбился где-то в Драк'Сотре к западу отсюда.$B$BПопытайся его разыскать. Я использую части, оставшиеся от него, для создания устройства, которое будет сбивать сеятели с неба!",
    O = "Соберите детали сеятеля чумы для специалиста Зубоколеса в Драк'Сотре.",
    T = "Разбившийся сеятель",
  },
  [12584] = {
    D = "Мы знаем, что в Колрамасе, некрополе на юго-востоке, был немалый запас руды, известной как саронит.$B$BМои разведчики говорят, что большая часть саронита так и осталась там после того, как некрополь разрушили тролли.$B$BЭйтригг и его товарищи с Серебряной заставы хотят получить образцы руды, чтобы как следует ее изучить.$B$BОтправляйся к павшему некрополю и собери образцы саронита.",
    O = "По указанию капитана Руперта соберите 10 кусков саронита и отнесите их Эйтриггу на Серебряную заставу.",
    T = "Зло в чистом виде",
  },
  [12585] = {
    D = "Да уж, приятного в этом мало, но долг есть долг.$b$bУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$b$bИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$b$bЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$b$bСобери нам дров для костра, и мы будем очень тебе благодарны.",
    O = "Принесите капитану Гронделю в Драк'Агал 20 кусков древесины высохшего колючника.",
    T = "Тролльский дозор: животворящее тепло",
  },
  [12586] = {
    D = "Well, $n, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.$B$BBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.$B$BI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.",
    O = "Talk to <x> at <x>.",
    T = "В поисках крупной дичи",
  },
  [12587] = {
    D = "Расчехляй оружие, |3-6($r). Пора отправляться в дозор!$b$bУ меня под командованием четыре заставы, и они должны оставаться под нашим контролем. Слушай приказ: обойди все четыре и предложи свою помощь тамошним командирам.$b$bНачни с капитана Брендона на юго-востоке отсюда. Когда все закончишь, он направит тебя на следующую заставу.$b$bКогда обойдешь все четыре заставы и окажешь там необходимую помощь, возвращайся ко мне. И помни, чем быстрее исполнишь работу, тем выше будет награда – так что поторопись. Время – деньги!$b$bВсе, выполняй!",
    O = "Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк'Сотре, к юго-востоку, застава капитана Гронделя – в Драк'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб'Валоке, к северу.",
    T = "Тролльский дозор",
  },
  [12588] = {
    D = "Во время последнего наступления мы нашли древнюю карту сокровищ. Если верить этой карте, то где-то рядом зарыт настоящий клад – бесценные тролльские артефакты.$b$bМоим воинам есть чем заняться, тем более теперь, когда мы зажаты между молотом и наковальней – между Драккари и Плетью. Так что поиском сокровищ придется заняться тебе.$b$bВозьми эту лопату и раскопай кучи земли к юго-западу отсюда. Когда отыщешь сокровища, возвращайся ко мне.",
    O = "По поручению капитана Брана из Драк'Сотры возьмите стальной заступ, раскопайте курганы древних троллей неподалеку и отыщите реликвию Драккари.",
    T = "Тролльский дозор: будем копать",
  },
  [12589] = {
    D = "Итак, ты думаешь, что умеешь стрелять?$B$BЧто ж, давай проверим твои умения. Начнем с чего-нибудь не слишком крупного и агрессивного. И помни: если не собираешься стрелять, то и не целься!$B$BА теперь, если ты $gготов:готова;, прицелься в яблоко на голове Везучего Вильгельма, и стреляй!",
    O = "Выстрелите из винтовки РЖР в яблоко на голове Везучего Вильгельма, а потом поговорите с Дростаном.",
    T = "Ничего опасного",
  },
  [1259] = {
    D = "Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имен до предпочитаемого вооружения.$B$BУж он-то расскажет вам об этом Павале Рите.",
    O = "Поговорите о Рите с адъютантом Тезораном в Тераморе.",
    T = "Lieutenant Paval Reethe",
  },
  [12590] = {
    D = "",
    O = "",
    T = "Blahblah[PH]",
  },
  [12591] = {
    D = "Умно...$b$bМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$b$bИ теперь мы оказались зажаты между двумя нерубианскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$b$bНаша первоочередная задача – помешать этим двум армиями соединиться. Надо отрезать их друг от друга и засыпать тоннели.$b$bВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.",
    O = "По поручению капитана Руперта из Драк'Сотры взорвите 5 нерубианских кратеров с помощью фугасных гранат.",
    T = "Тролльский дозор: подрывные работы",
  },
  [12592] = {
    D = "Итак, у тебя есть охотничий инстинкт. Стреляешь ты тоже неплохо, и Хеминг тебя не выгнал – а это значит, он возьмет тебя на охоту.$B$BА вот как насчет того, чтобы устроить соревнование? Только ты и я.$B$BХеминг и его приятели пригласят тебя на охоту, а мы подсчитаем, кто из нас сколько добудет. Только дело это небыстрое: придется убить много разных зверей... Удачи тебе!",
    O = "Убейте 60 животных, помогая Хемингу и его друзьям на охоте. Когда покончите с этим, возвращайтесь к Дростану в лагерь Эрнестуэя, чтобы сравнить ваши результаты.",
    T = "Вызов великого охотника",
  },
  [12593] = {
    D = "Все, что составляет мою сущность: злость, безжалостность, отмщение – я вкладываю в тебя, достойнейший рыцарь. Я даровал тебе бессмертие, ибо тебе суждено стать вестником новой, темной эры Плети.$B$BУзри же земли, лежащие перед тобой. Видишь ли ты, как Алый орден тщетно пытается разрушить созданное нами? Видишь батальоны Последней Надежды, бросающие вызов войскам Плети в Чумных землях? Все они должны поплатиться за свое упрямство. $B$BТы станешь моим возмездием, и страшен будет удел тех, кто станет у тебя на пути. Иди же и взгляни в лицо своей судьбе, мой рыцарь смерти.",
    O = "Доложите о своем прибытии инструктору Разувию из Сердца Акеруса.",
    T = "На службе Короля-лича",
  },
  [12594] = {
    D = "Из всех постов мне дали именно этот, самый поганый.$b$bВся местность затоплена грязной вонючей водой, а теперь здесь еще поселились какие-то вонючие болотные духи!$b$bЯ не знаю, что они собой представляют и что им здесь нужно, и, если честно, мне это по барабану. Для меня важно одно – они отравляют мой сектор! Мы здесь воюем, а как можно нормально вести боевые действия, когда все поле боя кишит этими грязными тварями?!$b$bТак что иди, |3-6($c), и не возвращайся, пока не убьешь хотя бы полдюжины этих гадов.",
    O = "По поручению капитана Гронделя убейте 7 мшистых буянов в Драк'Агале.",
    T = "Тролльский дозор: зачистка местности",
  },
  [12595] = {
    D = "Что ж, $n, тебе удалось подтвердить свое искусство охотника в выслеживании всех видов дичи: люторогов, кошек и кроколисков. Для многих этого хватило бы с лихвой – но не для таких, как я. Истинному охотнику нужны иные испытания. $B$BДориан Гроза Драконов разбил лагерь на севере, за озером Горьких Волн. До него дошли слухи о гигантских доисторических драконах. Ты только представь себе, какая это добыча! А какая слава! Давай-ка, навести Дориана и узнай – может, ему уже повезло.",
    O = "Поговорите с Дорианом Грозой Драконов в его лагере в Низине Шолазар.",
    T = "В поисках крупной дичи",
  },
  [12596] = {
    D = "Добро пожаловать на Серебряную заставу, $gновобранец:барышня;. Я – командир Кунц, но ты можешь называть меня просто \"Ваше превосходительство\".$b$bИ не думай, что тут у тебя будет вольница, и ты сможешь шляться по вверенной мне территории, берясь за любую работу, которая тебе подойдет, и ни перед кем не отчитываться.$b$bОбо всем, что ты делаешь, будешь докладывать лично мне – и готовься беспрекословно выполнять все мои приказы. Понятно?$b$bПерво-наперво ты познакомишься с моими людьми. И с районом, который нам поручили зачистить.$b$bОбойди всех моих капитанов и сделай все, что они тебе скажут. Когда закончишь обход, возвращайся ко мне с докладом.",
    O = "Обойдите четыре заставы Серебряного Авангарда, выполните приказы капитанов и возвратитесь к командиру Кунцу на Серебряную заставу с докладом.$b$bЗаставы капитана Брендона и капитана Руперта расположены в Драк'Сотре, к юго-востоку, застава капитана Гронделя – в Драк'Агале, прямо на восток, а застава алхимика Финкльштейна – в Хеб'Валоке, к северу.",
    T = "Па'трулль",
  },
  [12597] = {
    D = "Да, мои люди крепки и выносливы, но они все-таки смертные.$b$bРаны и боль выводят их из строя. Такова суровая правда жизни.$b$bНо к счастью, один из наших алхимиков придумал целебную мазь, которая почти полностью снимает боль.$b$bВ рецепт этой мази входит экстракт из особого мака, который тролли выращивают на полях неподалеку отсюда, на западе. Иди на поля Драк'Сотры и собери эти маки, чтобы у нас был хороший запас сырья для целебного снадобья.",
    O = "Соберите 5 распустившихся водяных маков на полях Драк'Сотры для капитана Брендона из Драк'Сотры.",
    T = "Обезболивающее снадобье",
  },
  [12598] = {
    D = "Умно...$b$bМы-то были уверены, что у нас все под контролем, а они сделали подкоп, прошли прямо под нами и захватили святилище!$b$bИ теперь мы оказались зажаты между двумя нерубскими армиями, и с каждой минутой наше положение становится все отчаяннее и отчаяннее.$b$bНаша первоочередная задача – помешать этим двум армиям получить подкрепление. Надо засыпать тоннели.$b$bВозьми эти гранаты и сбрось их в кратеры наших врагов на северо-западе отсюда.",
    O = "По заданию капитана Руперта из Драк'Сотры обрушьте 5 нерубских тоннелей с помощью фугасных гранат.",
    T = "Подрывные работы",
  },
  [12599] = {
    D = "Да уж, приятного в этом мало, но долг есть долг.$b$bУже несколько дней мои солдаты отважно сражаются, стоя по колено в холодной воде. Они – храбрые воины, но они все-таки не железные.$b$bИм нужно обсохнуть, согреться, воспрянуть духом. А для этого нужен костер.$b$bЭта часть города вся затоплена, но у мертвых корней колючника есть свойство отталкивать влагу, они всегда остаются сухими.$b$bСобери нам дров для костра, и мы будем очень тебе благодарны.",
    O = "Принесите капитану Гронделю в Драк'Агал 20 кусков древесины высохшего колючника.",
    T = "Животворящее тепло",
  },
  [126] = {
    D = "$n, гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем. И один из них воет громче других – это Изувой, их вождь.$B$BСтоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу.$B$BСоблюдай осторожность, этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост...",
    O = "Принесите лапу Изувоя Вернеру Осгуду в Приозерье.",
    T = "Вой в холмах",
  },
  [1260] = {
    D = "Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям \"Синего отшельника\" понравится!$b$bЯ послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи.$b$bДолог путь до Терамора, и для меня тяжеловат. Но я думаю, что $Gтакой молодой:такая молодая; |3-6($c) с радостью ухватится за возможность совершить подобное путешествие.",
    O = "Поговорите с Морганом Штерном в Тераморе.",
    T = "Морган Штерн",
  },
  [12600] = {
    D = "",
    O = "",
    T = "Рекламный код Upper Deck – Верховой медведь",
  },
  [12601] = {
    D = "Ага, ты, должно быть, обещанный нам патрульный. И очень вовремя, приятель – вообще-то, я не ждал, что ко мне пришлют барышню, но все равно... ты пришла очень вовремя. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!",
    O = "Помогите алхимику Финкльштейну в Хеб'валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.",
    T = "В подмастерья к алхимику",
  },
  [12602] = {
    D = "Ага, ты, должно быть, обещанный нам патрульный. $gИ очень вовремя, приятель:Вообще-то я не ждал, что ко мне пришлют барышню, но все равно... ты пришла очень вовремя;. Мне срочно нужен помощник.$b$bМы захватили лазутчика Драккари, и нам надо его допросить. Но сначала нужно приготовить сыворотку правды, и вот тут мне понадобится твоя помощь.$b$bПриготовление сыворотки – процесс кропотливый, он требует точных расчетов, безошибочной интуиции и способности к импровизации на каждом этапе.$b$bКогда будешь $gготов:готова;, дай мне знать, |3-6($r). И помни: самое главное – точный расчет времени!",
    O = "Помогите алхимику Финкльштейну в Хеб'Валоке в приготовлении сыворотки правды.$b$bКогда вы будете готовы приступить к работе, скажите об этом алхимику и выполняйте все его указания.",
    T = "В подмастерья к алхимику",
  },
  [12603] = {
    D = "Доисторические драконы обитают в большинстве земель на севере и востоке; даже на таком расстоянии я ощущаю жар их дыхания. Но прежде, чем мы бросим вызов самым могущественным из них, нам следует испытать свои способности на менее опасных противниках.$B$BОднако не следует расслабляться: любой из них способен сожрать человека целиком. После того как убийство драконов станет для тебя обычным делом, возвращайся сюда: я скажу, каким будет следующий шаг.",
    O = "Убейте 6 доисторических драконов, а затем поговорите с Дорианом Грозой Драконов в форпосте Дориана.",
    T = "Время точить когти",
  },
  [12604] = {
    D = "",
    O = "",
    T = "Поздравляем!",
  },
  [12605] = {
    D = "Не думаю, что мы сумеем привлечь внимание Праматери Сливины, если будем прыгать и размахивать руками как идиоты; но если мы будем умны, то сможем заставить ее выйти на бой. А заодно заготовим немного, м-м, корма для моего небольшого проекта.$B$B<Дориан бросает взгляд на Любопытсона.>$B$BНо пока что об этом не стоит беспокоиться. Найди яйца доисторических драконов к востоку и северо-востоку от нашего лагеря. Яйца нужно разбить, а дракончиков притащить сюда. Как только Праматерь узнает, что мы сделали, ей придется встретиться с нами.",
    O = "Принесите Дориану Грозе Драконов 6 доисторических дракончиков в форпост Дориана.",
    T = "Подготовка ловушки",
  },
  [12606] = {
    D = "Теперь, когда тоннели засыпаны, нам нужно подумать о том, как спасти наших товарищей, попавших в плен к неприятелю.$b$bЕсли нам повезет, то вполне может статься, что некоторые наши солдаты еще живы и относительно здоровы внутри нерубских коконов.$b$bОсвободи их, |3-6($c), пока не поздно!",
    O = "Вскройте нерубские коконы в Драк'Сотре и вернитесь к капитану Руперту в Драк'Сотру, освободив 3 взятых в плен пехотинцев.",
    T = "В коконах",
  },
  [12607] = {
    D = "Дориан решил, что прежде, чем отправиться на бой с Праматерью Сливиной, вам с Хемингом было бы неплохо научиться действовать сообща, оседлав мамонта.$B$BВокруг лагеря полно этих зверюг. Возьми уздечку и набрось ее на твердобивневого мамонта. Выбирай самочек. Самцы слишком опасны и терпеть не могут упряжи. Когда найдешь подходящего мамонта, веди его сюда.",
    O = "Приведите Любопытсону в форпост Дориана твердобивневого мамонта.",
    T = "Поимка мамонта",
  },
  [12608] = {
    D = "<Похоже, слова Аватары Фрейи были правдой. Нежить не могла войти в Низину Шолазар, пока была цела колонна Жизненной Силы: для проникновения в низину нежить использовала живых – служителей Культа Проклятых.>$B$B<Лучше предупредить Аватару Фрейи о том, что в Низине Шолазар находятся живые посланцы Короля-лича.>",
    O = "Поговорите с Аватарой Фрейи у водопадов Гласа Дождя.",
    T = "Вторжение сектантов",
  },
  [12609] = {
    D = "Слушай, |3-6($c). Я понимаю, что прошу слишком многого...$b$bДостать свежую паучью лимфу очень непросто, даже в этих зараженных краях. Но Финкльштейн говорит, что ему нужно ни много ни мало, а целый чан, причем чем скорее, тем лучше.$b$bМои люди сейчас собирают ему реагенты, и они просто не справятся с новым приказом алхимика вовремя. Им нужна помощь.$b$bКогда будешь в Зул'Драке, смотри внимательно по сторонам: может, где и увидишь пауков-капканщиков. Принеси мне всю лимфу, которую сумеешь добыть.",
    O = "Соберите 7 унций свежей паучьей лимфы от пауков-капканщиков в Зул'Драке для капитана Арната из Хеб'Валока.",
    T = "Пополнение запасов",
  },
  [1261] = {
    D = "Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он все-таки достал меня.$b$bА как же моя миссия?! Ты, $n, $Gдолжен:должна; закончить ее. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить.$b$bТой ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!$b$b$n, ты $Gдолжен:должна; найти эту тварь и вернуть подвеску.",
    O = "Принесите изукрашенную Подвеску Назиру в Деревню Гиблотопь.",
    T = "Марг говорит",
  },
  [12610] = {
    D = "С тех пор как у нас появился Финкльштейн, я только и делаю, что собираю различные ингредиенты для его экспериментов и снадобий.$b$bЯ выполняю приказы, потому что таков долг солдата, но я все-таки воин и ветеран многих битв. Мое место – на передовой, мое дело – сражаться с врагом.$b$bПомоги мне, |3-6($r). Собери за меня крылья летучих мышей, чтобы я мог поскорее заняться настоящим делом.",
    O = "Соберите 7 безукоризненных крыльев нетопырей в Зул'Драке для капитана Арната из Хеб'Валока.",
    T = "Подрезанные крылышки",
  },
  [12611] = {
    D = "Посланники Короля-лича сделали глупость, ступив в эти земли, где правит Жизнь. Все зло, которое они совершат, вернется к ним семикратно.$B$BЧудовище, ответственное за порчу, причиненную этой земле, носит имя Талгран Сеятель Гнили: ты сможешь найти его к северу отсюда. Возьми этот оберег и воспользуйся им, чтобы зло обратилось само против себя. Покажи войску Плети, что сила Жизни побеждает все!",
    O = "Аватара Фрейи хочет, чтобы вы победили Талграна Сеятеля Гнили при помощи Оберега Фрейи, отразив его проклятия и обратив их против него.",
    T = "Семикратное воздаяние",
  },
  [12612] = {
    D = "Здесь титаны создавали самых разнообразных живых существ, и жизнь расцветала, не зная пределов.$B$BПять колонн, усыпанных кристаллами, окружают долину и источают чистую жизненную силу. Войско Плети не могло бы проникнуть сюда; но, к несчастью, одна из колонн была уничтожена.$B$BОтправляйся к колонне Жизненной Силы: возможно, ты сумеешь узнать, что произошло. Никто из нежити не мог приблизиться к ней: ищи живых врагов. Ты отыщешь то, что осталось от колонны, к югу от этого места.",
    O = "Отправляйтесь к колонне Жизненной Силы и попытайтесь понять, как она была разрушена.",
    T = "Разрушенная колонна",
  },
  [12613] = {
    D = "Теперь мы не можем остановиться, |3-6($r). Первый переключатель сработал, остался еще один.$B$BТитаны создали другой наблюдательный пункт, чтобы следить за своими творениями. Ты найдешь его высоко в горах на востоке.$B$BЗадействуй активационный переключатель \"тета\", и Связующая спираль заработает.",
    O = "Аватара Фрейи хочет, чтобы вы направились к Дозору Творцов на востоке Низины Шолазар и там задействовали активационный переключатель \"тета\".",
    T = "Включение Связующей спирали: Дозор Творцов",
  },
  [12614] = {
    D = "Праматерь Сливина наверняка в ярости: сейчас это настоящий вихрь клыков, шипов и когтей. Ты $gпохитил:похитила; ее детенышей, а это ни одной матери не придется по нраву.$B$BТо есть, конечно, яйца – это не совсем детеныши, но, видать, сами драконы придерживаются другого мнения.$B$BОна в ярости и отчаянье: именно такую добычу и любит Хеминг. Думаю, вы с Хемингом, да еще и на этом мамонте, станете для нее достойными противниками.$B$BПраматерь можно найти на северной границе Дикой чащи. Помни: она жаждет мести!",
    O = "Убейте Праматерь Сливину и возвращайтесь к Дориану Грозе Драконов в форпост Дориана.",
    T = "Материнский гнев",
  },
  [12615] = {
    D = "Мастер проклятий Убунго, наверное, уже рассказывал тебе о подношениях богам Зул'Драка. Зим'Абва – не единственный бог, брошенный и забытый племенем драккари.$B$BМы обрели убежище и защиту под покровительством Зим'Торги, Матери Изобилия. Как и Зим'Абва, она даст тебе благословение, если ты принесешь ей дары Драккари.",
