  [12619] = {
    D = "Единственный и самый важный инструмент рыцаря смерти – это рунический меч. Именно с его помощью ты подчинишь себе магию льда, крови и нечестивости. Рунический меч – это сосуд, вмещающий силы рун рыцаря смерти.$B$BДа, рыцарь, настал твой час обрести собственный клинок. Осмотри оружейные стойки на этом этаже и найди затупившийся в боях меч, после чего отнеси его к ближайшей кузне рун и перекуй в рунический.",
    O = "Обыщите оружейные стойки в Черном оплоте, найдите затупившийся в боях меч и перекуйте его в рунический меч в рунной кузне.$B$BПринесите готовый клинок инструктору Разувию в Черный оплот.",
    T = "Украшенный рунический меч",
  },
  [1262] = {
    D = "Странно, что украденная Маргом была у простого солдата. Возможно ее владелец маскировался, или, что вероятнее, солдаты сами ее стащили. $B$BЧто бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти ее хозяина, если хотим разрешить эту загадку.$b$bОтнеси эту подвеску Зору Одинокое Дерево в Оргриммар. Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде.",
    O = "Отнесите изукрашенную подвеску Зору Одинокому Дереву в Оргриммар.",
    T = "Сообщение для Зора",
  },
  [12620] = {
    D = "Мы действовали слишком медленно, $n. Проклятые сектанты добрались до Мерцающей колонны и готовятся уничтожить ее. Я чувствую их присутствие.$B$BУ нас мало времени. Протруби в этот рог на вершине Мерцающей колонны, чтобы направить мою энергию в кристаллы.$B$BМы покажем этим фанатикам, что не стоит связываться с творениями титанов.",
    O = "Аватара Фрейи у водопадов Гласа Дождя хочет, чтобы вы протрубили в Рог Фрейи на вершине Мерцающей колонны.",
    T = "Гнев Хранительницы Жизни",
  },
  [12621] = {
    D = "Мы разобрались с сектантами, однако вторжение Плети так и не удалось остановить. Положение становится отчаянным, $n.$B$BЕсть одно последнее средство. Но прежде чем я открою тебе его, я должна быть уверена, что тебе можно доверять.",
    O = "Выслушайте то, что вам расскажет Аватара Фрейи.",
    T = "Договор Фрейи",
  },
  [12622] = {
    D = "Знаешь, чего Ауне думать? $B$BМного троллей Драккари собрались у бассейна Джин'Алаи, на юго-западе. Нам надо выманивать их вождей, и Ауне уже знает, как.$B$BТы ходишь туда, убиваешь всех троллей. Когда прикончишь много троллей, их вожди выйдут сами.$B$BИ, когда они появятся у своих тотемов, ты отберешь все сокровища у Кутубе'сы, Гаванила и Чуло Безумного.",
    O = "По поручению охотника за скальпами Ауне из Зим'торги заберите сокровища у Кутубе'сы, Гаванила и Чуло Безумного.",
    T = "Вожди у Джин'Алаи",
  },
  [12623] = {
    D = "Нам, зандаларам, нужна твоя помощь, $n. Мы должны положить конец тем бесчинствам, которые Драккари творят со своими богами!$B$BНа северо-востоке, на великих ступенях, что ведут на следующий ярус Зул'Драка, располагается Зим'Торга – дом еще одного из богов, где пребывает его изваяние, и убежище, которое мы так отчаянно пытаемся защитить.$B$BЯ хочу, чтобы ты $gотправился:отправилась; туда и $gпоговорил:поговорила; со знахарем Кхуфу. И будь $gосторожен:осторожна;. Драккари совершают набеги на эти края беспрестанно.",
    O = "Поговорите со знахарем Кхуфу в Зим'Торге.",
    T = "К знахарю",
  },
  [12624] = {
    D = "Когда я узнал, что мисс Булиан помогает Эрнестуэю с экспедицией, я тут же записался палубным матросом. Понимаешь, я уже много месяцев собираюсь жениться на ней!$B$BУ меня все было распланировано. Я хотел сделать ей предложение как раз в ту ночь, когда случилось кораблекрушение... но теперь обручальное кольцо пропало. Я уже везде искал!$B$BЯ знаю, это кажется невероятным, но мне кажется, оно где-то в Низине. Или его украл кто-нибудь из Торговой Компании, или, может, зверь проглотил; но оно здесь... я уверен!",
    O = "Ищите золотое обручальное кольцо у всех обитателей Низины Шолазар.",
    T = "Оно может быть где угодно!",
  },
  [12625] = {
    D = "Перед тобой Акерус, великая цитадель смерти! Ничто на земле не может с ней сравниться. Даже могучему Наксрамасу не устоять перед силами Черного оплота.$B$BХотя я чувствую смятение в твоих мыслях, у нас нет ни секунды на промедление. Ты $gдолжен:должна; собраться и взять власть над Акерусом в свои руки, ибо я уже слышу первые звуки боевых горнов.$B$BНа этом этаже со всех сторон есть лестницы, ведущие на верхний этаж, где располагаются наши войска. Найди там главного кузнеца крепости Корвия и потребуй у него отчет о состоянии дел. Таланор ждет нашего доклада.",
    O = "Найдите главного кузнеца крепости Корвия на войсковом этаже Черного оплота.",
    T = "Власть над Акерусом",
  },
  [12626] = {
    D = "<Корвий отдает вам честь.>$B$BНаши запасы оружия, брони и амуниции практически полны. Мы готовы к войне!$B$B<Корвий сворачивает в рулон толстый лист пергамента.>$B$BС другой стороны этажа, на юго-западе располагаются офицерские казармы. Возьми этот доклад и отнеси его Таланору, командиру батальона Проклятых.",
    O = "Доставьте доклад Корвия Командиру сил Плети Таланору, находящемуся в офицерских казармах Черного оплота.",
    T = "Батальон Проклятых",
  },
  [12627] = {
    D = "Я пытался поговорить с богами. Однако целители у бассейна Джин'Алаи проводят ритуалы, которые препятствуют моим попыткам связаться с богами.$B$BНам надо развеять их чары. Это действительно очень важно. Я уверен, что где-то там, на юго-западе, ты найдешь котлы, которые они используют для своей магии.$B$BОпрокинь все котлы, чтобы помешать ритуалам, которые не дают мне говорить с богами.",
    O = "По поручению знахаря Кхуфу из Зим'Торги опрокиньте Синий котел, Зеленый котел, Фиолетовый котел и Красный котел.",
    T = "Прорыв в Джин'Алаи",
  },
  [12628] = {
    D = "Боги говорили с нами, $n. Теперь мы знаем, что тебе нужно сделать.$B$BИди к алтарю Хар'коа к юго-востоку отсюда и поговори с богиней снежных леопардов.",
    O = "Поговорите с Хар'коа у алтаря Хар'коа.",
    T = "Разговор с Хар'коа",
  },
  [12629] = {
    D = "Когда Плеть видит цель, она не остановится ни перед чем на пути к этой цели.$b$bМы обречены на бессмысленное существование ходячих трупов...$b$b<Стефан кривит губы в жестокой усмешке.>$b$b... если мы не сумеем обратить их стремления против них самих.$b$bЯ все объясню, но позже. Сейчас мне нужно подготовить одно достаточно сложное заклинание, для которого мне понадобятся определенные материальные компоненты.$b$bИди на восток, за Реликварий Агонии. Убей поганищ, собери слюну вурдалаков, которых там встретишь, и принеси мне их останки.",
    O = "По указанию Стефана с Черной заставы отправляйтесь за Реликварий Агонии и соберите 5 клубков прогнивших внутренностей поганища с тлетворных поганищ и 5 сгустков вязкой слюны вурдалака.",
    T = "Можно убежать, но нельзя скрыться",
  },
  [1263] = {
    D = "",
    O = "",
    T = "Сожженная Таверна",
  },
  [12630] = {
    D = "Прежде чем ты познакомишься с Нассом, ты $gдолжен:должна; кое-что уяснить.$b$bОн принял токсическую дозу гнили, в результате чего ослеп, оглох и практически утратил чувствительность.$b$bНо все не так плохо. Сейчас у него стойкий иммунитет к этой гадости, и поэтому он идеально подходит для выполнения определенных работ – вроде той, что я собираюсь тебе поручить.$b$bТут поблизости много троллей Плети, и нам хотелось бы изучить, как на них действует гниль. Для этого нам нужны образцы их волос. Возьми с собой Насса и этот сапог. Когда убьешь тролля, пни Насса как следует, и он поймет, что надо выдрать у тролля прядь волос.",
    O = "С помощью Насса соберите образцы волос 10 иссохших троллей для Стефана с Черной заставы.$b$bЕсли вы потеряете Насса, возвращайтесь к Стефану.",
    T = "Насса надо как следует пнуть",
  },
  [12631] = {
    D = "Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$b$bГлядя на этот узор, ты теряешь себя и подчиняешься зову зловещей силы – силы, которая требует, чтобы ты $gнадел:надела; его на себя. Однако ты можешь противиться этой силе, а значит, сумеешь отнести колье на Черную заставу.$b$bЕсли кто-то и сможет найти этому объяснение, то только рыцарь смерти...",
    O = "Отнесите колье нежизни Стефану на Черную заставу.",
    T = "Приглашение",
  },
  [12632] = {
    D = "Меня покорят последней из всех богов, а это значит, что первым делом мы должны попытаться освободить остальных. Связанная колдовством своих покорителей, я не могу прозревать их судьбу.$B$BЯ попрошу тебя об одолжении. Драккари уже обратили мои чары против меня. Они превратили моих детей в безобразных уродов.$B$BВозьми мой ус. Убей моих измученных детей, и магия моего уса освободит их от кошмара и возродит к жизни.",
    O = "Используйте удивительные свойства уса Хар'коа для того, чтобы освободить и воскресить ее детей. Когда все будет сделано, вернитесь к Хар'коа. Она ждет вас у алтаря.",
    T = "Первым делом – мои дети",
  },
  [12633] = {
    D = "Вырезанное из кости и вымоченное в крови, это колье покрыто замысловатым узором.$b$bГлядя на этот узор, вы теряете себя и подчиняетесь зову зловещей силы – силы, которая требует, чтобы вы надели колье. Однако вы можете противиться этой силе, а значит, сумеете донести колье до Черной заставы.$b$bЕсли кто-то и сможет найти объяснение произошедшему, то только рыцарь смерти...",
