  [12859] = {
    D = "Тролли нападали на логово Яростного Когтя и выгоняли всех волчеров! А теперь – еще хуже. Тролли жгут нашу деревню! Совсем-совсем плохо. Вождь просил Моки, главного шамана Яростного Когтя, изучать их огонь. И вот что удивляет! Огонь по-прежнему жарок и может жечь и сжигать.$B$BПомоги волчерам погасить огонь. У Моки есть для тебя особый огнетушитель. Возьми его и потуши пожары в логове Яростного Когтя на юго-востоке. Иногда так бывает, что одна струя не потушит огонь – надо много. Но в огнетушителе вода есть всегда! Магия Яростного Когтя очень сильная, да!",
    O = "Используйте огнетушитель Яростного Когтя, чтобы потушить 15 пожаров в логове Яростного Когтя по просьбе старого шамана Моки в Разломе Света в Зул'Драке.",
    T = "Негасимый огонь",
  },
  [1286] = {
    D = "Удержаться на болотах было нелегко. Но все же мы возвели несколько оборонительных сторожевых башен в округе.$b$bПо последним донесениям разведчиков, группа дезертиров обосновалась в Разрушенной башне к юго-востоку от таверны.$b$bЗа главного у них, кажется, Балос Хакен. Посмотрим, получится ли вытянуть у него какие-нибудь сведения.$b$bНо будь с ним осторожнее, $N, он тертый вояка.",
