  [12985] = {
    D = "Здравствуй, |3-6($r).$b$bУ меня есть работа, и король Йоккум считает, что ты вполне можешь с ней справиться – если, конечно, тебе все еще хочется заслужить уважение моего народа.$b$bЯ придумал, как можно воссоздать еще один артефакт, который принесет нашей крепости благословение и покровительство Ходира. У меня есть почти все, чтобы приступить к восстановлению. Осталось только добыть глаза наших павших врагов$b$bВозьми кирку и принеси мне глаза мертвых железных великанов, которые остались на поле боя.",
    O = "По заданию Ньормельда в Дун Ниффелеме возьмите кирку с алмазным наконечником, вырвите с ее помощью глаза у мертвых железных великанов у Промерзшего озера и принесите ему 8 глаз Закаленных Бурей.",
    T = "Ковка шлема",
  },
  [12986] = {
    D = "Ядра Норганнона здесь нет. Я не знаю, зачем ты его ищешь, |3-6($r), и знаешь ли ты истинное назначение этой вещи.$B$BМожет быть, я помогу тебе в поисках ядра, но сначала ты помоги мне. Недавно мне довелось узнать о наблюдателе Ториме. Его власть оспаривают, а его судьба остается неопределенной. Это меня беспокоит, поскольку я ничего не знаю о других наблюдателях. Воспользуйся этим банком данных, чтобы исследовать их храмы на северо-востоке, и поделись со мной информацией.",
    O = "По заданию Кретея из Подножия посетите Храм Изобретений, Храм Зимы, Храм Жизни и Храм Порядка. Используйте банк данных для изучения каждого из них.",
    T = "Судьба титанов",
