  [13002] = {
    D = "Добро пожаловать в морозилку, $gдружок:подружка;. Хотя тут не слишком тепло, меня греет моя профессия – огранка камней. Не хватает только материалов!$B$BТы бы $gнашел:нашла; для меня парочку блестяшек – а я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.",
    O = "Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Геба'ли в Крепость Песни Войны.",
    T = "Огранка камней",
  },
  [13003] = {
    D = "Копье Ходира – символ великой воинской чести и мощи.$b$bВ присутствии этой реликвии в каждом, кто входит в Дун Ниффелем, загорается неутолимая жажда славы. И действительно: вы уже ощущаете неодолимую потребность испытать себя в битве.$B$BВсматриваясь в горизонт, вы замечаете летающего неподалеку дикого змея.$B$BИтак, решено. Из вас двоих только один доживет до рассвета...",
    O = "С помощью копья Ходира загарпуньте дикого змея в долине Древних Зим и сразитесь с ним не на жизнь, а на смерть.",
    T = "Бросая копье Ходира",
  },
  [13004] = {
    D = "Идет война, и каждый из нас должен внести свой вклад в победу! Я, например, занимаюсь огранкой камней, ибо мне под силу не просто обработать обычный камень, но и превратить его в идеальный. Знаешь, если бы ты $gпринес:принесла; мне несколько необработанных камней, я бы взамен научил тебя искусству огранки! Тогда ты сможешь получать идеальные камни с улучшенными характеристиками, обрабатывая драгоценные камни Нордскола высокого качества.",
    O = "Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Алестосу в Крепость Отваги.",
    T = "Огранка камней",
  },
  [13005] = {
    D = "Годами я пренебрегал своим долгом, предаваясь печали и горечи поражения.$B$BА вот мои храбрые земельники оказались покрепче! Они не нарушили свою клятву – ценой своих жизней защищать это место.$B$BДаже сейчас они храбро и самоотверженно сопротивляются тлетворному воздействию железных дворфов, выжидая момент, чтобы переломить ситуацию.$B$BИ этот момент настал. Мы должны сплотить остатки земельников и привести их к славной победе. Звуки рога Вершин призовут их выйти на битву и помогут разгромить неприятеля и отвоевать Террасу Творцов.",
    O = "Используйте рог Вершин, чтобы призвать земельников на битву с железными дворфами и убить 20 железных дворфов и 7 железных часовых по просьбе Торима с Террасы Творцов.",
    T = "Клятва детей земли",
  },
  [13006] = {
    D = "Вы подходите ближе и видите, что мороз уже оказал свое пагубное воздействие на поверхность шлема. Пока это лишь тонкий слой инея, но уже совсем скоро он превратится в толстую корку льда.$B$BЧтобы ваши усилия не пропали втуне, вы решаете осмотреть местность и попытаться найти решение этой проблемы.$B$BВы отходите на пару шагов и вдруг замечаете, как сверкнули глазницы шлема. В тот же миг в ваших мыслях возникает образ пещеры зимней спячки.",
    O = "Идите в пещеру зимней спячки, что к западу от Дун Ниффелема, и соберите 5 сгустков вязкого масла злобных масленышей. Потом возвращайтесь в Дун Ниффелем и натрите маслом шлем Ходира.",
    T = "Полировка шлема",
  },
  [13007] = {
    D = "Нам не удалось помешать им построить железного колосса, $n, а это значит, что у нас не осталось иного выхода, кроме как драться с этим чудовищем.$B$BУ этого колосса есть единственное слабое место, и Вруор придумал план, как на него надавить.$B$BКакой бы толстой ни была броня, кислота йормунгаров разъедает железо. Ими можно управлять при помощи сфер. Возьми одного йормунгара и отправляйся на северный край Снежных равнин. Прочеши всю равнину, найди колосса и сделай так, чтобы твой йормунгар дыхнул на него своим кислотным дыханием. Если тебе нужна помощь в укрощении этих существ, поговори с одним из дрессировщиков.",
    O = "Уничтожьте железного колосса с помощью прирученного йормунгара, а потом возвращайтесь к Глыбоскалу Камнетесу в Приют Глыбоскала.",
    T = "Железный колосс",
  },
  [13008] = {
    D = "Неожиданность была нашим главным козырем! Подрывники хорошо потрудились. Мы пробили тоннель в горе и ворвались в Плетхольм. Защитники лагеря отчаянно сопротивлялись, и у них было численное преимущество. Мы отступили обратно в долину и вели непрестанный артиллерийский огонь по преследователям. Какое-то время нам удавалось их сдерживать, а потом... эти чудовища стали использовать наших рыцарей, как живые щиты. Нам пришлось прекратить огонь, чтобы не стрелять по своим.$B$BОсвободи наших рыцарей, которых держат на поле за базой, |3-6($c)!",
    O = "Освободите 8 опутанных рыцарей по заданию командира рыцарей Энтари из Оплота Серебряного Авангарда в Ледяной Короне.",
    T = "Тактика Плети",
  },
  [13009] = {
    D = "Еще неизвестно, сможет ли мой народ позабыть все обиды и вспомнить о том, что когда-то мы с Торимом были соратниками и друзьями.$b$bПусть эти доспехи хотя бы напоминают ему о тех днях, когда мы с честью сражались плечом к плечу, непобедимые.",
    O = "Отнесите перекованные доспехи Торима в Храм Штормов по просьбе Ньормельда.",
    T = "Новое начало",
  },
  [1301] = {
    D = "Перед тем, как перебраться сюда, в \"Синий Отшельник\", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.$b$bИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.$b$bЕсли вдруг ненароком встретишь его, кланяйся от меня.",
    O = "Поговорите с Винсентом Хьялом в Гавани Менетилов.",
    T = "Джеймс Хьяль",
  },
  [13010] = {
    D = "Остался всего один шаг до того, как я верну свой дом на Террасе Творцов.$B$BНужно найти Кролмир.$B$BВ тот злосчастный день я швырнул его о землю со всей силой и яростью, на которые был способен. Последовал страшный взрыв.$B$BДолгие годы я считал его утраченным, но теперь мне хотелось бы удостовериться...$B$BВозвращайся к королю Йоккуму и попробуй выяснить – вдруг он что-то знает о судьбе моего молота.",
    O = "Поговорите с королем Йоккумом в Дун Ниффелеме и попробуйте выяснить, что ему известно о Кролмире, принадлежавшем Ториму.",
    T = "Кролмир, Молот Бурь",
  },
  [13011] = {
    D = "У меня есть для тебя поручение. Если справишься, это поможет тебе заслужить уважение моего народа.$b$bЙормунгары представляют серьезную угрозу, и с ними следует разобраться как можно скорее. Если им ничто не препятствует, они плодятся, как кролики, и распространяются, как пожар.$b$bОни появились на юго-западе, в пещере зимней спячки. И если в самое ближайшее время мы не убьем их матку, они захватят все наши земли.$b$bОна вечно голодная и никогда не отказывается от пищи. Возьми этот нож, найди в их пещере свежий труп медведя и срежь мясо с его боков. Положи мясо рядом с кратером, где она обитает, и убей ее, пока она будет кормиться.",
    O = "По приказу короля Йоккума из Дун Ниффелема убейте Йормуттар в пещере зимней спячки.",
    T = "Ненасытная Йормуттар",
  },
