  [13176] = {
    D = "",
    O = "",
    T = "Подготовка к доставке",
  },
  [13177] = {
    D = "Добро пожаловать в крепость Ледяных Оков, $n. Твое задание будет очень простым. Одержи победу над десятью представителями Орды. А теперь ступай! Принеси победу Альянсу!",
