  [13265] = {
    D = "",
    O = "",
    T = "Сбор ткани",
  },
  [13266] = {
    D = "В день, когда за мной придет моя смерть, я хотел бы сказать, что жизнь прошла не зря. Те, кто станут оплакивать мою гибель, будут знать, что я был вождем, который принимал решения на благо своего народа.$B$BНо предательство Вариматаса и Гнилесса...Все, над чем мы работали, пошло прахом.$B$B<Тралл тяжело вздыхает.>$B$BПравосудие должно свершиться.$B$BПорталы, ведущие в Подгород, будут немедленно открыты. Вол'джин будет ждать тебя. Вскоре я присоединюсь к тебе. Вместе мы сделаем то, что нужно сделать, $n.",
    O = "Воспользуйтесь порталом в Подгород, расположенном в крепости Громмаш, и доложите о своем прибытии Вол'джину.",
    T = "Жизнь без сожалений",
  },
  [13267] = {
    D = "Весь Подгород под контролем Вариматаса. Наши солдаты находятся в боевой готовности, ожидая от вождя приказа идти в атаку.$B$BПомоги Орде отвоевать Подгород и встань в один ряд с нашими самыми великими воинами! Если останешься в живых, доложись Траллу.$B$BДай вождю знать, когда будешь $gготов:готова; вступить в бой.",
    O = "Помогите Траллу и Сильване вернуть Орде контроль над Подгородом.$B$BВ случае успеха отрапортуйте об этом Траллу.",
    T = "Битва за Подгород",
