  [13475] = {
    D = "",
    O = "",
    T = "Великая честь",
  },
  [13476] = {
    D = "Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$b$bСтупай же и вступи в схватку с Альянсом на всех фронтах. За честь! За Орду!",
    O = "Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.",
    T = "Великая честь",
  },
  [13477] = {
    D = "",
    O = "",
    T = "В едином порыве",
  },
  [13478] = {
    D = "В войне против Орды решающей может оказаться любая битва, $gсынок:дочка;.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$b$bАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.",
    O = "Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.",
    T = "В едином порыве",
  },
  [13479] = {
    D = "Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $Gдруг:дорогая;, потому что мне как раз $Gнужен проворный помощник:нужна проворная помощница;.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.",
    O = "Принесите весеннему сборщику 20 осколков раскрашенной яичной скорлупы.",
    T = "Большая охота за яйцами",
  },
  [13480] = {
    D = "Ах, Сад чудес, праздник весны и жизни! Надеюсь, тебе понравилось собирать яйца, $Gдруг:дорогая;, потому что мне как раз $Gнужен проворный помощник:нужна проворная помощница;.$B$BЯ не знаю, какую магию использовали при создании этих яиц, а друиды играют со мной в молчанку. Будешь разбивать яйца – сохрани для меня осколки скорлупы. Содержимое яиц можешь оставить себе, мне же понадобятся только скорлупки.",
    O = "Принесите весеннему собирателю 20 осколков раскрашенной яичной скорлупы.",
    T = "Большая охота за яйцами",
  },
  [13481] = {
    D = "Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BЯ не могу уйти сам, но с твоей помощью, |3-6($c), мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?",
    O = "Проводите отца Камароса в безопасное место и доложите об этом брату Кельтану на борту \"Молота Оргрима\".",
    T = "Валим отсюда!",
  },
  [13482] = {
    D = "Свет ко мне милостив. Я до сих пор не погиб в этом ожившем кошмаре, но если мне не удастся отсюда выбраться, приспешники Плети убьют меня, раздерут мое тело на части и используют их для своих \"работ\".$B$BЯ не могу уйти сам, но с твоей помощью, |3-6($c), мне, может быть, и удастся спастись, и я еще повоюю с силами Плети.$B$BПоможешь мне выбраться, пока мясники Плети меня не нашли?",
    O = "Проводите отца Камароса в безопасное место, а затем сообщите об этом Абсалану Благочестивому на борту \"Усмирителя небес\".",
    T = "Валим отсюда!",
  },
  [13483] = {
    D = "Если тебе не сидится на месте, то поищи магов в поселениях рядом со столицами – в Колючем Холме, Брилле, деревне Кровавого Копыта и на Площади Соколиных Крыльев. Им нужна помощь в каких-то исследованиях, и они нанимают большое количество охотников за яйцами. Больше сказать не могу, подробности узнаешь у магов.",
    O = "Поговорите с весенним сборщиком в Колючем Холме, Брилле, деревне Кровавого Копыта или Площади Соколиных Крыльев.",
    T = "Весенние сборщики",
