  [135] = {
    D = "Интересно, что имел в виду Вилли, когда упомянул о Каменщиках. Оговорился или проговорился? Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками? Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ. Покажите ему записку Вилли и посмотрите, сможет ли он пролить свет на эту тайну. Если вам не сразу удастся найти Шоу, поищите в Казармах в Старом городе.",
    O = "Отнесите записку Вилли Матиасу Шоу в Штормград.",
    T = "Братство Справедливости",
  },
  [13500] = {
    D = "",
    O = "",
    T = "Поклонение огню",
  },
  [13501] = {
    D = "",
    O = "",
    T = "Кулек конфет",
  },
  [13502] = {
    D = "Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.",
    O = "Соберите 10 праздничных шоколадных яиц и отдайте их продавцу Сада чудес вместе с позаимствованной корзиной для яиц.",
    T = "Что вам надо? Шоколада!",
  },
  [13503] = {
    D = "Вот – возьми эту корзину для яиц и ступай искать раскрашенные яйца. Возвращайся, когда наберешь десять праздничных шоколадных яиц.",
    O = "Соберите 10 праздничных шоколадных яиц и отдайте их торговцу Сада чудес вместе с позаимствованной корзиной для яиц.",
    T = "Что вам надо? Шоколада!",
  },
  [13524] = {
    D = "Ты... ты не $gодин:одна; из них? Быстрее! Освободи меня!$B$BНам нужно немедленно отправляться в Приют Янтарной Сосны! Как только лейтенант Думонт узнает, кто эти люди на самом деле, он камня на камне не оставит от этого города!",
    O = "Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Доложитесь лейтенанту Думонту по прибытии в Приют Янтарной Сосны.",
    T = "Побег из Среброречья",
  },
  [13538] = {
    D = "Три башни южнее реки Ледяных Оков вытягивают энергию из Крепости!$B$BУничтожь башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем возвращайся ко мне. И помни, только осадные машины могут навредить башне, поэтому тебе следует защищать их от Орды!",
    O = "Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, а затем вернитесь к офицеру-стратегу Абрамису на Озере Ледяных Оков.",
    T = "Южный саботаж",
  },
  [13539] = {
    D = "Хотя Альянс у нас на пороге, настоящий стратег всегда заглядывает дальше собственного носа.$B$B\"Напади там, где враг не готов дать отпор; появись там, где тебя не ждут.\"$B$B$n, я хочу, чтобы ты $gотправился:отправилась; через Реку Ледяных Оков и $gуничтожил:уничтожила; одну из башен на юге. Наши чернокнижники докладывают, что башни оттягивают энергию, которую мы могли бы использовать, чтобы укрепить наши войска.$B$BВозвращайся ко мне, как только ты разрушишь одну из башен.",
    O = "Уничтожьте башню Темного Взора, башню Огненного Дозора или башню Клинка Зимы, затем вернитесь к офицеру-стратегу Килрату.",
    T = "Свержение башен",
  },
  [13541] = {
    D = "",
    O = "",
    T = "",
  },
  [13548] = {
    D = "",
    O = "",
    T = "Кулек конфет",
  },
  [13549] = {
    D = "Помимо артефактов Драккари, меня также интересует животный мир Зул'Драка. Мне бы очень хотелось привезти в Зандалар некоторые образцы местной фауны. У меня уже есть самцы леопарда и ледолапого медведя, но теперь мне нужно несколько самочек!$B$BК великому сожалению, мой ловчий внезапно скончался. Может быть, ты подменишь его?$B$BПожалуйста, возьми это ружье, оно стреляет усыпляющими дротиками. Усыпи зверя и загляни ему под хвост. Запомни – меня интересуют самки. Леопарды и медведи водятся возле алтарей Рунока, Кетц'лун и Хар'коа.",
    O = "По просьбе летописца То'кини из Зим'Торги усыпляйте из воздушного ружья То'кини северных леопардов и ледолапых медведей. Возвращайтесь к нему, поймав по три самки каждого вида.",
    T = "Хвост трубой",
  },
  [13556] = {
    D = "Как дела, $gпацан:деваха;? Думаешь, ты сможешь мне помочь? Ба'Кини понадобится много яиц ящера для жертвоприношений Дубра'джину.$B$BЕсли бы не ритуалы, нас давно бы уже поработили драккари! Дубра'джин помогает нам!$B$BСобери яйца ящеров под деревьями здесь, в Гундраке. Иногда ящеры носят их с собой, чтобы держать их в тепле.",
    O = "Соберите 12 яиц ящера Гундрака по заданию Га'ваны из Дубра'джина.",
    T = "Яйца для Дубра'джина",
  },
  [13559] = {
    D = "",
    O = "",
    T = "Подношение Ходиру",
  },
  [13571] = {
    D = "",
    O = "",
    T = "Бюро находок Флетчера",
  },
  [1358] = {
    D = "Мой коллега из Калимдора, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей. Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел. $b$bХелбрим обосновался в Степях, в деревне под названием Перекресток. Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар. Направляйтесь на запад, в Степи, и вскоре дойдете до Перекрестка.",
    O = "Принесите образец сердца волка аптекарю Хелбриму в Степи.",
    T = "Образец для Хелбрима",
  },
  [1359] = {
    D = "Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах. Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца! $b$bЭто просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов. Отнесите их моей коллеге, аптекарю Зинг. Ее можно найти в главном представительстве нашего Общества в Подгороде.",
    O = "Отнесите образцы сердца волка аптекарю Зинг в Подгород.",
    T = "Посылка для Зинг",
  },
  [13592] = {
    D = "Турнир – это возможность помериться силой с другими героями, но стоит помнить и о том, что главный враг – Плеть – не дремлет. Ты оттачиваешь мастерство в поединках с товарищами, но тебе столь же необходимо совершенствоваться в битвах с неприятелем.$B$BОтправляйся на юго-запад Долины павших героев, что к северу от Корп'ретара – там приспешники Плети поднимают из небытия павших героев и обращают их против нас. Окажи честь нашим союзникам и упокой этих слуг Плети, тем самым подготовившись к настоящей битве.",
    O = "Убейте 10 обращенных героев по заданию сэра Маркуса Барлоу из Павильона Серебряного союза на Ристалище Серебряного турнира.",
    T = "Теория и практика",
  },
  [13593] = {
    D = "Приветствую тебя, чемпион. Я наслышан о твоих достижениях! Буду рад включить тебя в число участников делегации Штормграда, если ты желаешь к нам присоединиться.$B$BТы будешь тренироваться и совершенствоваться как прежде, но звание чемпиона Штормграда позволит тебе выступать под нашим флагом.",
    O = "Если вы хотите стать искателем славы Штормграда, поговорите еще раз с маршалом Якобом Алерием в Павильоне Серебряного союза.",
    T = "Искатель славы из Штормграда",
  },
  [136] = {
    D = "Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне. Так что мое сокровище теперь может стать твоим, главное – следуй подсказкам.$b$bСначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля. Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдешь мой сундучок. Загляни внутрь за следующей подсказкой.",
