  [160] = {
    D = "Отнеси это письмо Элло Чернодреву, мэру Темнолесья.$b$bМы с ним старые друзья... и когда он прочтет и узнает, что ты для меня $gсделал:сделала;... уверен, он будет так же счастлив, как и я! Ха-ха-ха!",
    O = "Отнесите письмо Аберкромби Элло Чернодреву, мэру Темнолесья.",
    T = "Письмо для мэра",
  },
  [161] = {
    D = "Если мои подозрения верны, то это взрывчатый порошок. Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело. Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола. Путь предстоит нелегкий и опасный, $N.$b$bПройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре. Советую не сходить с дороги и не задерживаться.",
    O = "Главный инженер Плотиннер хочет, чтобы вы отнесли странно пахнущий порошок Ашлану Камнехмылу, специалисту по взрывчатым веществам в лагере Мо'грош.",
    T = "Прямая и черная угроза",
