  [1618] = {
    D = "Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются!$B$BНа Красногорье время от времени устраивают налеты орки Черной горы, а снаряжения туда всегда мало поставляется. Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей.",
    O = "По просьбе Тормуса Подземной Кузни отнесите 4 рунических медных пояса и 4 тяжелые медные кувалды Вернеру Осгуду в Красногорье.",
    T = "Экипирование Красногорья",
  },
  [162] = {
    D = "Прошу тебя, отнеси этот отчет кому-нибудь, сведущему в такого рода вопросах.$b$bЯ слышал про одну ночную эльфийку по имени Грацина Сила Духа. Она посвятила много времени изучению форм жизни, встречающихся лишь в Азероте; она и историк заодно! Если ты хочешь, чтобы кто-то объяснил, что именно происходит и как это прекратить, обратись к ней. Нам любая помощь не помешает.$b$bГоворят, она сейчас в Храме Луны в Дарнасе.",
