  [237] = {
    D = "Горный пехотинец Кремневик превозносит тебя до небес, |3-6($r). Поэтому я хочу доверить тебе очень важное задание. Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны.$b$bОтправляйся в южные холмы и убей 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Это поможет нам выиграть время. Когда выполнишь задание, возвращайся.",
    O = "Горный пехотинец Булыжный Карьер просит вас убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов.",
    T = "Защита королевских земель",
  },
  [2378] = {
    D = "Ты много $gсделал:сделала; для ловчих смерти, но пришло время двигаться дальше. У тебя талант к искусству обмана и скрытности, но этот талант еще следует развить.$b$bУ ловчих смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам. Для начала поговори с Шентулом в Оргриммаре.",
