  [241] = {
    D = "Описание",
    O = "Краткое описание",
    T = "<TEST> ЭЙ МИСТЕР УИЛСОН!",
  },
  [2418] = {
    D = "Есть у меня зуб на этих дворфов Тенегорна! Пару лет назад они пригласили меня в крепость Ангор, чтобы я исследовал для них два образца прелюбопытнейших камней, привезенных с ульдаманского раскопа. Я провел исследования, и вообрази, что это было? Энергия! Каждый камень был мощнейшим источником энергии в сжатом, потенцированном виде – нужно только знать, как правильно высвободить ее! Чего только не найдешь в Ульдамане... $B$BВ общем, как только я рассказал об этом дворфам, они вышвырнули меня из крепости и направились в Ульдаман за чудесными камнями. $B$BМне бы такие, знаешь ли, тоже пригодились. Принеси мне несколько обоих видов, и я щедро вознагражу тебя.",
