  [24509] = {
    D = "",
    O = "",
    T = "Temp Quest Record",
  },
  [24510] = {
    D = "$C! Быстрее, иди сюда, нам надо поговорить.$B$BМоя покровительница, леди Джайна Праудмур, обнаружила брешь в обороне цитадели Ледяной Короны – некое место, известное как Кузня Душ. Она оставила мне поручение найти тех, кто мог бы ей помочь... и я надеюсь, что ты не откажешь в этой просьбе.$B$BПожалуйста, найди ее как можно скорее.",
    O = "Войдите в Кузню Душ со стороны Цитадели Ледяной Короны и найдите леди Джайну Праудмур.",
    T = "В ледяную цитадель",
  },
  [24511] = {
    D = "У нас не хватает людей, чтобы начать наступление на Цитадель, но такой шанс выпадает редко, его нельзя упускать.$B$BПробейся к дальнему концу подземелья и обеспечь нам проход к Яме Сарона. Мы должны закрепиться там, чтобы послать солдат дальше, в Цитадель.",
    O = "Чтобы обеспечить безопасный проход в Яму Сарона, убейте Броньяма и Пожирателя Душ.",
    T = "Тени замученных душ",
  },
  [24522] = {
    D = "Как можно быстрее отнеси Кель'Делар к Солнечному Колодцу! Мы должны поверить словам Утера о том, что оскверненный могуществом Короля-лича клинок не всегда будет тебе подвластен. Ты $gдолжен:должна; отправиться на Остров Кель'Данас и найти вход в сам Солнечный Колодец. Только он обладает силой очистить меч.$B$BУчти, что стражники Солнечного Колодца не позволят тебе пройти без разрешения, поэтому тебе придется заручиться поддержкой Халдарона Светлого Крыла, начальника охраны.",
    O = "Поговорите с Халдароном Светлым Крылом у входа на плато Солнечного Колодца на острове Кель'Данас.",
    T = "Путешествие к Солнечному Колодцу",
  },
  [24535] = {
    D = "Если Кель'Делар действительно у тебя, $n, я, возможно, смогу пропустить тебя в Солнечный Колодец. Как ты помнишь, этим мечом когда-то сражался Талориен Искатель Рассвета, защищая Колодец от Плети. Талориен пал на том месте, которое мы сейчас называем Тропой Мертвых. Ценой своей жизни он выиграл время, необходимое для того, чтобы его люди сумели подготовиться и встретить врага во всеоружии. Останки Талориена покоятся на этом острове в южном конце Тропы. Наведайся туда, и, если дух героя благословит тебя, я разрешу тебе пройти в Солнечный Колодец.",
    O = "Наведайтесь к останкам Талориена Искателя Рассвета и получите его благословение на владение Кель'Деларом.",
    T = "Талориен Искатель Рассвета",
  },
  [24536] = {
    D = "Присмотрись к этим ребятам. Хитрая Шестеренка уже не первый год заведует праздниками, а тут эти ребята сваливаются, как снег на голову. Они не входят в Хитрую Шестеренку, и картель нанял меня разобраться, что здесь к чему. Здесь просто невозможно дышать – и дело не только в духах.Возьми вот это устройство и проанализируй состав духов в воздухе среди стражей. Я хочу знать, что они в них добавляют. Здесь наверняка что-то нечисто.",
    O = "С помощью анализатора воздуха Гвоздезуба изучите состав воздуха вокруг шести надушенных стражников, а затем вернитесь к детективу с результатами.",
    T = "Дышать нечем!",
  },
  [24541] = {
    D = "Я так и знал, что дело здесь нечисто! Сюда добавлен какой-то химикат, влияющий на подсознание, но с тем количеством, которое у меня есть, хороший анализ не сделаешь. Мне нужно намного больше.Но не вздумай покупать духи! Эти негодяи от меня ни гроша не получат. Нет, мы пойдем другим путем.Сейчас мы замаскируем тебя под посыльного. Я видел, головорезы из химической компании охраняют ящики с товарами возле ворот. Беги мимо, но не останавливайся – иначе они тебя раскусят. Они бросят тебе ящик – хватай его и тащи сюда!",
    O = "Замаскировавшись под посыльного, отправляйтесь к воротам Оргриммара, возле которых находятся товары Королевской химической компании. Добудьте ящик Королевской компании и вернитесь к детективу Крямсу Гвоздезубу в Оргриммар.",
    T = "Позаимствовать духи",
  },
  [24545] = {
    D = "Я дам тебе одно задание, |3-6($r), хоть это и противоречит моим убеждениям. Скорее всего ты не оправдаешь надежд.$b$bНо лучше забудь мои слова и посвяти все свои силы этому новому заданию. А я дам тебе необходимые знания и ресурсы. $b$bНайди Отмщение Света, молот, брошенный Артасом в Пещере Ледяной Скорби. Если усилить его саронитом и разъедающей кровью поганищ, он нам еще отлично послужит.",
    O = "Поместите Отмщение Света, 25 кусков древнейшего саронита, разъедающую кровь Гниломорда и разъедающую кровь Тухлопуза в кузню рун Верховного лорда Могрейна в Цитадели Ледяной Короны.$B$BРазъедающую кровь Гниломорда и Тухлопуза можно получить в рейде для 25 игроков в Цитадели Ледяной Короны.",
    T = "Святость и скверна",
  },
  [24547] = {
    D = "Грань Тьмы – одно из самых могущественных орудий, которым может владеть |3-6($c).$b$bТеперь твоя жажда власти утолена?$b$b<Вы ощущаете на себе проницательный взгляд Могрейна.>$b$bЯ полагаю, что нет. В таком случае, вот мое последнее предупреждение...$b$bТы приступаешь к самой опасной части своей миссии. Обуздай свои желания, ибо если твои устремления порочны, то душа твоя обречена.$b$bЭтот клинок – не более чем пустой сосуд, тень того, чем он может стать.",
    O = "Верховный лорд Дарион Могрейн поручил вам убить 50 слуг Короля-лича в Цитадели Ледяной Короны с помощью Грани Тьмы. Души будут засчитаны в рейде на 10 или 25 игроков.",
    T = "Пиршество душ",
  },
  [24548] = {
    D = "Трон Короля-лича некогда служил его тюрьмой. Сам Кил'джеден выковал сосуд из ледяных кристаллов Круговерти Пустоты с единственной целью – заключить в нем мятежную душу Нер'зула.$b$bРазбив кристальную тюрьму с помощью Ледяной Скорби, Артас освободил дух Нер'зула и позволил ему слиться со своей душой. Осколки этого кристалла до сих пор рассыпаны по всей цитадели. $b$bЧтобы сила твоего оружия навеки пребывала в нем, мне потребуются только те осколки, что находились во владении самых могущественных прислужников Короля-лича.",
    O = "Верховный лорд Могрейн поручил вам собрать 50 осколков Льда Тьмы.$B$BОсколки Льда Тьмы можно получить только в рейде 25 игроков.",
    T = "Расколотый трон",
  },
  [24549] = {
    D = "",
    O = "Верховный лорд Могрейн просит вас принести ему Грань Тьмы.",
    T = "Темная Скорбь...",
  },
  [24553] = {
    D = "Признаюсь, я сомневался в том, что тебе удалось перековать Кель'Делар и что дух Талориена удостоит тебя вниманием. Ты не представляешь, что означает для меня и моего народа возвращение легендарного меча. $B$BКак и было обещано, я разрешаю тебе пройти к Солнечному Колодцу и встретиться с властителями Луносвета. Погрузи меч в Солнечный Колодец. После очищения его сила будет навеки связана с тобой. Затем отнеси меч Каладису Сияющему Копью в Покой Кель'Делара.",
    O = "Окуните закаленный Кель'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.",
    T = "Очищение Кель'Делара",
  },
  [24554] = {
    D = "Эта потертая рукоять меча знавала лучшие дни, но даже сейчас по ней можно сказать, что делал ее настоящий мастер.$B$BИзящная гравировка и инкрустация драгоценными камнями свидетельствует о том, что оружие некогда принадлежало знатному человеку. Похитителей Солнца наверняка заинтересует эта находка. Найдите их представителя в Покое Кель'Делара к югу от ристалища Серебряного Турнира.",
    O = "Принесите потертую рукоять Миралию Блеску Солнца в Покой Кель'Делара, что к югу от ристалища Серебряного Турнира.",
    T = "Потертая рукоять",
  },
  [24555] = {
    D = "Ошибки быть не может – это рукоять могущественного древнего клинка. Вот только что это был за клинок? Я не могу вспомнить ни одного меча с такой гравировкой, но не все еще потеряно.$B$BМы должны обратиться к Кориалстразу, более известному тебе как Крас. Он – давний друг кель'дорай и Кирин-Тора. За его плечами мудрость рода красных драконов; наверняка, он сможет нам помочь. Отправляйся за его советом на вершину Храма Драконьего Покоя, после чего поговори с Магистром Хаторелем в даларанском Прибежище Похитителя Солнца.",
    O = "Поговорите с Красом на вершине Храма Драконьего Покоя.",
    T = "То, что знают драконы",
  },
  [24556] = {
    D = "Заслать тебя в Серебряный Анклав будет нелегко. Туда допускаются только обладатели гербовых накидок Серебряного союза. Если бы нам только удалось заполучить одну из них, остальное можно было бы решить с помощью пары заклинаний.$B$BНо у меня есть идея! На балконе над \"Нитями судьбы\" стоит некто Шанди Шикблеск. Я его пару раз выручал в прошлом, так что он задолжал мне ответную услугу. Он стирает одежду многих граждан этого города. Может быть, он согласится одолжить тебе гербовую накидку...",
    O = "Позаимствуйте у Шанди Шикблеска гербовую накидку.",
    T = "Подходящая маскировка",
  },
  [24557] = {
    D = "Один из моих шпионов в Клоаке заметил представителя Серебряного союза, которые, как ты понимаешь, редко проявляют интерес к тому, что творится в канализации. А этот околачивался вокруг таверны \"Ведьма ворон\". Несомненно, они что-то затевают.$B$BОтправляйся в Клоаку, найди этого прихвостня Серебряного союза и разберись с ним. Обыщи его тело – может быть, у него найдется информация о местонахождении той книги из Храма Драконьего Покоя. Нельзя допустить, чтобы она оказалась в Ледяной Короне.",
    O = "Перехватите приказы Серебряного союза.",
    T = "Планы Серебряного союза",
  },
  [24558] = {
    D = "Эту книгу надо немедленно отнести Миралию Блеску Солнца. Ты этим займешься? Никому другому я не могу доверить столь ценную ношу, а ты уже $gдоказал:доказала; свою верность, обхитрив Серебряный союз.$B$BТвой путь лежит в Покой Кель'Делара, что на юге от ристалища Серебряного Турнира в Ледяной Короне. Миралий будет ждать тебя вместе с мечом. Чем быстрее мы сможем распознать этот клинок, тем скорее сможем им овладеть и обратить против Короля-лича во имя Этаса Похитителя Солнца. Мы должны показать Даларану и Альянсу, кто достоин возглавить эту битву.",
    O = "Принесите книгу \"Древние клинки драконьей ковки\" Миралию Блеску Солнца в Покой Кель'Делара.",
    T = "Возвращение к Миралию Блеску Солнца",
  },
  [24559] = {
    D = "Нельзя допустить, чтобы великий Кель'Делар оставался расколотым и обесчещенным. Возьми фрагменты клинка вместе с потертой рукоятью и отправляйся в Яму Сарона, что в цитадели Ледяной Короны.$B$BВ этой яме слуги Короля-лича добывают и обрабатывают саронитовую руду. Только с помощью заряженного саронита можно перековать Кель'Делар.$B$BТы $gдолжен:должна; собрать саронитовые слитки и перековать меч, вопользовавшись молотом и наковальней начальника кузни.",
    O = "Возьмите 5 слитков зараженного саронита и молот начальника кузни, чтобы соединить фрагменты Кель'Делара и создать перекованный Кель'Делар.",
    T = "Перековать меч",
  },
  [24560] = {
    D = "Наконец-то фрагменты Кель'Делара воссоединились, и клинок снова стал целым. Но он еще не готов к битве, ибо для начала его надо закалить. Эти саронитовые зубцы очень хрупкие и могут отколоться в момент удара.$B$BНо глубоко под цитаделью Ледяной Короны есть Кузня Душ, в которой можно закалить подобный клинок. Отнеси Кель'Делар в обитель Пожирателя Душ и найди там горнило душ. Закали меч и принеси его мне. Я буду ждать тебя в Ледяных залах.",
    O = "Закалите перекованный Кель'Делар в горниле душ.",
    T = "Закалить клинок",
  },
  [24561] = {
    D = "Ты $gперековал и закалил:перековала и закалила; клинок, но я не чувствую в нем былой силы. Правильно ли я понял, что клинок побуждает тебя к действию, словно он обладает собственной волей?$B$BОсмелишься ли последовать его зову? Негоже великому мечу ржаветь в ножнах. Я боюсь, что мы никогда не узнаем его тайн, если не последуем велению его судьбы. Отнеси его в Залы Отражений, что в Цитадели Ледяной Короны, но будь $gготов:готова; ко всему. Я буду ждать тебя в Ледяных залах.",
    O = "Отнесите Кель'Делар в Покои Клинка, что в Залах Отражений.",
    T = "Залы Отражений",
  },
  [24562] = {
    D = "Как можно быстрее отнеси Кель'Делар к Солнечному Колодцу! Мы должны поверить словам Утера о том, что оскверненный могуществом Короля-лича клинок не всегда будет тебе подвластен. Ты $gдолжен:должна; отправиться на Остров Кель'Данас и найти вход в сам Солнечный Колодец. Только он обладает силой очистить меч.$B$BУчти, что стражники Солнечного Колодца не позволят тебе пройти без разрешения, поэтому тебе придется заручиться поддержкой Халдарона Светлого Крыла, начальника охраны.",
    O = "Поговорите с Халдароном Светлым Крылом у входа на плато Солнечного Колодца на острове Кель'Данас.",
    T = "Путешествие к Солнечному Колодцу",
  },
  [24563] = {
    D = "Ты ведь работаешь на Миралия Блеска Солнца, верно? Думаю, я знают способ испытать, что за клинок у тебя в руках. Полагаю, тебе известна история этого меча? Им владел Талориен Искатель Рассвета, что защищал Колодец от нашествия Плети. Талориен пал на том месте, что мы сейчас называем Тропой Мертвых. Ценой своей жизни он выиграл время, необходимое для того, чтобы его люди сумели подготовиться и встретить врага во всеоружии. Останки Талориена покоятся на этом острове в южном конце Тропы. Наведайся туда, и, если дух героя благословит тебя, я разрешу тебе пройти в Солнечный Колодец.",
    O = "Наведайтесь к останкам Талориена Искателя Рассвета и получите его благословение на владение Кель'Деларом.",
    T = "Талориен Искатель Рассвета",
  },
  [24564] = {
    D = "Истекают часы изгнания Кель'Делара. Тебя ждет Солнечный Колодец, $n.$B$BТам ты встретишь Лор'темара Терона, регента Кель'Таласа и Верховного магистра Роммата. Будь $gосторожен:осторожна; с ними, не давай вовлечь себя в политические махинации.$B$BСосредоточься на своей миссии. Когда ты будешь $Gготов:готова; завершить восстановление Кель'Делара, поговори с хранителем Солнечного Колодца. Окуни меч в Солнечный Колодец, а затем отнеси его Миралию Блеску Солнца в Покой Кель'Делара.",
    O = "Окуните закаленный Кель'Делар в Солнечный Колодец. Когда вы будете готовы войти на плато Солнечного Колодца, обратитесь к хранителю Солнечного Колодца.",
    T = "Очищение Кель'Делара",
  },
  [24576] = {
    D = "<Рока с отвращением выслушивает, почему вы пытаетесь выследить Снивела.> $B$BТо есть, все это время я была под действием заклинания этого алхимика? Как я только могла купиться на эту подставу! Ну, попадись мне только этот маленький мерзавец – разорву на части!$B$BЕсли он закончил все свои дела, то должен направляться к башне дирижаблей, что в центре Оргриммара. $n, нельзя допустить, чтобы он поднялся на борт и улетел, избежав наказания!$B$BБеги к башне как можно быстрее!",
    O = "Отправляйтесь к башне дирижаблей, что в центре Оргриммара, и допросите Снивела Ржавстера. Постарайтесь получить хоть какие-нибудь доказательства.",
    T = "Разговор по душам...",
  },
  [24579] = {
    D = "Сартарион, Ониксовый страж, охраняет яйца сумеречных драконов. Он обитает в Обсидиановом святилище, в Драконьих чертогах под Храмом Драконьего Покоя.$B$BСовет Шести приговаривает Сартариона к смерти!",
    O = "Убейте Сартариона.$B$BЭто задание можно выполнить на любом уровне сложности и любым составом рейда.",
    T = "Сартарион должен умереть!",
  },
  [2458] = {
    D = "Торговая Компания... Доводилось тебе слышать про такую?$b$bМы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели.$b$bНедавно мы получили сведения, что Торговая Компания затевает что-то крупное. Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом.$b$bКогда найдешь башню, используй это сигнальное ружье, потом подойди к Физзулу и отдай ему честь, как принято в Изувеченной Длани.",
    O = "Отыщите башню Торговой Компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.$b$bВозле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и отдайте честь, как принято в Изувеченной Длани (команда /честь).$b$bВсе нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным.",
    T = "Надежное прикрытие",
  },
  [24580] = {
    D = "Ануб'Рекан некогда был одним из сильнейших пауков-повелителей Неруба, но Королю-личу удалось захватить его и превратить в нежить.$B$BНыне владыка подземелий обитает в Паучьем квартале Наксрамаса, помогая Кел'Тузаду строить зловещие планы.$B$BСовет Шести приговаривает Ануб'Рекана к смерти!",
