  [2498] = {
    D = "Я только что получил известие, что Деналан с озера Аль'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников. Пожалуйста, поговори с ним и скажи, что тебя прислал я.$B$BТоропись, $n, ему нужна наша помощь.",
    O = "Релиан Зеленый Костер хочет, чтобы вы поговорили с Деналаном у озера Аль'Амет.",
    T = "Возвращение к Деналану",
  },
  [2499] = {
    D = "Я во всем разобрался! И сразу бросился сюда, чтобы найти тебя. На самом деле все так просто... порча переходит от одного древесника к другому, но только один из них является истинным источником.$b$bЭто Дубохмур, он поражен такой огромной опухолью, каких я еще и не видел. Я бы даже сказал гигантской.$b$bРаньше Дубохмур жил в пещере возле моего озера, но потом перебрался в закоулок северо-восточнее Родниковой реки. $n, найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!",
    O = "Снимите гигантскую опухоль с Дубохмура.",
    T = "Дубохмур",
  },
  [25] = {
    D = "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?$B$BСообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на все, что только подойдет поближе... то есть, на все, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса.$B$BНу, $Gготов:готова; принести пользу?",
    O = "Истребите 12 злобных элементалей воды на озере Мистраль, что к востоку от Туннеля Когтя и к юго-западу от заставы Расщепленного Дерева.",
    T = "Остановка у Каменного Когтя",
  },
  [250] = {
    D = "Хвала небесам, что хоть кого-то волнует наша Дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра! Не сомневаюсь, следующей целью Черного Железа станет именно Дамба. Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора.$b$bПотому-то ты мне и $gнужен:нужна;, $n. Я заметил саперов из клана Черного железа неподалеку от восточной части Дамбы. Разведай обстановку и возвращайся с уликами.",
    O = "Осмотрите область вокруг восточной части Дамбы и отыщите для главного инженера Плотиннера улику, указывающую на замыслы дворфов Черного Железа.",
    T = "Черная угроза",
  },
  [2500] = {
    D = "$C, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реагенты, которые можно отыскать в Бесплодных землях.$B$BВот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не $gлюбитель:любительница; сражений, можешь попросить о помощи друзей.$B$BЯ неплохо заплачу, если ты принесешь мне все необходимое.$B$BЧто скажешь?",
    O = "Добудьте в Бесплодных землях реагенты для Гхака Целителя и отнесите их ему в Телcамар.",
    T = "Пробежка по Бесплодным землям",
  },
  [2501] = {
    D = "Ты не раз меня $gвыручал:выручала;, $n. Я хотел бы дать тебе в награду рецепт зелья, которое ты уже $gпробовал:пробовала;, но взамен попрошу выполнить опасное поручение.$B$BВ этом сейфе находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.$B$BДобудь мне кровь дракона, и я отдам тебе рецепт.",
    O = "Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар.",
    T = "Пробежка по Бесплодным землям-2",
  },
  [25055] = {
    D = "Стихии разбушевались, |3-6($c). Землетрясения, от которых мы страдаем и которые грозят обрушить Стальгорн, – не обычные явления природы. Служители Земли пришли к мнению, что мы должны утихомирить стихии, пока они не разорвали Азерот на куски. Нам нужна твоя помощь, $n.$B$BЯ дам тебе мешок с припасами Служителей Земли. В нем ты найдешь две вещи: сапту стихий и тотем очищения. С помощью сапты ты увидишь, что творится в мире элементалей, и затем усмиришь встревоженных духов земли, воспользовавшись тотемом очищения.",
    O = "Гаван Серое Перо хочет, чтобы с помощью сапты стихий и тотема очищения из припасов Служителей Земли вы усмирили 20 потревоженных духов земли.",
    T = "Усмирение стихий",
  },
  [25092] = {
    D = "Стихии разбушевались, |3-6($c). Землетрясения, от которых мы страдаем, и пожары, грозящие спалить Оргриммар, – не обычные явления природы. Служители Земли пришли к мнению, что мы должны утихомирить стихии, пока они не разорвали Азерот на куски. Нам нужна твоя помощь, $n.$B$BЯ дам тебе мешок с припасами Служителей Земли. В нем ты найдешь две вещи: сапту стихий и тотем очищения. С помощью сапты ты увидишь, что творится в мире элементалей, и затем усмиришь потревоженных духов огня, воспользовавшись тотемом очищения.",
    O = "Провидица Бахура хочет, чтобы с помощью сапты стихий и тотема очищения из припасов Служителей Земли вы усмирили 20 потревоженных духов огня.",
    T = "Усмирение стихий",
