  },
  [2759] = {
    D = "Хотя Гальван покинул Пиратскую Бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера.$b$bВозьми этот знак и отдай его Макгевану в Пиратской Бухте.$b$bЕсли ты действительно с этим справишься, он поймет, что ты $gдостоин:достойна;. Я в тебя верю, $n!",
    O = "Поговорите с Макгеваном в Пиратской Бухте.",
    T = "В поисках Гальвана",
  },
  [276] = {
