  [2763] = {
    D = "Для нашего ремесла очень важно научиться добывать драгоценные камни. Немногие камни драгоценнее цитрина. Он во много раз усиливает ту магию, которую мы вкладываем в наши творения.$B$BНа сей раз мы усилим сорок слитков мифрила четырьмя цитринами. В результате ты получишь лучшее представление о магической гемологии и научишься создавать изысканные мифриловые наплечники.",
    O = "Принесите сорок мифриловых слитков и 4 цитрина Гальвану Древнему из Тернистой долины.",
    T = "Могущество камней",
  },
  [2764] = {
    D = "Если ты $gготов:готова; покинуть Гальвана, отправляйся в Прибамбасск.$B$BТам живет мой лучший ученик, Трентон Молот Света. Он научит тебя обращению с изысканным мифрилом. Впрочем, можешь остаться здесь и поучиться еще!$B$BАх да, Прибамбасск находится в Танарисе!",
    O = "Поговорите с Трентоном Молотом Света из Прибамбасска.",
    T = "Лучший ученик Гальвана",
  },
  [2765] = {
    D = "Я с первого взгляда понял, что ты станешь $gодним из моих лучших учеников:одной из моих лучших учениц;! Ты без колебаний $gотдал:отдала; Макгевану вещь, наделенную силой, лишь бы только встретиться со мной. Подобная слепая вера и преданность искусству должна быть вознаграждена.$B$BТы $gстал:стала; настоящим экспертом в кузнечном деле. Насладись же наградой!",
    O = "Получите награду у Гальвана Древнего!",
    T = "Кузнец-умелец!",
  },
  [2766] = {
    D = "Перед вами странный металлический предмет яйцевидной формы. Вы понажимали на кнопочки – и внезапно яйцо ожило и раскрылось. Очевидно, это какой-то гномский приборчик! Из механического яйца раздается искаженный разрядами голос:$b$b\"Меня зовут Карлс Пропеллерз. Мой автономный робот попал в аварию! Обнаруживший его получит награду! Прошу вас, доставьте этот маячок к роботу!$b$bЯ вычислил координаты робота – он находится в пещере рядом с Долиной Свирепого Утеса!\"",
    O = "Отнесите аварийный маяк к автономному роботу Карлса, в пещеру рядом с Долиной Свирепого Утеса.",
    T = "Найти КПХ-22/FE!",
  },
  [2767] = {
    D = "Из динамика снова слышится искаженный разрядами голос гнома:$b$b\"Мне необходимо перегнать КПХ-22/FE в просторное и безопасное место, чтобы начать длительную процедуру подготовки к взлету. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, на большую дорогу! Это самое подходящее место, и там достаточно просторно, чтобы аппарату было где развернуться.$b$bПроводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской Бухте, меня зовут Карлс Пропеллерз. Конец связи!\"",
    O = "Проводите КПX-22/FE в безопасное место, затем сообщите об этом Карлсу Пропеллерзу в Пиратской Бухте.",
    T = "Спасти КПХ-22/FE!",
  },
  [2768] = {
    D = "Сержант Блай обокрал меня! Он сказал, что он только одолжит, но он украл мой драгоценный изыскательский жезл!!! Без этого жезла как я буду знать, где бурить новые скважины под воду??$B$BНайди Блая и принеси мне мой жезл! Я услышал, что он вынудил его компашку низкопробных авантюристов идти за сокровищами в Зул'Фаррак, – город, расположенный на западе. Держу пари, там ты его и найдешь.$B$BНадеюсь, что он уже повстречался с троллями, потому что если тебе придется драться с ним за мой жезл, то схватка выйдет нешуточная.",
    O = "Принесите изыскательский жезл главному инженеру Чепухастеру в Прибамбасск.",
    T = "Изыскательский жезл",
  },
  [2769] = {
    D = "Вы еще не встречались с братьями Медноштиф? Они на Мерцающей равнине в Калимдоре гоняют на своем болиде наперегонки с гоблинами. Обычно они выигрывают, что неудивительно: гоблинские машины взрываются так часто, что едва дотягивают до финишной черты!$B$BНо братья Медноштиф все равно постоянно ищут новые способы сделать свою машину еще более скоростной, и Виззл сказал мне, что ему нужен очень редкий компонент для очередных экспериментов.$B$BПохоже, ему надо с этим помочь. Спросите его на этот счет.",
    O = "Поговорите с Виззлом Медноштифом на Мерцающей равнине.",
    T = "Братья Медноштиф",
  },
  [277] = {
    D = "Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю!$B$BОтбери у гноллов их кремни, которыми они высекают огонь. Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров.",
    O = "Принесите Ретилю Стражу Природы 9 необработанных кремней.",
    T = "Запрет на огонь",
  },
  [2770] = {
    D = "В пустыне Танарис есть город троллей – Зул'Фаррак, в глубине которого находится священный бассейн. Из этого бассейна тролли призывают огромное чудовище, Газ'риллу! Злобная энергия пронизывает это чудовище насквозь, до самых кончиков его чешуи. И именно эту энергию я хочу использовать в своей машине!$B$BПринеси мне наэлектризованную чешую Газ'риллы.$B$BНо только помни, что тролли держат способ призывания этого монстра в тайне, и просто так они с ней не расстанутся.",
    O = "Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину.",
    T = "Газ'рилла",
  },
  [2771] = {
    D = "Похоже, таков был замысел учителя. Меня он научил делать одни предметы, а тебя другие.$b$bУчитель мудр, $n! Мы обучим друг друга!$b$bНаучи меня делать мифриловые капюшоны и изысканные мифриловые наплечники, а я покажу тебе, как куется изысканный мифриловый шлем.",
