  },
  [2782] = {
    D = "Табличка покрыта письменами троллей из племени Сухокожих. Да, секрет Рин'джи и впрямь оказался очень загадочным.$B$BВозможно, эта табличка представляет собой немалую ценность, хотя может быть и с точностью до наоборот. Тролль из племени Сухокожих в беде мог пообещать что угодно, лишь бы его спасли...",
    O = "Отнесите табличку Оран Змеиные Кольца в Квартал Магов Подгорода. Оран – известная ученая, изучающая троллей из племени Сухокожих, и она наверняка сумеет прочесть надписи на табличке.",
    T = "Секрет Рин'джи",
