  [3118] = {
    D = "Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну.",
    O = "Поговорите с Фрагуном Шепотом Тени в Альдрассиле, что в Тенистой долине.",
    T = "Зашифрованный знак",
  },
  [3119] = {
    D = "Этот знак был передан мне посланником нашей наставницы жрецов, Шанды. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде.",
    O = "Поговорите с Шандой в Альдрассиле, что в Тенистой долине.",
    T = "Благословенный знак",
  },
  [312] = {
    D = "У меня был месячный запас вяленой солонины на зиму. Я запер его в ларь, чтобы медведи не добрались. Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь! Но он не смог взломать ториевый замок. Но я же с голоду помру, если не верну свое мясо!$b$bТы вроде посильнее меня будешь. Может, сумеешь вернуть мой запас? Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь.",
    O = "Добудьте из пещеры Старого Ледоборода вяленое мясо из краденого ларя Тундры Макгранна.",
    T = "Ограбление тайника Тундры Макгранна",
  },
  [3120] = {
    D = "Этот знак был передан мне посланником нашего наставника друидов, Марданта. Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Марданту.",
    O = "Поговорите с Мардантом Крепким Дубом на древе Альдрассил, что в Тенистой долине.",
    T = "Зеленый знак",
  },
  [3121] = {
    D = "Для начала мне понадобится помощь Ксераша Огненного Клинка из павильона Лорисс, что рядом с лагерем Мохаче! Он изготовил состав, который нужен мне для... ну, потом увидишь.$b$bВ общем, отправляйся к Огненному Клинку. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Ксерашу в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Ксераш останется доволен.",
    O = "Отнесите сушеную голову Ксерашу Огненному Клинку в павильон Лорисс в Фераласе.",
    T = "Странная просьба",
  },
  [3122] = {
    D = "Вот травы, $n. Отнеси их знахарю Узер'и.$b$bИ, пожалуйста, передай ему, что сушеная голова – то, что надо.",
    O = "Отнесите знахарю Узер'и в Фералас мешочек для трав Ксераша.",
    T = "Возвращение к знахарю Узер'и",
  },
  [3123] = {
    D = "Это будет испытание – испытание придуманного мною ритуала и твоих способностей. Возьми этот сосуд, $n. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ.$b$bОтправляйся в дикие земли и отыщи диких существ. Медведи-сталемехи и длиннозубы-охотники станут твоей первой добычей, $n. Убивай этих существ и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть.",
    O = "Убейте 10 медведей-сталемехов или длиннозубов-охотников, и используйте сосуд уменьшения, чтобы уменьшить и пленить их.$b$bОтнесите 10 уменьшенных зверей знахарю Узер'и в Фералас.",
    T = "Испытание сосуда",
  },
  [3124] = {
    D = "Ты уже $gдоказал:доказала;, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание.$b$bГиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их тверды и преданны.$b$bТвоя задача – убить 10 блеклоперых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.",
    O = "Убейте 10 блеклоперых гиппогрифов любого вида, затем используйте сосуд уменьшения, чтобы уменьшить и пленить их.",
    T = "Уменьшенный гиппогриф",
  },
  [3125] = {
    D = "$n, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Чудесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.$b$bУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.",
    O = "Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы заключить в них духи павших чудесных дракончиков.",
    T = "Уменьшенный чудесный дракончик",
  },
  [3126] = {
    D = "Следующей нашей добычей, $n, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!$b$bИ вскоре мы сможем использовать их мощь в своих целях.$b$bОтыщи 3 бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!",
    O = "Убейте 3 бродячих лесных древней. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.",
    T = "Уменьшенный древень",
  },
  [3127] = {
    D = "Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника.$b$bКогда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.$b$bЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!",
    O = "Убейте 7 сухопутных бродяг или скальных великанов. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших скальных великанов.",
    T = "Уменьшенный горный великан",
  },
  [3128] = {
    D = "Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.$b$bВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и чудесных дракончиков на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.",
    O = "Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер'и в Лагерь Мохаче.",
    T = "Натуральные ингредиенты",
  },
  [3129] = {
    D = "Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.",
    O = "Подождите, пока знахарь Узер'и готовит оружие.",
    T = "Оружие духа",
  },
  [313] = {
    D = "Из-за катаклизма множество троггов выбрались на поверхность, в связи с чем тролли из племени Мерзлогривов были вынуждены спасаться бегством. К сожалению, они поселились совсем рядом с нами, и это создает для нас проблемы.$b$bЯ отдал распоряжение горному пехотинцу Данстану отправиться вместе со своим отрядом в Серую берлогу, что к юго-западу отсюда, приглядывать за живущими там вендиго, но сейчас мне нужно, чтобы они вернулись в Каранос. Найди их и скажи, чтобы они установили в Серой берлоге роботов удаленного наблюдения, полученных от гномов, а сами отправлялись в Каранос.",
    O = "Сообщите о распоряжениях капитана Таррана горным пехотинцам Данстану, Льюину и Валгруму. Их можно найти в Серой берлоге.",
    T = "Вести наблюдение издалека",
  },
  [3130] = {
    D = "В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным.$b$bКак бы то ни было, Латроникус тебя ждет. Пока что ты $gпоказал:показала; себя молодцом, $n. Продолжай в том же духе!$b$bМожешь идти.",
