  [334] = {
    D = "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, |3-6($c) вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать...$B$BПрошу вас, $n! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов.",
    O = "Отправляйтесь в суконную лавку Ларсона в Квартал Магов Штормграда, и передайте Турману Шнайдеру его набор для шитья.",
    T = "Посылка для Турмана",
  },
  [3341] = {
    D = "В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям все куда серьезнее...$B$BЖивущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладовей.$B$BУ Амненнара прямая телепатическая связь с Нер'зулом; мы должны прервать ее, $n. Да сгинет Хладовей!",
    O = "Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп.",
    T = "Да сгинет Хладовей",
