  [3384] = {
    D = "",
    O = "",
    T = "<UNUSED>",
  },
  [3385] = {
    D = "Они называют себя Черным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей.$B$BИ что еще хуже, $n, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Черного Железа.$B$BМы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца.$B$BОтправляйся в Котлован немедля!",
    O = "Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит.",
    T = "Черный рынок",
  },
  [339] = {
    D = "Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! $b$bНо речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы 1, 4, 6 и 8 все еще в джунглях!",
    O = "Принесите 1, 4, 6 и 8 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю первую главу.",
    T = "Глава I",
  },
  [34] = {
    D = "Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом.$B$BТеперь мне долго не удастся посадить нарциссы. Они загублены! И во всем виноват мерзкий кабан. Положи конец этому паразиту! Принеси мне его клык, и я с удовольствием вознагражу тебя. Говорят, он пасется в полях на юго-западе от Приозерья, но порой заходит и сюда, в мой сад.",
    O = "Убейте Грубобрюха. Принесите Марти Джанроз клык вепря.",
    T = "Незваный гость",
  },
  [340] = {
    D = "Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров. Так и хочется самому себе наподдать за то, что упустил страницы!$B$BМне удалось собрать почти все, кроме 10, 11, 14 и 16.",
    O = "Принесите 10, 11, 14 и 16 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю вторую главу.",
    T = "Глава II",
