  [3401] = {
    D = "",
    O = "",
    T = "<UNUSED>",
  },
  [3402] = {
    D = "Мне нужно, чтобы ты лично $gдонес:донесла; весть о кончине Ковиса Визглику в Прибамбасск. Он будет так рад, что непременно щедро наградит тебя.",
    O = "Поговорите с Визгликом в Прибамбасске.",
