  [3405] = {
    D = "",
    O = "",
    T = "<UNUSED>",
  },
  [341] = {
    D = "Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлджедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у нее окончание! $B$BПохоже, нам недостает страниц 18, 20, 21 и 24. Они должны быть где-то неподалеку...",
    O = "Принесите 18, 20, 21 и 24 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю третью главу.",
    T = "Глава III",
  },
  [342] = {
    D = "А, Глава IV, захватывающий финал! И как она закончилась! $b$bНам не хватает всего лишь трех страниц этой главы. А именно – 25, 26 и 27. Стоит найти их – и последняя глава готова.",
    O = "Принесите 25, 26 и 27 страницы книги \"Зеленые холмы Тернистой долины\" Барнилу Каменному Горшку, чтобы собрать всю четвертую главу.",
    T = "Глава IV",
