  [3425] = {
    D = "",
    O = "",
    T = "<UNUSED>",
  },
  [343] = {
    D = "Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\". Копия этой книги должна быть в Королевской библиотеке крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!$B$BКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.",
    O = "Отправляйтесь в Королевскую библиотеку крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.",
    T = "Кстати, о стойкости духа",
  },
  [344] = {
    D = "\"Как закалялось железо\"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!$B$BНо о чем это я? Ах, да... \"Как закалялось железо\"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.$B$BУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.",
    O = "Поговорите с братом Пакстоном из Аббатства Североземья.",
    T = "Брат Пакстон",
  },
  [3441] = {
    D = "Выслушай меня, $gcтранник:странница;.",
    O = "Выслушайте Каларана Ветрореза.",
    T = "Божественное воздаяние",
  },
  [3442] = {
    D = "Ты $gпринял:приняла; правильное решение, $n. $B$BНадо нанести удар по самому уязвимому месту – четырем сторожевым башням. $B$BТебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придется потрудиться, кроме того, нужно добыть необходимые ингредиенты. $B$BПринеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чье пламя будет неугасимым. $B$BЧтобы достать эти ингредиенты, ищи големов и элементалей.",
    O = "Принести 4 сердца пламени и 4 меры масла големов Каларану Ветрорезу.",
    T = "Неугасимое пламя",
  },
  [3443] = {
    D = "Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары. Начнем с древка.$B$BВ Котловане надсмотрщики и работорговцы из клана Черного Железа используют оружие из зачарованного тория – особенно прочного сплава. Если ты принесешь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка.",
    O = "Принесите 8 окованных торием кинжалов Каларану Ветрорезу.",
    T = "Древко факела",
  },
  [3444] = {
    D = "Мне приходилось бывать в преддвериях затонувшего храма. Зло, таящееся в этом жутком месте, окутывает всякого, кто входит туда. Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол. Помню, есть там огромный круглый зал со множеством высеченных из камня змей.$B$BНе так давно мне попал в руки круглый камень, на котором была высечена подобная змея. Я велел послать его в мою мастерскую в Кабестане. Забери его оттуда, и возможно, я смогу ответить на твои вопросы.",
    O = "Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане.",
    T = "Круглый камень",
  },
  [3445] = {
    D = "Слыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Также как и мы с Троясом, он облазал многие развалины и останки древних поселений. Говорят, что он отправился изучать развалины строений троллей в Танарисе.$B$BУдачи в поисках, о нем давненько ничего не слышали!",
    O = "Найдите Марвона Клепальщика в Танарисе.",
    T = "Затонувший храм",
  },
  [3446] = {
    D = "В храме я видел круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня. Я всего лишь дотронулся до одной из них и угодил в ловушку! Произошел сильнейший взрыв – мне несказанно повезло, что я остался цел. Лежа там, на краю галереи, я заметил еще одну статую в самом низу зала – что-то вроде алтаря. Алтарь Хаккара, полагаю.$B$BПоложи этот знак на алтарь в Затонувшем храме – думаю, это поможет открыть его секреты.",
    O = "Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.",
    T = "Во глубине болот",
  },
  [3447] = {
    D = "Все, что я видел в Затонувшем храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе все как можно подробней. Круг статуй, сокрытый в храме – весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам.$B$BКогда я подошел к главному алтарю, в зале зажглись огни. Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната.$B$BОднако я должен предупредить тебя, $n. В храме заключено великое зло. Какие бы сокровища там не скрывались, древние силы будут яростно защищать их от посягательств.",
    O = "Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.",
    T = "Тайна камня",
  },
  [3448] = {
    D = "Недавно мне доверили задачу исследования Азшары – некогда прекрасного края, который эльфы называли домом. Это было в те времена, когда они занимались магией. Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас. Мы перевернем его по камушку, чтобы разгадать загадки нашего прошлого.$B$BМой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует.$B$BУ него здесь в городе есть небольшой дом рядом с Залом Тайн.",
    O = "Поговорите с Тимором в Стальгорне.",
    T = "Передача поручения",
  },
  [3449] = {
    D = "Некоторые эльфы в старину почитали магию не меньше самой Элуны. Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий. Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять.$B$BЯ был бы очень рад получить прорисовки этих рун из руин Эльдарата. Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами. Будьте осторожны, не только лига исследователей имеет свои интересы в Эльдарате.",
    O = "При помощи готовальни сделайте прорисовки руны Бет'Амары, руны Джин'йаэль, руны Маркри и руны Саэл'Хаи. Отправляйтесь на маленький островок близ южного полуострова Азшары и дайте сигнал пилоту Зиггсу Зажигателю забрать их.",
    T = "Чародейские руны",
  },
  [345] = {
    D = "Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но...$B$BЯ пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я еще не успел закончить работу... и сделать еще чернил я не могу!$B$BДля изготовления чернил мне нужна ретбанская руда из Красногорья. Старшина Ослоу из Приозерья – мой верный поставщик...",
    O = "Поговорите со старшиной Ослоу из Приозерья и расспросите его о ретбанской руде.",
    T = "Запас чернил",
  },
  [3450] = {
    D = "Я хочу, чтобы эти прорисовки были доставлены мне в башню, но вам незачем лично проделывать весь этот путь. Пусть их просто доставят из Азшары по воздуху.$B$BУ Зиггса Зажигателя есть перед мной должок, к тому же он скоро окажется в тех местах – он назначен патрулировать побережье. Поговорите с ним перед отъездом. Он даст вам сигнальное ружье, чтобы вы могли подать ему сигнал. Когда добудете прорисовки, отправляйтесь в условленное место и отдайте их ему, чтобы он доставил их в мою башню в целости и сохранности. Он должен быть в ангаре в Палатах Войны.",
    O = "Поговорите с Зиггсом Зажигателем в Стальгорне.",
    T = "Легкая доставка",
  },
  [3451] = {
    D = "А, так вас послал Тимор? Да, есть у меня перед ним должок. Это что? Ах, поганец! Ладно, я ему помогу. Значит, вам нужны сигнальное ружье и условленная точка... да легко.$B$BБлиз южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку. Берете ружье и даете оттуда сигнал. Я вижу сигнал и прилетаю забрать это... ну, что ему надо.",
    O = "Поговорите с Зиггсом Зажигателем в Стальгорне и получите от него сигнальное ружье.",
    T = "Сигнал \"Взять на борт!\"",
  },
  [3452] = {
    D = "Работа над факелом близится к завершению. Не хватет лишь одного компонента. $B$BВ горах к северо-западу отсюда есть большой лагерь Сумеречного Молота. Говорят, они носят при себе некие символы и идолов в дань уважения своему богу. Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони. Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела.",
    O = "Найдите знак Рагнароса и принесите его Каларану Ветрорезу.",
    T = "Защита пламени",
  },
  [3453] = {
    D = "Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары.",
    O = "Подождите, пока Каларан Ветрорез закончит факел Воздаяния.",
    T = "Факел воздаяния",
  },
  [3454] = {
    D = "Факел готов и отныне связан со своим владельцем. Возьми его, $n.",
    O = "Возьмите факел воздаяния.",
    T = "Факел воздаяния",
  },
  [346] = {
    D = "Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку.",
    O = "Вернитесь к брату Кристофу на Соборную площадь. Отдайте ему книгу \"Как закалялось железо\".",
    T = "Возвращение к Кристофу",
  },
  [3461] = {
    D = "Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернетесь в Стальгорн. Я уверен, что он до сих пор у себя в Палатах Магии. Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника... это уж точно.$B$BВсе же благодарю вас, что вы ему помогли, и желаю удачи.$B$BОй, готовальня мне ни к чему. Почему бы вам просто не отдать ее лично Тимору, когда вы с ним встретитесь?",
    O = "Принесите Тимору его готовальню назад в Стальгорн.",
