  [3506] = {
    D = "Вы поразмыслили еще немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится?$b$bВы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга – прочие же связаны с куда более жуткими тварями.$b$bВы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить.",
    O = "Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг'тору Кроволапу в Азшаре.",
    T = "Предательница",
  },
  [3507] = {
    D = "Вернись в Оргриммар к Белгрому. Он захочет увидеть ее голову своими глазами! Мы там тоже скоро будем.$b$bУдачный у нас денек! Спасибо за помощь, $n.",
    O = "Поговорите с Белгромом Каменной Булавой в Оргриммаре.",
