  [354] = {
    D = "Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки.",
    O = "Принесите останки Грегора, останки Ниссы и останки Тармена Колману Фартингу в Брилл.",
    T = "Смерти в семье",
  },
  [3541] = {
    D = "В Оргриммаре есть у меня скупщик краденого. У него притон в Волоке. Этого скользкого типа нелегко найти, если не знать точно где искать. Запомни: искать следует в одном из самых высоких зданий. $B$BТолько сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих. $B$BОн готов заплатить очень хорошую цену за табличку Джин'яэль. Не знаю, зачем уж она ему сдалась, но $gвидел:видела; бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где ее найти!",
    O = "Отнесите табличку Джин'яэль Джес'римону в Оргриммар.",
    T = "Доставка Джес'римону",
  },
  [3542] = {
    D = "Теперь ты отправишься к Андрону Ганту. Он обретается в Подгороде, недалеко от Района Фармацевтов. $B$BЭтот был более многословен, когда я спросила, зачем ему нужна табличка. Маги Подгорода хотят изучить некоторые тайные заклинания высокорожденных. Они считают, что табличка им в этом поможет. Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей. $B$BОтнеси ему табличку Маркри и возвращайся за своей долей.",
    O = "Отнесите табличку Маркри Андрону Ганту в Подгород.",
    T = "Доставка Андрону Ганту",
  },
  [355] = {
    D = "Ты $gпринес:принесла; мне останки Агамондов и $gутолил:утолила; мою жажду мести. Но мельницы этой проклятой семейки все еще представляют собой угрозу не только для меня, но и для всех Отрекшихся.$B$BЯ рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.",
    O = "Поговорите с мировым судьей Севреном в Брилле.",
    T = "Разговор с Севреном",
  },
  [356] = {
    D = "Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.$B$BНаш успех на Бастионе рассчитан на битву на один фронт: мы не можем допустить атаки с тыла и, уж конечно, не можем лишить наших защитников линии поставки припасов.$B$BОтправляйся на запад и убей любого приспешника Плети, которого встретишь. Обрати особое внимание на усадьбу Балнира – там настоящее гнездо этой Плети.",
    O = "Убейте 8 кровоточащих ужасов и 8 странствующих духов.",
    T = "Патруль в арьергарде",
  },
  [3561] = {
    D = "Последнюю табличку надлежит доставить весьма опасному человеку, $n. Можешь не сомневаться, я доверяю ему куда меньше,чем кому-либо из тех, к кому я тебя отправляла. $B$BВерховный маг Ксилем живет в башне в холмах, возвышающихся над Азшарой. Он человек, однако он не похож на людей, которых мне приходилось встречать... или убивать. Он необычайно властен. Я не смею спросить его, что он собирается делать с табличкой. $B$BОн сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним. Ищи Саната на севере.",
    O = "Отнесите табличку Саэль'Хай верховному магу Ксилему в Азшару.",
    T = "Доставка верховному магу Ксилему",
  },
  [3562] = {
    D = "Отнеси это послание Джедиге. Скажи ей, что я заплачу ей лично, когда она придет ко мне.$B$BСтупай скорее, $n. Скажи своей госпоже, что награда ожидает ее.",
    O = "Отнесите записку Магаты Джедиге в Азшару.",
    T = "Плата Магаты Джедиге",
  },
  [3563] = {
    D = "Отнеси это послание Джедиге. Скажи ей, что я доволен ее работой.$B$BСкажи, чтобы скорее возвращалась в Оргриммар – Джес'римон достойно наградит ее. $B$BПередай ей это, и, возможно, впредь я буду давать тебе поручения, $n.",
    O = "Доставьте записку Джес'римона Джедиге в Азшару.",
    T = "Плата Джес'римона Джедиге",
  },
  [3564] = {
    D = "Вот *ик!* держи *ик!* Это для Джедиги. И ты это, *ик* заходи, если что!",
    O = "Доставьте записку Андрона Джедиге в Азшару.",
    T = "Плата Андрона Джедиге",
  },
  [3565] = {
    D = "Что еще? Ах да, оплата. Конечно. $B$BВот, возьми и выметайся. Уверен, Джедига ждет не дождется твоего возвращения.",
    O = "Доставь записку Ксилема Джедиге в Азшару.",
    T = "Плата Ксилема Джедиге",
  },
  [3566] = {
    D = "Это... была... ловушка... $B$BПрости... меня... $B$BТы $gдолжен:должна; убить предателя... Отомсти ему за нас... За Ториуса...",
    O = "Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.",
    T = "Восстань, Обсидион!",
  },
  [3567] = {
