  [3641] = {
    D = "Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномом-инженером.",
    O = "Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн.",
    T = "Покажи свою работу",
  },
  [3642] = {
    D = "Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у тебя в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.$B$BЕсли ты по-прежнему хочешь заняться гномским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.",
    O = "Если вы согласны заниматься гномским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской Бухте.",
    T = "Договор о неразглашении",
  },
  [3643] = {
    D = "Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномом-инженером.",
