  [365] = {
    D = "Кто это тут? $gНовенький:Новенькая:c; |3-6($c)? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, отнеси их аптекарю Юхану в Брилл.",
    O = "Украдите 10 тыкв с западной фермы, к северу от Похоронного Звона. Потом отнесите эти тыквы аптекарю Юхану в Брилл.",
    T = "Поля Горя",
  },
  [366] = {
    D = "Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.$B$BМы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамена Короля-лича. Я рад, что он остался свободным.$B$BМы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас.",
    O = "Верните Гюнтеру книгу заклинаний. Его можно найти на острове, в приюте Гюнтера.",
    T = "Книга Гюнтера",
  },
  [3661] = {
    D = "Дикие совухи – очень непредсказуемые существа, $n. Они могут быть мягкими и пушистыми, но если что-то дорогое для них окажется под угрозой, в них проснется настоящий зверь!$B$BГоворят, что этих животных создала сама Элуна, и я хочу узнать, правда это, или нет.$B$BМного диких совухов обитает во Внутренних землях – целые популяции примитивных, злобных и диких совухов. Не хотите ли отправиться туда и принести мне их перьев?",
    O = "Соберите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут'теран.",
    T = "Любимцы Элуны?",
  },
  [367] = {
    D = "Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Темная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принесите мне 5 склянок крови пса Тьмы, чтобы я мог провести эксперимент.",
    O = "Принесите аптекарю Юхану 5 склянок крови псов Тьмы.",
    T = "Новая чума",
  },
  [368] = {
    D = "Пока ты $gсобирал:собирала; для меня образцы, я провел исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты. Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее.$B$BМне потребуется 5 чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу.",
    O = "Принесите аптекарю Юхану из города Брилл 5 чешуек мурлоков из племени Злобного Плавника из Тирисфальских лесов.",
    T = "Новая чума",
  },
  [3681] = {
    D = "Я вынужден прервать твое путешествие, |3-6($r). Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения.$B$BЕсли бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов.$B$BНайди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света.",
    O = "Разыщите в Штормграде Даториана Ралла и поговорите с ним.",
    T = "Фолиант Божественности",
  },
  [369] = {
    D = "Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов.$B$BПринесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах.",
    O = "Принесите Аптекарю Юхану из города Брилл 4 образца яда злобного ночного кругопряда.",
    T = "Новая чума",
  },
  [37] = {
    D = "Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся. Чтобы составить полный отчет, мне нужно выяснить, что с ними случилось.$B$BОтправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки.",
    O = "Отправляйтесь на север по реке и отыщите следы пропавших стражников – Рольфа и Малакаи.",
