  [412] = {
    D = "Мне следует вернуться в Гномреган и продолжить исследования, чтобы найти способ вылечить облученных гномов.$b$bНо я оставался в Караносе, потому что это мой город, и я хотел помочь защитить его от атак Мерзлогривов. Я занимался техобслуживанием и ремонтом паровых танков.$b$bПо какой-то причине падальщики Мерзлогривов стали таскать у меня гиромеханические шестерни, которые нужны для завершения ремонта. Все они на передовой Мерзлогривов. Не поможешь мне вернуть эти шестерни?",
    O = "Принесите Раззлу Шустрецу 8 гиромеханических шестерней.",
    T = "Операция \"Перенаправление\"",
  },
  [4120] = {
    D = "Я – охотник, и всегда стремлюсь превзойти силой своих противников. Запомни, $n: всегда можно обратить ситуацию в свою пользу, если хорошо знаешь врага.$b$bК северу от Ясеневого леса есть место, называемое Оскверненный лес. Тамошние звери запятнаны веществом, которое именуется скверной. Медведи и волки от него совершенно взбесились, но в то же время скверна сделала их сильнее обычного.$b$bСтупай, $n. Отправляйся в Оскверненный лес, чтобы встретиться с этими тварями лицом к лицу.",
    O = "Убейте 12 гризли злобных когтей и 12 опустошителей-сквернолапов в Оскверненном лесу по просьбе Тало Тернового Копыта из Лагеря Мохаче.",
    T = "Сила порчи",
  },
  [4121] = {
    D = "Ты в самом деле надеешься добраться до точки встречи, держа меня в плену? Ты и правда рассчитываешь, ворвавшись в крепость Черной горы и похитив главную ценность клана, удрать $gнезамеченным:незамеченной;?$b$bДа тебя в порошок сотрут!",
    O = "Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.$b$bЛекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.$b$bТакже отдайте Лекслорту ториевые оковы.",
    T = "Опасное положение",
  },
  [4122] = {
    D = "Я шел за ним через Тлеющее ущелье, через горы и Пылающие степи. Предателя поймали на месте преступления, когда тот передавал оркам Черной горы сверхсекретную информацию о деятельности нашего отряда. Я говорю о Грарке Лоркрубе. $B$BОн теперь в Пылающих степях, под их надежной охраной – по крайней мере, он сам так думает. $B$BВозьми эти оковы, $n. Найди Грарка, надень на него эти оковы и доставь сюда. Награда будет достойной.",
    O = "Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. $B$BПо обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника.",
    T = "Грарк Лоркруб",
  },
  [4123] = {
    D = "Сколько лет я ищу этот камень! Он называется \"сердце горы\". Размером как раз с твой кулак. Дворфы Черного Железа прячут его в своих тайных подвалах. Я пытался его купить, предлагал им хорошую цену, но они не продают!$B$BПридется забрать его силой, другого способа я не вижу.$B$BТебе надо пробиться на нижний ярус Глубин Черной горы, взломать потайной сейф и забрать сердце. Для того чтобы добраться до тайника, тебе придется сразиться с тамошним стражником. Его зовут Хватка Смерти, и он появится только тогда, когда ты вскроешь все сундуки и сейфы!$B$BУдачи.",
    O = "Принесите сердце горы Максворту Суперблеску в Пылающие степи.",
    T = "Сердце горы",
  },
  [4124] = {
    D = "Моему соратнику, Гинро Пылающему Очагу, нужна помощь. Он ищет курьера и пакеты, которые тот вез. Курьер пропал примерно неделю назад; наши собственные поиски результата не дали. Мы зашли в тупик. Пришлось объявить курьера пропавшим без вести.$b$bЕсли у тебя есть свободное время, пожалуйста, поговори с Гинро. Он должен быть где-то здесь. Возможно, он у себя.",
    O = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.",
    T = "Пропавший курьер",
  },
  [4125] = {
    D = "Прошла примерно неделя с тех пор, как Раскал, курьер, отправился в Таланаар. Фералас он знает, как свои пять пальцев – он был здесь с нами с самого начала, с тех пор, как генерал Оперенная Луна привела сюда экспедиционный корпус. Я знаю, что он собирался взять весельную лодку и проплыть вдоль побережья Фераласа, чтобы миновать лагерь Орды.$b$bЕго лодки я так и не обнаружил – но, возможно, тебе это удастся. Может быть, она спрятана либо потонула. А между тем именно лодка может помочь выяснить, где Раскал. Если найдешь что-нибудь, дай мне знать.",
    O = "Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа.",
    T = "Пропавший курьер",
  },
  [4126] = {
    D = "Подонки Черного Железа под предводительством гнусного Харли Чернопыха украли рецепт нашего лучшего светлого громоварского! Подлые твари! Они не достойны такого прекрасного напитка!$B$B$n, у меня есть для тебя работа. Отправляйся в Глубины Черной горы в Пылающих степях, уничтожь все бочонки со светлым громоварским, какие сумеешь найти, и забери у мерзавцев наш рецепт!$B$BПереверни все Глубины, но найди этот рецепт!",
    O = "Найдите украденный рецепт Громоваров и верните его Рагнару Громовару в Каранос.",
    T = "Харли Чернопых",
  },
  [4127] = {
    D = "Копаясь в иле, вы нащупываете рукоятку ножа. Похоже, тот, кто плыл на лодке, его потерял. Рядом валяются обломки самой лодки...$b$bВы берете нож с собой: Гинро Пылающий Очаг из Крепости Оперенной Луны велел вам принести ему все, что может помочь разгадать тайну. Однако вас не покидает ощущение, что вы тут не одни...",
    O = "Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли.",
    T = "Разбитая лодка",
  },
  [4128] = {
    D = "Здравствуй, $n. Ходят слухи, что кто-то украл у Рагнара Громовара его драгоценный эль. Бедолага рвет и мечет! Ему нужен отважный и дерзкий наемник, который возьмется за это дело. Рагнар готов хорошо заплатить.$B$BЕсли тебе интересно, переговори с ним. Он сейчас в своей \"Громоварке\" в Караносе. Это в Дун Мороге.",
    O = "Переговорите с Рагнаром Громоваром.",
    T = "Рагнар Громовар",
  },
  [4129] = {
    D = "У нас в крепости живет друид, Квинтис Ночной Костер, который умеет... много всего. В частности, он владеет сверхзнанием – способностью узнавать на ощупь историю предмета. Не спрашивай, как он это делает – я в этом не разбираюсь, и разбираться не хочу. Я знаю только две вещи: во-первых, я видел, как это работает, а во-вторых, этот друид у меня в долгу.$b$bКороче, тащи этот ножик к Квинту, в его жилище на дереве, и передай, что должок, который за ним числится, будет уплачен, если он разберется с этой штукой.",
    O = "Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.",
    T = "Тайна ножа",
  },
  [413] = {
    D = "Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан.$B$BМожет, он и не такой пивовар, как остальные Ячменовары, но свое пиво он любит, и я знаю, что это тоже ему понравится.$B$BНе отнесешь ему вот этот бочонок \"Мерцающего портера\"?",
    O = "Отнесите бочонок \"Мерцающего портера\" горному пехотинцу Ячменовару.",
    T = "\"Мерцающий портер\"",
  },
  [4130] = {
    D = "Извини, меня до сих пор немного пошатывает. Как бы то ни было, я увидел несколько полезных вещей.$b$bРаскал вытащил два больших кожаных заплечных мешка из своей лодки и направился прочь от воды. Однако потом вернулся к лодке. Вижу скальпы гноллов... он наткнулся на гноллов – кажется, это тот клан, который называют Древолапами. Он чем-то очень озабочен, даже вроде бы напуган. Раскал настолько поглощен своими мыслями, что не замечает, как у него за спиной материализуются элементали воды. И... и все. Больше я ничего не увидел.$b$bИзвини, $n. Мне необходимо отдохнуть. Расскажи Гину о том, что я видел. Ему следует это знать...",
    O = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.",
    T = "Сверхзнание",
  },
  [4131] = {
    D = "Возможно, Раскала сцапали наши \"друзья\" из клана Древолапов, но что-то мне подсказывает, что дело было не так. И все равно начать лучше всего с их лагерей.$b$bКонечно, хотелось бы иметь более отчетливые сведения, но пока что у нас нет ничего, кроме смутного указания на лагеря гноллов. Я знаю, что гноллы хранят у себя награбленное и дерутся из-за добычи. Возможно, они просто наткнулись на заплечные мешки, которые упоминал Кинт. Прежде я не рисковал соваться к гноллам, но теперь, когда у нас есть сведения, полученные от Кинта, попробовать стоит.",
    O = "Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера.",
    T = "Гноллы из стаи Древолапов",
  },
  [4132] = {
    D = "Ты $gпроделал:проделала; отличную работу, $n! Теперь пришло время для последнего задания. $B$BГенерал Кузня Гнева, ответственный за атаки Черного Железа на 109-ое подразделение Каргатского экспедиционного корпуса и массовые убийства наших солдат, должен понести наказание. $B$BЭто непростое задание, но в случае успеха труды окупятся сторицей.",
    O = "Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания.",
    T = "Операция:смерть Кузне Гнева",
  },
  [4133] = {
    D = "Тенемагу Вивиан Лягроб нужна твоя помощь. Она сейчас в Бесплодных землях, на сторожевой заставе Каргат. Там недавно прошел слух о небезызвестном напитке, сваренном дворфами Черного Железа в Глубинах Черной горы, – вот она и отправилась проверить.$B$BПоговори с Вивиан. Она тебя ждет.",
    O = "Переговорите с тенемагом Вивиан Лягроб в Каргате.",
    T = "Вивиана Лягроб",
  },
  [4134] = {
    D = "Ходят слухи, что Харли Чернопых из клана Черного Железа украл рецепт эля. Говорят, этот эль, иначе – светлое громоварское – придает великую силу и храбрость тому, кто его употребит. Нам хотелось бы изучить состав этого напитка. Может быть, мы найдем и другое применение его удивительным свойствам... подходящее для целей Отрекшихся.$B$BОтправляйся в Глубины Черной горы, найди Харли, забери у него рецепт светлого громоварского и принеси его мне.$B$BВозможно, тебе придется выманить Харли из укрытия. Для этого пригрози ему уничтожением его драгоценного эля.",
    O = "Принесите рецепт светлого громоварского Вивиан Лягроб в Каргат.",
    T = "Украденный рецепт громоварского",
  },
  [4135] = {
    D = "В рюкзаках находится два предмета: во-первых, посылка, адресованная в Таланаар, а во-вторых – записка, адресованная неизвестно кому.$b$bВ записке, набросанной торопливым почерком, говорится об обнаружении коварных насекомоподобных существ к югу от лагерей гноллов, в лесах, известных как \"Гудящая Бездна\". Автор сообщает, что намерен лично проникнуть туда, поскольку речь может идти о серьезной опасности, грозящей всему Фераласу. Записка подписана \"Раскал из Оперенной Луны\".$b$bПохоже, вам наконец-то удалось выяснить, куда делся Раскал...",
    O = "Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов.",
    T = "Гудящая Бездна",
  },
  [4136] = {
    D = "Мой братец Риббли всегда только и делал, что тянул денежки из семьи и тратил их на какие-то поганые махинации.$B$BПохоже, последний его проект оказался поганее прочих, потому что барон Ревилгаз из Пиратской Бухты назначил награду за голову бедняжки Риббли. Ты даже не представляешь, как возрадовались все Крутипробы! Наш малыш Риббли наконец хоть чего-то да стоит!$B$BНо сейчас он скрывается в Глубинах Черной горы. Найди его и приведи ко мне!$B$BА если он не пойдет добром... ну что ж, не пойдет – и не надо... тогда принеси мне его голову.",
    O = "Принесите голову Риббли Юке Крутипроб в Пылающие степи.",
    T = "Риббли Крутипроб",
  },
  [414] = {
    D = "Я бы и еще отхлебнул \"Мерцающего портера\" с хмелеварни моего братца – забористое же пойло! Но я хочу, чтобы мой приятель-пехотинец попробовал его. Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телcамар в озере Лок Модан.$B$BЧтобы добраться до Телcамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток. И по той дороге иди прямо до Телcамара.$B$BОтдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!",
    O = "Отнести бочонок \"Мерцающего портера\" горному пехотинцу Кэдреллу.",
    T = "Портер для Кэдрелла",
  },
  [4141] = {
    D = "Видишь Лариона вон там? Это ОН виноват, что мы застряли здесь! $B$BЯ говорил ему, что мы идем не туда, но разве он меня слушал? И представляешь, после этого он еще и не желает со мной разговаривать! Ну, пока он не передумает, я позабавлюсь! $B$BТы $gзаметил:заметила; здесь таких странных созданий, похожих на цветы? На самом деле это довольно умные зверушки. Думаю, их можно надрессировать на всякие фокусы. $B$BВ первую очередь, мне нужны образцы для изучения. Сможешь принести мне несколько?",
    O = "Соберите 15 кровоцветов и принесите их Муиджину.",
    T = "Муиджин и Ларион",
