  [4289] = {
    D = "В этом кратере встречается множество странных зверей – они похожи на тех, что водятся на моей родине, но выглядят более... породистыми. Я не могу объяснить это, но мне кажется, это место – средоточие силы Матери-Природы. Я воздаю ей хвалу всякий раз, как встречаю одно из ее прекрасных созданий в этом кратере. $B$BЕсли ты тоже хочешь достигнуть просветления, отправляйся на север. Там ты найдешь огромных обезьян, помериться силами с которыми сочтет за честь самый искусный воин. Принеси мне их шкуры, докажи свою силу!",
    O = "Принесите 2 шкуры Ун'Горской гориллы, 2 шкуры Ун'Горского топтуна и 2 шкуры Ун'Горского рокотуна землепроходцу Торве к входу в Кратер Ун'Горо.",
    T = "Обезьяны Ун'Горо",
  },
  [429] = {
    D = "Мой брат Квинн был тяжело ранен вурдалаком, Иваром Нечистым, и я не знаю, сможет ли он как следует поправиться без помощи магии. Хотя я сама и не фармацевт, но знаю, что наши аптекари могут изготавливать исцеляющие зелья из обесцвеченных сердец воргов. $b$bСобери такие сердца и отнеси их аптекарю Ренферрелу к Гробнице, на юг отсюда. А потом возвращайся ко мне с зельем. $b$bМножество воргов водится между этим местом и садом Мальдена к востоку отсюда.",
    O = "Соберите 6 обесцвеченных сердец ворга и принесите их аптекарю Ренферрелу в Гробницу.",
    T = "Звериные сердца",
