  [4484] = {
    D = "",
    O = "",
    T = "Манускрипт ненасытности",
  },
  [4485] = {
    D = "Приветствую, $n. Я вижу, твоя решимость по-прежнему сильна, как и твоя вера.$b$bДумаю, настало время тебе поговорить с Даторианом Раллом в Штормграде. Ты $Gдолжен:должна; получить еще несколько уроков, и я чувствую, ты к ним $Gготов:готова;.$b$bНайди Даториана в Соборе Света – и пожалуйста, $n, отнесись к его урокам серьезно. Ты $Gдобился:добилась; своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись $Gвысокомерным:высокомерной;.$b$bУдачи тебе.",
    O = "Поговорите с Даторианом Раллом в Штормграде.",
    T = "Фолиант благородства",
  },
  [4486] = {
    D = "Ну-ка, ну-ка, поглядите на могучего паладина во всей красе!$b$bПрошу прощения, $n, я не в обиду... Просто иногда немного завидую твоим достижениям. Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток. Но пока не преуспел, $Gсам:сама; понимаешь.$b$bНо вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому $Gготов:готова;. Звучало веско. Звучало так, как будто что-то эдакое происходит.",
    O = "Поговорите с Даторианом Раллом в Штормграде.",
    T = "Фолиант благородства",
  },
  [4487] = {
    D = "Ага, хорошо, что ты здесь. Я посылал $gсуккуба:инфернала;, чтобы подогреть твой интерес, но, похоже, ты $Gуспел:успела; оказаться здесь раньше, чем $gона добралась:он добрался; до тебя. Ладно.$B$BТут недавно пошли разговоры о твоем растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень. Короче, я думаю, что ты уже достаточно $Gзарекомендовал:зарекомендовала; себя и потому заслуживаешь... хе-хе... подарочка.$B$BВ Степях над Кабестаном ты найдешь человека по имени Страхад. Уверен, вы уже встречались.",
    O = "Поговорите в Кабестане со Страхадом Фарсаном.",
    T = "Призыв коня Скверны",
