  [453] = {
    D = "Удачи, $n. Надеюсь, ты найдешь этого парня, причем живым.$B$BСбежав за пределы Темнолесья, он мог пасть жертвой диких зверей.",
    O = "Отыщите незнакомца. Его приметы:$B$BОн родом не из Темнолесья.$B$BОн – нервный тип.$B$BОн сбежал из Темнолесья и двинулся на запад.",
    T = "Поиски таинственного незнакомца",
  },
  [454] = {
    D = "До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.$b$bМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.",
