  [4541] = {
    D = "",
    O = "",
    T = "<NYI> <TXT>",
  },
  [4542] = {
    D = "Кентавры стали все чаще нападать на эти земли, и об этом нужно срочно доложить на Заставу Вольного Ветра! Отправляйтесь туда, найдите дозорного утесов Долгорога и отдайте ему это письмо. Форт находится к юго-востоку отсюда.$B$BНо будьте осторожны: неподалеку есть поселение клана Зловещий Тотем, и его члены в последнее время ведут себя беспокойно",
    O = "Отнесите срочное послание дозорному утесов Долгорогу на Заставу Вольного Ветра.",
    T = "Письмо на Заставу Вольного Ветра",
  },
  [455] = {
    D = "Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.$B$BПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.$B$BНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.$B$BМы очень надеемся на тебя, $n. Не подведи нас.",
    O = "Пройдите через Дун Альгаз.$B$BУбейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.$B$BОб исполнении доложите Валстагу Сталезубу из Гавани Менетилов.",
    T = "Альгазская битва",
  },
  [456] = {
    D = "Мои приветствия, $N. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия.$b$bВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.$b$bК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. $GЮный:Юная; |3-6($c), помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.",
    O = "Убейте 4 молодых ночных саблезубов и 4 молодых щетинистых вепрей.",
    T = "Природное равновесие",
