  [47] = {
    D = "Кобольды в этих местах иногда носят с собой золотую пыль. Достань мне этой пыли, и я дам за нее лучшую цену в городе. Да, лучшую цену в городе!$B$BКобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой.",
    O = "Принесите 10 порций золотой пыли в Златоземье Реми Повторюху. Золотую пыль можно добыть у кобольдов в Элвиннском лесу.",
    T = "Золотая пыль",
  },
  [470] = {
    D = "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз все было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась...$b$bЯ бросила в одного из них сумку, но он взял и засосал ее! Мне едва хватило времени, чтобы сбежать.$b$bА в сумке-то мои вещи!$b$bЯ даже не знаю, какой из этих гадов ее сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что $Gсогласился:согласилась; помочь!",
    O = "Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов.",
    T = "Прожорливый слизнюк",
  },
  [4701] = {
    D = "Тебе несомненно приходилось видеть воргов, которыми командуют орки Черной горы.$b$bВот что интересно – сколько мы их ни убиваем, их не делается меньше. Разведчики доносят, что воргов растят и обучают на Пике Черной горы, в столице орков этого клана. Отправляйся туда и поищи источник опасности. Отыщи... и уничтожь.$b$bУдачи, $n. Да хранит тебя Кенарий...",
    O = "Отправьтесь на Пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами.",
    T = "Устранение опасности",
  },
  [471] = {
    D = "Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных.$b$bЛекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!$b$bЕсли у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков.",
    O = "Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов.",
