  [4864] = {
    D = "Изучив содержимое ящика, вы решаете, что Джарону могут пригодиться лежащие там инструменты. Однако среди них нет и следа амулета.$b$bПохоже, дикие совухи обитают к северу и к востоку отсюда, и вы решаете, что ваш следующий шаг – встретить этих существ лицом к лицу и забрать у них амулет.",
    O = "Подберите Припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон.$b$bПринесите Припасы и Ожерелье Синих перьев Джерону Гранильщику в его дом в Зимних Ключах.",
    T = "Разъяренные дикие совухи",
