  [5047] = {
    D = "Разыщи Малифоя Черномолота в Круговзоре, |3-6($c). Скажи ему, что с Вентуроном все в порядке и что костюмчик исправно работает.$B$BИ передай ему вот что...$B$B<Вентурон вручает вам ярко светящийся кусок мяса.>$B$BЯ его вырезал из внутренностей одной зверюги во время своих вынужденных каникул.$B$BГотов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища!$B$BКстати, ты знаешь, где Круговзор? Это в Зимних Ключах.",
    O = "Переговорите с Малифоем Черномолотом в Круговзоре.",
    T = "Айс Вентурон, к вашим услугам!",
  },
  [5048] = {
    D = "Это злобная старушенция и к тому же, весьма вероятно, уже с катушек съехала... Но записи указывают, что старушка Эмма как раз вполне может являться той самой Эммой Фелстоун.$b$bВозможно, вы видели старушку Эмму бредущей по городу – она разговаривает сама с собой, иногда неся совершенно невнятный вздор. Но она никому и ничему не мешает, так что горожане, в большинстве своем, оставили ее в покое.$b$bОбдумав все, я бы сказал, что старушка Эмма и в самом деле – Эмма Фелстоун. Можете сами спросить у нее, не Фелстоун ли ее фамилия.",
    O = "Найдите в Штормграде старушку Эмму и узнайте, действительно ли она – Эмма Фелстоун. Если да, то, может, ей понравится та посылочка, что собрала для нее Джанис Фелстоун.",
    T = "Добросердечная Эмма",
  },
  [5049] = {
    D = "Мне удалось выяснить, что тот, кого ты ищешь, – он же получатель посылки – это Иеремия Пейсон, продавец тараканов в Подгороде.$b$bМне всегда казалось, что для торговли тараканами нужны особые личные качества. Не сомневаюсь, тебя ждут великие дела, |3-6($c). Ступай, меняй мир к лучшему. Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек.",
    O = "Найдите в Подгороде Иеремию Пейсона и выясните, в самом ли деле он Иеремия Фелстоун. Если да, передайте ему посылку от Джанис Фелстоун.",
    T = "Грусть Иеремии",
  },
  [505] = {
    D = "Меня недавно назначили мировым судьей в Южнобережье. Моего предшественника убили, и виновников так и не нашли. Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак.$b$bЛагеря Синдиката расположены на Возвышенности Соферы и на Кинжале Коррана, на севере и на западе от захваченной Ордой Мельницы Таррен. Убей всех союзников Синдиката, которых встретишь в этих лагерях.",
    O = "Убейте 12 преступников и 8 воров Синдиката и возвращайтесь к мировому судье Генри Малебу в Южнобережье.",
    T = "Убийцы из Синдиката",
  },
  [5050] = {
    D = "Кажется, мое мнение насчет тебя было ошибочным и мне следует извиниться. Сестра прислала мне ряд личных вещей, в том числе – ха-ха – документы на ферму Фелстоун. Я пока не стану предъявлять на нее права.$b$bЕсли призрак моей сестры не может упокоиться и привязан к ферме... может быть, ты вернешь ей это? Это половина оберега; вторую носил ее муж.$b$bМожет быть, тогда она обретет покой?",
    O = "Отнесите половинку талисмана Джанис Фелстоун в Западные Чумные земли.",
    T = "Оберег удачи",
  },
  [5051] = {
    D = "Несчастный призрак продолжает причитать:$B$B\"Мне холодно, Джон. Принеси мне свой оберег, и мы снова будем вместе! Скорее, Джон, пока чума не превратила нас в жутких тварей! Я не вижу тебя, Джон... Но знаю, ты рядом. Я чувствую.\"$b$bБыть может, если найти вторую половину оберега и собрать его воедино, душа Джанис Фелстоун обретет покой.",
    O = "Отыщите вторую половину оберега удачи на ферме Фелстоун в Западных Чумных землях и соберите его.$b$bОтдайте оберег удачи Джанис Фелстоун.",
    T = "Вторая половина",
  },
  [5052] = {
    D = "Кровь повлияла не только на шипы *фыркает*, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни. Племя Дыбогривов выкапывает эти осколки и носит с собой как тотемы *фыркает*, и они дают им силы в бою и помогают творить заклинания. *фыркает*$B$BСекреты их магии мне известны.$B$BПринеси Кривозубу один кровавый осколок, и ты все поймешь. Принеси Кривозубу много осколков, и он благословит тебя. Сильна магия иглогривов, ведь это магия самого Агамаггана! *фыркает*",
    O = "Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи.$B$BСоберите побольше кровавых осколков, и он одарит вас силой, дарованной ему Агамагганом.",
    T = "Кровавые осколки Агамаггана",
  },
  [5053] = {
    D = "This quest will send you mail to your mail box. Just hit complete.",
    O = "Test quest to see if mail is sent to your mailbox. Just hit complete, then go check your mail.$B$BHave a nice day.",
    T = "<UNUSED>",
