  [5230] = {
    D = "Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.",
    O = "Принесите полную бутылку с поля Джанис жрице Тени Вандис в Бастион, что в Западных Чумных землях.",
    T = "Возвращение в Бастион",
  },
  [5231] = {
    D = "Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, |3-6($c). Мы должны нанести удар по котлу и получить к нему доступ!$B$BОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз, и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлит свое варево.",
    O = "Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.",
    T = "Цель: Слезы Далсона",
