  [5232] = {
    D = "Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.",
    O = "Отнесите полную бутылку с поля Слез Далсона жрице Тени Вандис в Бастион в Западных Чумных землях.",
    T = "Возвращение в Бастион",
  },
  [5233] = {
    D = "Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!$b$bНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.$b$bДоброй охоты, $n!",
    O = "Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.",
    T = "Цель: Удел Страданий",
  },
  [5234] = {
    D = "Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.",
    O = "Принесите полную бутылку с Призрачной фермы жрице Тени Вандис в Бастион, что в Западных Чумных землях.",
    T = "Возвращение в Бастион",
  },
  [5235] = {
    D = "Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, $n.$B$BПустошь Гаррона находится далеко на востоке от Бастиона, близко к границам Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, |3-6($c).",
    O = "Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с пустоши Гаррона.",
    T = "Цель: пустошь Гаррона",
  },
  [5236] = {
    D = "Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.$b$bЗаполучив яд, пора возвращаться к жрице Тени Вандис в Бастион.",
    O = "Отнесите полную бутылку с пустоши Гаррона жрице Тени Вандис в Бастион в Западных Чумных землях.",
    T = "Возвращение в Бастион",
