  [5238] = {
    D = "",
    O = "",
    T = "Задание выполнено!",
  },
  [524] = {
    D = "За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов. Очевидно, его нашли мертвым в Чумных землях. Дарталия всегда заботится обо мне и решила передать пленников мне в руки.$B$BПора устроить этим фермерам вечеринку. Ох, повеселимся!$B$BПоставь гниющий бочонок на ковер у них в комнате. Чумной напиток для всех!",
    O = "Поставьте гниющий бочонок на ковер для плененных фермеров.",
    T = "Эликсир агонии",
  },
  [5241] = {
    D = "Ты знаешь, иногда по ночам мне слышится плач дядюшки Карлина – как будто бы плач доносится откуда-то издалека, с востока.$B$BА вдруг он плачет обо мне... $n, пожалуйста, разыщи моего дядюшку и скажи ему, что со мной все в порядке.$B$BСкажи, что я здесь, жду его и очень скучаю по сказкам, которые он рассказывал мне на ночь... особенно той, про кроликов и черничное варенье. Она была такая забавная!",
    O = "Найдите Карлина Редпата.",
    T = "Дядюшка Карлин",
  },
  [5242] = {
    D = "Увы, я вижу только один путь покончить с угрозой Оскверненному лесу – прямую атаку. Других путей в Оплот Теней нет, телепортировать тебя внутрь я тоже не могу. Единственный путь – прямой путь в бездну... и я также знаю, кого тебе следует искать в этой бездне. Его зовут Скверн'дан... Владыка теней Скверн'дан. Его власть там, внизу, смертоносна... Он – голова змеи. Убей его и двух его суккубов-прислужниц, и вернись ко мне. Это Скверн'дан заключил союз с Легионом. Его надо остановить!",
    O = "Убейте Моору и Салию и принесите голову Владыки теней Скверн'дана Грете Замшелому Копыту в Оскверненный лес.",
    T = "Окончательный удар",
  },
  [5243] = {
    D = "Я склонен рассматривать свое бытие в форме нежити как род болезни, |3-6($r). Болезни, которая требует лечения. Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение. Действительно, нет лучше орудия против язычников Плети, чем нежить.$B$BКоллеги чтят меня за мои деяния, однако почести ничего не значат для меня.$B$BЕсли ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа.$B$BОтправляйся в Стратхольм и пополни наши запасы святой воды. Искать ее следует в брошенных ящиках с припасами.",
    O = "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Барталомею Чтимому, как только воды будет достаточно.",
    T = "Святая вода",
  },
  [5244] = {
    D = "История Кел'Терила – это история проклятой расы, прикованной к месту, где был совершен неудавшийся ритуал...$b$bВысокорожденные, которых вы найдете там, когда-то похитили священный артефакт, будучи уверенными, что смогут вытянуть его мощь, перелить ее в себя и стать еще более могущественными. Из-за их действий реликвия взорвалась, а куски ее ушли под лед озера...$b$bЕсли хотите узнать больше, поговорите с Джероном Гранильщиком. Он был там недавно и сможет рассказать вам обо всем.",
    O = "Поговорите с Джероном Гранильщиком в деревне Звездопада.",
    T = "Руины Кел'Терила",
  },
  [5245] = {
    D = "[Deprecated] The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.$B$BIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.$B$B",
    O = "[Deprecated] Use Gormir's Pick to find the four Highborne Relic Fragments.",
    T = "Беспокойные духи Кел'Терила",
  },
  [5246] = {
    D = "Я не понимала... Простите мои жестокие слова, |3-6($c).$b$bЯ не хочу вспоминать об ошибках своих предков, но если ваша просьба искренна, я помогу.$b$b*Аврора изучает фрагменты.*$b$bЯ уверена, что это – Кристалл Зин-Малора, артефакт, содержащий в себе могучие силы тайной магии. Возможно, его использовали и во благо, но из-за злых намерений тех, кто его похитил, кристалл раскололся.$b$bОтправляйтесь в Храм Зин-Малор в Азшаре – я могу лишь надеяться, что книга все еще там.",
    O = "Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях.",
    T = "Фрагменты прошлого",
  },
  [5247] = {
    D = "Я смогу помочь вам, если воссоздание артефакта действительно является вашим желанием.$b$bЧтобы воссоединить фрагменты, мне потребуются вещи, обладающие сильными магическими свойствами. Слитки зачарованного тория и пять кристаллов восстановления... Также вам нужно будет набрать воды из... необычного источника... Найдите Зловещий пруд на Пути Элдрета в Забытом Городе, что в Фераласе, и наполните этот фиал.$b$bПока вас не будет, я попытаюсь извлечь из этих страниц знание, как восполнить урон, нанесенный этой реликвии.",
    O = "Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях.",
    T = "Фрагменты прошлого",
  },
  [5248] = {
    D = "$n, Я скорблю о том, что раса эльфов была разрушена, подобно этому кристаллу. Я не знаю, соберутся ли когда-нибудь эти осколки воедино, и все же то, что я могу помочь тебе, уменьшает мою скорбь.$B$BМы не должны забывать о прошлом, $n...$B$BПожалуйста верни кристалл Зин-Малора к озеру Кел'Терил. Найди там духа высокорожденного, который, так же как и я, сожалеет о допущенных ошибках и скажи ему, что мы стремимся все исправить.",
    O = "Отнесите кристалл Зин-Малора к озеру Кел'Терил в Зимних Ключах и найдите духа высокорожденного, который согласится с вами поговорить.",
    T = "Измученный воспоминаниями о прошлом",
  },
  [5249] = {
    D = "В Зимних Ключах, к северу отсюда, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$b$bРабота здесь отнимает все мое время, так что у меня давно уже не было возможности самой добраться до Зимних Ключей. Но вам-то ничто не мешает!$b$bКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в деревне Звездопада и очень много знает о тех местах.",
    O = "Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.",
    T = "В Зимние Ключи!",
  },
  [525] = {
    D = "Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно...$B$BНадо доставить это письмо мировому судье Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать.",
    O = "Доставьте расшифрованное письмо мировому судье Южнобережья Малебу.",
    T = "Все больше тайн",
  },
  [5250] = {
    D = "В Зимних Ключах, к северу от Оскверненного леса, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$b$bЯ так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних ключей. Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин.$b$bКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в Звездопаде и очень много знает о том районе.$b$bСкажите ему, что вы $gмой ученик:моя ученица;.",
    O = "Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.",
    T = "Звездопад",
  },
  [5251] = {
    D = "Впадать в крайности всегда опасно, $n. Взять, к примеру, Алый орден. Неужели такой слепой фанатизм способен привести к чему-то хорошему? Скольких невинных убили они во имя Света.$B$BЭто просто святотатство!$B$BВот что, один из этих негодяев мне особенно интересен – это архивариус Галфорд из Стратхольма. Этот человек отвечает за самые ценные документы ордена. Уничтожь его и сожги его архивы! Если справишься с этим, получишь достойную награду.",
    O = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив.",
    T = "Архивариус",
  },
  [5252] = {
    D = "Кри... кристалл...$b$bЗдешние высокорожденные находятся в плену своего жалкого сущессствования...$b$bЯ полон горрречи, но я понимаю, в чем моя ошибка. И хотя изменить прошлое нееевозможно, теперь я обрел покой, зная, что тебе удалосссь добыть кристалл Зин-Малора...$b$bТы $gдолжен:должна; вернуть крисссталл...$b$bОн должен быть воззвращен.",
    O = "Поговорите с Вундом Ночным Охотником в деревне Звездопада и узнайте у него, куда нужно поместить кристалл Зин-Малора.",
    T = "Раскаявшийся высокорожденный",
  },
  [5253] = {
    D = "Впечатляюще, $n. $B$BКристалл Зин-Малора никогда не вернется в храм, лежащий в руинах. Но я полагаю, что твои усилия уничтожить зло минувших лет не должно пойти прахом.$B$BНайди верховного друида Фэндрала Олений Шлем в Дарнасе, $n, и отдай ему кристалл. Он должен находится в руках тех, кто не злоупотребит его мощью. К тому же только самые сильные маги смогут управиться с артефактом такой мощи.",
