  [5529] = {
    D = "До Серебряного Рассвета дошли слухи о том, что Плеть создает собственную армию драконов! Мы должны этому помешать – с помощью драконов Плеть сможет беспрепятственно перемещаться по всему Азероту!$B$BИх некроманты выращивают проклятых драконов в Некроситете, посреди озера Дарроумир.$B$BОтправляйся в Некроситет и убей как можно больше драконьих детенышей, пока они не успели вырасти и превратиться в неуязвимых монстров!",
    O = "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.",
    T = "Зачумленные детеныши дракона",
  },
  [553] = {
    D = "Вот, возьми Гелькуларов жезл. Он тебе понадобится.$B$BГелькулар создал для своего заклятья 3 церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор.$B$BГелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надежно охраняемом человеческом городе на юге. Мы отомстим!",
    O = "Зарядите жезл Гелькулара силой пламени Азеля, пламени Вераза и пламени Узеля.$B$BВонзите заряженный жезл в гробницу Гелькулара в Южнобережье.",
    T = "Месть Гелькулара",
