  [576] = {
    D = "Стой! Кто идет?$B$BАррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть.$B$BА вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской Бухте как дома.$B$BНе поможешь старому морскому волку вернуть зрение?",
    O = "Диззи Одноглазый из Пиратской Бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса.",
    T = "Смотри в оба",
  },
  [5761] = {
    D = "Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны. Клан Пылающего Клинка – главная, но не единственная угроза. Есть еще и Пламенеющий Клинок, клан, который обосновался в Огненной Пропасти и втайне смущает умы простых представителей Орды.$b$bЧтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный.$b$bУбей его. Я уверен, Вождь будет рад получить его сердце...",
    O = "Спуститесь в Огненную Пропасть, убейте Тарагамана Ненасытного и принесите его сердце Ниру Огненному Клинку в Оргриммаре.",
    T = "Убить тварь",
