  [6029] = {
    D = "Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета в администрации Круговзора. Я должен доложить обстановку офицеру Гарушу в Бастион, расположенный на восточных окраинах Западных Чумных земель, к востоку от Тирисфальских лесов.$B$BЕсли я могу тебя об этом просить... это будет прекрасный повод представить тебя моему начальнику. И, возможно, он найдет тебе дело!",
    O = "Доставьте донесение из Круговзора офицеру Гарушу из ордена Серебряного Рассвета в Бастион в Западных Чумных землях.",
    T = "Донесение из Круговзора",
