  [611] = {
    D = "Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты $gспрашивал:спрашивала;. Посмотри там.$B$BТы $gвернул:вернула; мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!",
    O = "Уничтожьте Алтарь Приливов при помощи меча Кателины, убейте Газбана и принесите Камень Приливов и меч Кателины барону Ревилгазу.",
    T = "Проклятье приливов",
  },
  [612] = {
    D = "It's a long shot, but perhaps you could try to convince Catelyn to part with her dagger? The heart of a collector, you know how it is?$b$bPerhaps if you mention that it's for me, she might be more well-disposed to sell it to me.",
    O = "Return Catelyn's blade.",
    T = "<UNUSED>",
  },
  [6121] = {
    D = "Теперь, $n, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.",
    O = "Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    T = "Новый урок",
  },
  [6122] = {
    D = "Водопад Скалистый на Темных берегах – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающая местную фауну – особенно оленей. Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры. Осторожнее – в пещере у водопада ныне поселилась опасная нага.$B$BКак только наберешь воды, доставь ее Аландариан Песне Ночи в Аубердин. Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой.",
    O = "Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый. $B$BДоставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темные берега.",
    T = "Основной источник",
  },
  [6123] = {
    D = "Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится земляной корень. Травники знают, где его искать, так что, если нам не повезло и ты не $gтравник:травница;, придется найти кого-то, кто сможет помочь.$B$BДля усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будь $gосторожен:осторожна;.",
    O = "Принесите 5 земляных корней и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.",
    T = "Сбор лекарственных ингредиентов",
  },
  [6124] = {
    D = "Мази, изготовленной из реагентов, которые ты $gпринес:принесла; мне, $n, хватит на десять доз. Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотела бы, чтобы ты $gпомог:помогла; нам начать исцеление. По всем Темным берегам встречаются больные олени. Используй мазь для исцеления их недуга.$B$BЯ уверена, что Дендрит Блеск Звезд из Лунной поляны захочет поговорить с тобой, когда работа будет закончена. Пожалуйста, передай благодарность жителей Аубердина Кругу Кенария... и позволь мне лично поблагодарить тебя за помощь!",
    O = "Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темных берегах, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темных берегов, где начинается Ясеневый лес.",
    T = "Исцеление больных",
