  [6384] = {
    D = "Всего лишь за несколько монет ветрокрыл отнесет тебя в Оргриммар. Оказавшись там, отнеси мясные продукты Гримтака Гришке. Ее постоялый двор располагается на Аллее Силы.$B$BПоговори со мной, когда решишь отправиться в путь.",
    O = "Оплатите полет в Оргриммар укротителю ветрокрылов Буроку и, оказавшись в Оргриммаре, отнесите мясные продукты Гримтака Гришке.",
    T = "Дорога до Оргриммара",
  },
  [6385] = {
    D = "Я написала Гримтаку письмо благодарности. Поможешь с доставкой? Если ты уже $gбыл:была; на Колючем Холме и $gзнаком:знакома; с местным укротителем ветрокрылов, то можешь полететь туда.$B$BИди с моим письмом к Дорасу, оргриммарскому укротителю ветрокрылов, и поговори с ним насчет полета до Колючего Холма.",
    O = "Отнесите письмо Гришки Дорасу из Оргриммара.",
    T = "Укротитель ветрокрылов Дорас",
  },
  [6386] = {
    D = "Мои виверны могут отвезти тебя в самые разные края – при условии, что ты $gсам:сама; там уже $gбыл:была; и $gговорил:говорила; с местным укротителем ветрокрылов.$B$BТебе уже доводилось бывать на Колючем Холме, да и Бурока ты знаешь, так что лети прямо к нему. Оказавшись в Колючем Холме, ты сможешь передать Гримтаку письмо Гришки.$B$BКак будешь $gготов:готова;, скажи.",
    O = "Оплатите перелет в Колючий Холм укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Гримтаку из Колючего Холма.",
    T = "Возвращение на Колючий Холм",
  },
  [6387] = {
    D = "Ко мне приходит немало молодых дворфов, мечтающих научиться кулинарии. А что нужнее всего повару? Мясницкий нож!$B$BЯ составил список учеников, которые хорошо проявили себя на занятиях и заслужили почетный мясницкий нож. Отнеси этот список Голниру Твердопалу в Стальгорн. Он подготовит для меня эти ножи.$B$BПроще всего добраться до Стальгорна на грифоне, поэтому ступай вместе со списком к нашему укротителю грифонов, Бролану Ветробороду, и поговори с ним насчет полета в Стальгорн.",
    O = "Отнесите список Гремлока Бролану Ветробороду в Каранос.",
    T = "Награды ученикам",
  },
  [6388] = {
    D = "Вот почетные мясницкие ножи для учеников Гремлока. Если ты уже $Gбывал:бывала; в Караносе, то можешь полететь обратно на грифоне!$B$BОтнеси ножи нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчет полета в Каранос.",
    O = "Отнесите почетные мясницкие ножи Гриту Турдену в Стальгорне.",
    T = "Грит Турден",
