  [6389] = {
    D = "Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.$B$BПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.",
    O = "Выпустите термитов Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.",
    T = "Чума на вашу лесопилку!",
  },
  [639] = {
    D = "В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой. Он бросался в бой с мечом Трол'каларом в руке – \"убийцей троллей\", на их древнем наречии.$B$BНо теперь сыновья Троллебоя ослабели, а цитадель их разрушена.$B$BМеч защищен несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать.$B$BПервую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде.",
