  [6543] = {
    D = "Недавно я отправил в Ясеневый лес нескольких разведчиков. Мне нужен гонец, чтобы доставить им приказы и вернуться с отчетом об их наблюдениях.$B$BПервый твой пункт – застава Зорам'гар, что на западном побережье на Зорамском взморье. Там ты найдешь первого гонца. Так же тебе придется заглянуть на Заставу Расщепленного Дерева, что на севере и к востоку по дороге близ Азшары. Там найдешь разведчика и сопровождающего.$B$BПередай каждому указания и забери у них новые донесения.",
    O = "Распакуйте связку донесений. Доставьте отчеты Песни Войны разведчику, гонцу и всаднику клана Песни Войны. Возьмите у них новые донесения для Кадрака и доставьте ему в северную сторожевую башню в Степях.",
    T = "Отчет Песни Войны",
