  [6548] = {
    D = "Клан Зловещего Тотема напал на мою деревню и убил почти всех жителей. Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь.$b$b$n, все, чего я желаю – это чтобы как можно больше этих негодяев умерло. Ты найдешь их к западу отсюда.",
    O = "Убейте 8 бузотеров и 6 наемников из племени Зловещего Тотема, затем вернитесь к Макабе Плоскому Копыту, ожидающему вас на юго-восточной границе Когтистых гор.",
    T = "Отомсти за мою деревню",
  },
  [655] = {
    D = "Воспоминания по-прежнему ярки, как будто все было вчера... Так много лет без надежды, прикованный к этой проклятой дыре деревом и сталью. И вот наконец появился вождь: Молот Рока блещет полуночными доспехами, высоко вздымает боевой молот...$B$BКак же это подло, как непереносимо, что удар труса мог сразить нашего величайшего героя. Враг наскочил сзади и пронзил его копьем... Я упал на колени. Какая могла быть надежда? Какая еще может быть надежда...",
    O = "Поговорите с Тор'ганом в Павшем Молоте.",
    T = "Павший Молот",
  },
  [656] = {
    D = "Вы должны нанести поражение Мизраэль прежде, чем она обретет полную силу. Если вы этого не сделаете, то, как только она наберет достаточно сил, она кинется на своих пленителей! Есть такие, кто считает, что может ее контролировать, но если ее можно контролировать, с чего было великанам с самого начала заковывать ее в цепи?$B$BПотрясающая логика, да?$B$BЧтобы сразить Мизраэль, призовите ее у ее кристаллов, где вы в первый раз говорили с ней. Нанесите ей поражение и заберите ее мистические оковы, а потом подсоедините их к кристаллам Мизраэль.$B$BСделайте так – и она вновь будет поймана в ловушку.",
    O = "Отправляйтесь к кристаллам Мизраэль, вызовите принцессу и победите ее.$B$BЗаберите ее мистические оковы и присоедините их к кристаллам.",
    T = "Призыв принцессы",
  },
  [6561] = {
    D = "Силы оставили меня. Мне необходима твоя помощь!$B$BВ давние времена на этом месте был храм Элуны. К несчастью, он был разрушен, когда порча древнего бога просочилась из-под земли и осквернила священный лунный колодец.$b$bАку'май, слуга древнего бога, поднялся из глубин.$b$bСлужители культа Сумеречного Молота объединились с нагами в борьбе за эти земли. Ведомые Келрисом, они приносят Аку'май невинные жертвы.$b$bУбей Келриса и принеси его голову Башане в Громовой Утес, $n.",
    O = "Принесите голову Повелителя сумрака Келриса Башане Рунический Тотем в Громовой Утес.",
    T = "Злодейство в Непроглядной Пучине",
  },
  [6562] = {
    D = "Дже'неу Санкри нужна помощь. Он ждет в Непроглядной Пучине, что в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор. Ты можешь добраться до него через Утес Ветрорезов или идя на север через Степи. Зорамское взморье лежит далеко на западе от леса. Будь $Gосторожен:осторожна;, $n. Там обитают такие силы, от которых теплого приема не жди.",
    O = "Поговорите с Дже'неу Санкри в Ясеневом лесу.",
    T = "Угроза из Глубин",
