  [668] = {
    D = "Не будем заставлять капитана О'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$b$bА через несколько недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища.$b$bВот, $n, отнесите все О'Брину.",
    O = "Отнесите эльфийские самоцветы капитану О'Брину в бухту Фальдира, что на Нагорье Арати.",
    T = "Затонувшее сокровище",
  },
  [6681] = {
    D = "$n,$B$BЧерный Ворон очень заинтересовался тобой, $gюный вор:юная воришка;. Мы наблюдали. Тебе не хватает ловкости, но это преходяще.$b$bЕсли ты хочешь стать $gучеником:ученицей; мастера Черного Ворона и членом Лиги убийц, стоит только принести печать Черного Ворона (приложенную к этому письму) в поместье Черный Ворон.$b$bПервым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость.$b$bС уважением,$b$bФарад.",
    O = "Отнесите печать Черного Ворона Фараду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.$b$bНе теряйте бдительности. Поиски поместья – проверка на ловкость.",
