  [6804] = {
    D = "Мы отправили отряд элементалей воды на разведку в восточные пределы Лордерона, пораженные чумой нежити. Теперь наши разведчики поражены скверной. Повелители Вод не могут допустить, чтобы проклятая чума угрожала нашему народу!$B$BВозьми этот фиал. В нем заключен один из аспектов Нептулона. Он исцелит пораженных скверной элементалей, уничтожив проникшую в их тела заразу. Однако этот процесс столь болезнен, что некоторые из них могут стать нестабильными.$B$BТебе придется убить колыхающихся волноплесков. Принеси мне их браслеты.",
    O = "Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару.",
    T = "Отравленная вода",
  },
  [6805] = {
    D = "Мы, элементали воды, противостоим существам низших стихий. Если и в самом деле хочешь быть $gнашим союзником:нашей союзницей;, докажи это!$B$BДалеко на юге, в пустынных землях Силитуса, в скалистом уголке, именуемом долиной Кристаллов, кишат слуги воздуха и земли. Они защищают сокрытые там предметы силы от примитивных существ, смертных. Мне нет никакого дела до того, что они там стерегут, я хочу, чтобы ты $gперебил:перебила; их.$B$BОтправляйся в Долину Кристаллов в Силитус и уничтожь наших врагов.",
    O = "Убейте 15 вихрей пыли и 15 пустынных грохотунов и возвращайтесь к герцогу Гидраксису в Азшару.",
    T = "Буря в пустыне",
  },
  [681] = {
    D = "Мы ведем войну со Стромгардом и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьется с другой, и конца этому не видно.$b$bНо наши силы иссякают, в то время как силы наших врагов – растут.$b$bНам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами.$B$BПойдите на базу Синдиката в Северном поместье и убейте их. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще.",
    O = "Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката.$B$BЗатем вернитесь к капитану Ниалс в Опорном пункте.",
    T = "Северное поместье",
  },
  [682] = {
    D = "Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки.",
    O = "Принесите 7 знаков Стромгарда Капитану Ниалс в Опорный пункт.",
    T = "Знаки Стромгарда",
  },
  [6821] = {
    D = "Ты $gдоказал:доказала; мне, что $gспособен:способна; доблестно противостоять врагам и верно служить Повелителям Вод. Однако пока тебе приходилось выходить на бой с довольно слабыми противниками. Сможешь ди ты сразить более могущественного врага.$B$BСлушай мое повеление.$B$BНа вершине Пика Черной горы орки изловили слугу огня, Пиростража Углевзора. Найди место, где они его держат, и перебей и стражу и пленника. Принеси мне его глаз – докажи свою преданность.",
    O = "Принесите око Углевзора герцогу Гидраксису в Азшару.",
    T = "Око Углевзора",
  },
  [6822] = {
    D = "Пришло время испытать твои силы всерьез, $n. Ты $gготов:готова;?$B$BНа самом дне Глубин Черной горы скрывается путь к Огненным Недрам. Это оплот нашего врага, охраняемый самыми мощными служителями огня в нашем мире.$B$BОтправляйся в Огненные Недра, $n. Докажи мне, что у тебя хватит сил справиться с тем, что скрывается там.$B$BЕсли у тебя есть союзники, бери их с собой. Не стоит отправляться в Огненные Недра в одиночку.",
    O = "Убейте 1 Повелителя огня, 1 лавового великана, 1 древнюю гончую Недр и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару.",
    T = "Огненные Недра",
  },
  [6823] = {
    D = "Если в самом деле хочешь быть $gнашим союзником:нашей союзницей;, докажи серьезность своих намерений в боях против наших врагов – слуг воздуха, земли и огня. Каждое нанесенное им поражение подорвет их позиции в этих землях и послужит доказательством твоей приверженности благу нашего народа.",
    O = "Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару.",
    T = "Агент Гидраксиса",
  },
  [6824] = {
    D = "$n, твоя помощь для нас неоценима, и мы с неохотой отправляем тебя на последнее задание – мы не хотим терять столь полезного союзника, однако работа есть работа.$B$BИмей в виду, если ты успешно выполнишь поставленную перед тобой задачу, это весьма существенно приблизит час нашей победы.$B$BМы хотим, чтобы ты $gуничтожил:уничтожила; нескольких капитанов в Огненных Недрах: Люцифрона, Сульфурона, Гееннаса и Шаззраха. Убей их и принеси их отрубленные руки.$B$BЭто потребует от тебя всех сил, но если ты преуспеешь, Повелителям Огня будет нанесен ужасный удар.",
