  [7124] = {
    D = "Битва, разгоревшаяся на землях Альтеракской долины, идет и за рудники – Железный и Ледяного Зуба. Они богаты сырьем, и к тому же их можно использовать для хранения припасов.$B$BПомоги нам, $n! Захвати один из этих рудников, во имя Орды! Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный. Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану.",
    O = "Захватите рудник и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.",
    T = "Захват рудника",
  },
  [713] = {
    D = "Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева. $B$BЕго охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных. И это еще не все: оно позволяет сохранять чары на магических предметах. $B$BМне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте.$B$BБрокин, мой друг-гоблин, научит тебя, как изготовить масло. Ты найдешь его в Альтераке.",
    O = "Найдите масло льда и принесите его Лотвилю Вериатусу в Бесплодные земли.",
    T = "Охлаждение горячих голов",
  },
  [714] = {
    D = "$n, ты $gсправился:справилась; со своей работой выше всяких похвал.$B$B*Мысли Лотвила явно витают где-то в его экспериментах.*$B$BБудешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростертыми...$B$BОп-ля! Лови-лови, скорей! Да, спасибо.$B$BА сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом.$B$BЕсли сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент.",
    O = "Принесите гирохронатом Лотвилю Вериатусу в Бесплодные земли.",
    T = "Гиро...чего?",
  },
  [7141] = {
    D = "Лига исследователей уверена, что в Альтеракской долине есть артефакты, но клан Северного Волка не позволяет нам проводить здесь исследования. Не дадим Орде задушить наши благородные научные начинания! Уничтожь генерала Северного Волка, Дрек'Тара. Без него орки ничего сделать не смогут.$B$BДрек'Тара можно найти в крепости Северного Волка, на юге Альтеракской долины. Убей его и возвращайся.",
    O = "Отправляйтесь в Альтеракскую долину, сразитесь с генералом Орды Дрек'Таром и возвращайтесь к геологу Камнетерке в Альтеракские горы.",
    T = "Битва за Альтерак",
  },
  [7142] = {
    D = "Дворфы Грозовой Вершины вместе со своими союзниками вторглись в Альтеракскую долину, и мы должны выкинуть их отсюда! Если мы хотим выиграть битву за Альтерак наверняка, то нам нужно уничтожить их генерала, Вандара Грозовую Вершину!$B$BЕго можно найти в Дун Болдаре, на севере Альтеракской долины.$B$BУбей его, $n, и возвращайся обратно ко мне.",
    O = "Отправляйтесь в Альтеракскую долину и убейте генерала дворфов, Вандара Грозовую Вершину. После этого возвращайтесь к Вогге Смертобою в Альтеракские горы.",
    T = "Битва за Альтерак",
  },
  [715] = {
    D = "Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждет впереди. С другой стороны, ты $gдоказал:доказала; свою приверженность наукам, которые так чтит Лотвил. Не поможешь ли ты, в таком случае, и мне? $B$BМне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе. $B$BВзамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях.",
    O = "Принесите зелье простой невидимости и лечебное зелье Люсьену Подай-Ключ в Бесплодные земли.",
    T = "Жидкий камень",
  },
  [716] = {
    D = "Я знаю, каким скупым бывает Лотвил, $n, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... $B$BЯ собрал все неиспользованные камни, которые ты $gпринес:принесла;, и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. $B$BНо мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу.",
    O = "Принесите украшенные узором бронзовые наручи Люсьену Подай-Ключ в Бесплодные земли.",
    T = "Камень – лучшая одежка!",
  },
  [7161] = {
    D = "Приветствую, |3-6($c). Много времени прошло с тех пор, когда мы в последний раз внимали зову битвы. Трудно пробудить давно забытые чувства, но если они проснулись, обязательно прольется кровь. Ярость боя зовет нас...$B$BВ Альтеракской долине все новички должны пройти боевое крещение.$B$BГлубоко в пещерах гноллов из стаи Дикой Лапы хранится знамя клана Северного Волка. Отправляйся туда и добудь его. Возвращайся ко мне со знаменем, и получишь знак отличия новобранца.",
    O = "Отправляйтесь в пещеру Дикой Лапы, расположенную на юго-востоке от основной базы в Альтеракской долине, и добудьте знамя Северного Волка. Отнесите знамя Северного Волка воеводе Лаггронду.",
    T = "Арена испытаний",
  },
  [7162] = {
    D = "Ты $gприбыл:прибыла; вовремя, |3-6($c). Эти дикари из клана Северного Волка ни в какую не желают сдаваться! Ничего, мы им покажем, на что способна Грозовая Вершина. Они склонятся перед нашей мощью!$B$BПеред тем, как отправиться в бой, ты $gдолжен:должна; вступить в ряды Грозовой Вершины.$B$BК юго-западу от Дун Болдара находится пещера Ледяного Крыла. В ее недрах хранится знамя Грозовой Вершины. Отправляйся туда и добудь его. Принеси знамя мне, и получишь отличительный знак новобранца.",
    O = "Отправляйтесь в пещеру Ледяного Крыла, которая расположена в Альтеракской долине, на юго-западе от Дун Болдара, и добудьте знамя Грозовой Вершины. Отдайте знамя лейтенанту Хаггердину в Альтеракских горах.",
    T = "Арена испытаний",
