  [7401] = {
    D = "Согласно приказу сержанта Язры Кровавый Рык, все дворфы на поле сражения подлежат неукоснительному уничтожению.$B$BПосле боя из каждого убитого дворфа следует выдрать хребет, а тело оставить вонять и разлагаться, – в назидание всем, кто осмелится замахнуться на Орду.$B$BВыдранные хребты, как доказательство своих подвигов, сдавайте Язре Кровавый Рык.",
    O = "Ваша задача – убивать дворфов в Альтеракской долине.$B$BУбейте дворфа и вырвите ему хребет. Отнесите хребет дворфа сержанту Язре Кровавый Рык в крепость Северного Волка.",
    T = "Разыскиваются: ДВОРФЫ!",
  },
  [7402] = {
    D = "Согласно приказу капрала Норга Грозовой Вершины, все солдаты Грозовой Вершины должны убить как можно больше орков.$B$BВ качестве трофея предъявляйте орочьи зубы.$B$BПеред тем, как вырывать оркам зубы, не забывайте надевать защитные перчатки!",
    O = "Ваше задание – убивать орков в Альтеракской долине.$B$BУбейте орка и доставьте зуб орка капралу Норгу Грозовой Вершине в Дун Болдар.",
    T = "Разыскиваются: ОРКИ!",
  },
  [741] = {
    D = "Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнас? Мне не хотелось бы уезжать с Темных берегов без него.$b$bВот, $n, отвези эту таинственную окаменелость главному археологу Седоусу в Дарнас.",
    O = "Отвезите таинственную окаменелость главному археологу Седоусу в Дарнас.",
    T = "Рассеянный геолог",
  },
  [742] = {
    D = "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$b$bОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – Застава Расщепленного Дерева и Застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на Заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!",
    O = "Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.",
