  [7429] = {
    D = "",
    O = "",
    T = "Освободите Нотта!",
  },
  [743] = {
    D = "Спасибо, что $gвыбрал:выбрала; время поговорить со мной, $n. Я Руул, воин и учитель.$B$BПришло время пройти испытания и покинуть Мулгор.$B$BЕсли ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги.$B$BЭти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.",
    O = "Принесите 8 когтей гарпий из стаи Неистовства Ветра Руулу Орлиному Когтю в деревню Кровавого Копыта.",
    T = "Соседство со стаей Неистовства Ветра",
  },
  [744] = {
    D = "$n, вскоре мой брат предстанет перед вождем Кровавым Копытом, и мне выпала большая честь сделать для него головной убор.$B$BМне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?$B$BПерья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утеса. Мне нужно всего-то 6 лазурных и 6 бронзовых перьев, чтобы закончить работу.",
    O = "Добудьте 6 лазурных перьев и 6 бронзовых перьев.",
    T = "Подготовка к церемонии",
  },
  [7441] = {
    D = "Представь себе, $gчужестранец:чужестранка;: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника... – и меня тут же обворовали! Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре'Таласа!$b$bКлюч мне теперь ни к чему: я обменял свое бессмертие на свободу, – но книга мне нужна позарез!$b$bОтыщи мне этого беса Пузиллина, и добудь у него книгу!$b$bИщи его в Квартале Криводревов Забытого Города.",
    O = "Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.$b$bЕсли добудете книгу, вернитесь к Азж'Тордину в павильон Лорисс в Фераласе.",
    T = "Пузиллин и старейшина Азж'Тордин",
  },
  [745] = {
    D = "$n, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.",
    O = "Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Бледногривов и возвращайтесь к Бейну Кровавому Копыту в деревню Кровавого Копыта.",
    T = "Недобрые соседи",
  },
  [746] = {
    D = "К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у нее надо учиться, а не осквернять бесконечными ямами.$B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.",
    O = "Соберите 5 кирок геолога.$B$BСломайте их в кузнице. $B$BОтнесите 5 сломанных инструментов Бейну Кровавому Копыту в деревню Кровавого Копыта.",
    T = "Дворфийские делишки",
  },
  [7461] = {
    D = "Ну что, довольно ли ты $gслышал:слышала;? Надеюсь, ты не устрашишься вступить в бой?$b$bЭтому безумию необходимо положить конец! Время бессмертных давным-давно миновало. Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле. А потом убей Бессмер'тера. Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже. Помоги духам этого города упокоиться в мире!",
    O = "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.$b$bВойдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.$b$bЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар.",
    T = "Древнее безумие",
  },
  [7462] = {
    D = "В библиотеке, Читальне, ты найдешь древний сундук, спрятанный под лестницей. Можешь взять оттуда, что тебе понравится.",
    O = "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!",
    T = "Сокровище Шен'дралар",
  },
  [7463] = {
    D = "А-а, |3-6($r), $gпосвятивший:посвятившая:r;себя магии! Удивительно. Я не видывал подобных тебе уже... сколько? Которое у нас тысячелетье на дворе? Да уже лет пятьсот!$b$bУ меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придется выполнить одно мое поручение.$b$b*Лидрос хихикает.*$b$bВ Эльдре'Таласе завелась аномалия. В восточном крыле поселился элементаль воды. Надо его... того... занести в каталог.$b$bСтупай в Квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари. Принеси ее мне, а я тебя научу одной полезной штучке!",
    O = "Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.",
    T = "Магический напиток",
  },
  [747] = {
    D = "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утес. Но прежде чем это случится, тебе придется доказать моему отцу, вождю Соколиному Ветру, что ты $Gдостоин:достойна; этой чести. $b$bНа плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты $gспособен:способна;, – поохоться на равнинных долгоногов и принеси мяса в деревню.",
    O = "Принесите 7 перьев равнинных долгоногов и 7 кусков мяса равнинных долгоногов Груллу Соколиному Ветру в Лагерь Нараче.",
    T = "Охота начинается",
  },
  [748] = {
    D = "Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо.$B$BДля очищения колодцев придется создать тотемы, а ты пойдешь с ними к колодцам и проведешь очищающие ритуалы.$B$BНачнем мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы волков прерий и когти взрослых долгоногов. И тех, и других ты найдешь на юго-западе.",
    O = "Принесите 6 лап волков прерий и 4 когтя равнинного долгонога Муллу Громовому Рогу в деревню Кровавого Копыта.",
    T = "Отравленная вода",
  },
  [7481] = {
    D = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!",
    O = "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.",
    T = "Эльфийские легенды",
  },
  [7482] = {
    D = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master led us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!",
    O = "Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к книжнице Рунический Шип и сообщите ей все, что вам удалось узнать.",
    T = "Эльфийские легенды",
  },
  [7483] = {
    D = "Мастер Винтхалус потерял \"Манускрипт Скорости\" в восточном крыле. Этот манускрипт позволит тебе наложить на все свое снаряжение небольшое ускоряющее заклятие. Детские игрушки, на самом деле...$b$bТем не менее, если тебя это все же интересует, принеси мне манускрипт, и кое-какие необходимые реагенты.$b$bХм... Насколько я помню, там требуется кровь героев, безупречный черный алмаз и большие сверкающие осколки. Впрочем, я могу и ошибиться!$b$b*Лидрос пожимает плечами.*",
    O = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Скорости\", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 2 образца крови героев, чтобы получить магический знак стремительности.",
    T = "Манускрипт скорости",
  },
  [7484] = {
    D = "Этот манускрипт едва не вызвал интерес у одного из юных фамилиаров хранителя мудрости! Бедняжка, ему было всего несколько недель от роду!$b$bТем из вас, кто интересуется магией, этот манускрипт может пригодиться!$b$bОн пропал где-то в этом крыле. Могу только предположить, что его прибрал к рукам один из духов высокорожденных.$b$bПринесите мне \"Манускрипт Средоточия\", несколько больших сверкающих осколков, шкуру тени и безупречный черный алмаз, и я создам для вас магический знак.",
    O = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Средоточия\", 1 безупречный черный алмаз, 4 больших сверкающих осколка и 2 образца шкуры тени, чтобы получить магический знак сосредоточения.",
    T = "Манускрипт средоточия",
  },
  [7485] = {
    D = "Потеряв этот манускрипт, он рыдал, как ребенок! Не пойми меня неправильно – мне и самому случалось плакать из-за книг, ведь нет большей утраты, чем утраченные знания, – но рыдать из-за этих почти бесполезных обрывков заклинаний? Абсурд! Мне даже подумалось, что принц, пожалуй, оказал ему услугу, отделив его плоть от костей.$b$bПринеси мне этот манускрипт вместе с безупречным черным алмазом, большими сверкающими осколками и истлевшей шовной нитью поганища, и я воссоздам этот магический знак!$b$bАх, да: в общем, ищи в северном крыле.",
    O = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Защиты\", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 1 истлевшую шовную нить поганища, чтобы получить магический знак защиты.",
    T = "Манускрипт защиты",
  },
  [7486] = {
    D = "$n, твои заслуги перед Повелителями Вод превосходят самые смелые ожидания. Мы не могли предположить, что обитатель этого мира может обладать подобной силой!$B$BНе знаю, как у твоего народа принято выражать благодарность, однако могу пообещать тебе щедрую награду.$B$BОтправляйся в южную часть острова и найди сундук, сокрытый в волнах. В том сундуке твоя награда.$B$BИди, $n. Забери свою награду.",
    O = "Заберите свою награду из сундука Гидраксиса.",
    T = "Награда для героя",
  },
  [7487] = {
    D = "Земля испещрена трещинами и разломами – прямо у нас под ногами, |3-6($r). В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя Огня.$B$B$gУдивлен:Удивлена;? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.",
    O = "Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.",
    T = "Сродство с недрами",
  },
  [7488] = {
    D = "Маг Лефтендрис, злокозненная эльфийка крови, чья жестокость уступает лишь ее извращенной приверженности к магии, бежала в Забытый Город! Она создала магическое устройство: сеть, улавливающую энергию этого места, – и мы опасаемся, что, если Летендрис не остановить, она нанесет непоправимый урон нашему миру!$b$bОстанови ее, $n. Отыщи ее и отними у нее эту сеть. Она, скорее всего, где-то неподалеку от сатиров в Квартале Криводревов Забытого Города. Принеси эту сеть мне, чтобы мы могли осторожно выпустить захваченную ею энергию на свободу...",
    O = "Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.",
    T = "Сеть Лефтендрис",
  },
  [7489] = {
    D = "Эльфийка крови Лефтендрис перешла все мыслимые границы! Она так жаждала все новой магической энергии, что бросила вызов своим собратьям и создала хитроумное устройство, сеть, предназначенную для того, чтобы всасывать отравленную магию Забытого Города. Она и теперь собирает эту энергию, намереваясь использовать ее против своих врагов!$b$bЛефтендрис необходимо остановить. Отыщи ее в Квартале Криводревов в Забытом Городе, повергни ее и принеси ее сеть мне, чтобы мы могли передать ее для изучения более здравомыслящим эльфам крови.",
    O = "Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.",
    T = "Сеть Лефтендрис",
