  },
  [758] = {
    D = "Тотем готов, $n. Остается лишь провести ритуал очищения.$B$BСтупай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью Тотема очищения колодца Громового Рога. После этого возвращайся ко мне.$B$BИ да пребудут с тобой духи.",
    O = "Очистите колодец Громового Рога на севере от деревни с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.",
    T = "Очищение колодца Громового Рога",
  },
  [7581] = {
    D = "Ты $Gдолжен:должна; добыть у младших демонов кандалы для стража ужаса.$B$BКровь сатира из племени Буйного Нрава, что живут в Забытом Городе, для этого сгодится. Свернувшаяся кровь скрепит осколки Хедерины и даст силу кристаллической тюрьме.",
    O = "Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.",
    T = "Тюремные кандалы",
  },
  [7582] = {
    D = "Демоны Хедерины, что живут у подножия горы Хиджал, выделяют яды Скверны, которые вызревают и твердеют, образуя антимагические кристаллы. Они известны как слезы Хедерины.$B$BДаже чудовищная сила стража ужаса не сможет разбить стены тюрьмы, сделанной из этого материала.$B$BОтправляйся в Теснину Зловещего Шепота в Зимних ключах и добудь этих слез.",
    O = "Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.",
    T = "Тюремная камера",
  },
  [7583] = {
    D = "Темница готова. Теперь самое трудное дело.$B$BТы $Gдолжен:должна; найти и схватить командира стражей ужаса в Гниющем Шраме при помощи этой кристаллической тюрьмы.$B$BОсторожнее! Страж ужаса -коварный и смертельный враг, он будет пытаться уничтожить тебя, как только ты начнешь обряд заточения. Он будет отчаянно отбиваться, пытаясь избежать плена.$B$BОн будет смотреть только на тебя, $n. Потому я рекомендую взять с собой друзей, которые не дадут ему погубить тебя!",
    O = "Отправляйтесь в Гниющий Шрам и найдите командира стражей ужаса.$B$BПри помощи светящейся кристаллической тюрьмы поймайте командира стражей ужаса. Будьте готовы к отчаянным атакам и сопротивлению, поскольку демон будет пытаться избежать заточения.$B$BЕсли вы добьетесь успеха, отнесите пленного стража ужаса Дайо в Гниющий Шрам.",
    T = "Заточение",
