  [7633] = {
    D = "",
    O = "",
    T = "Посвящение",
  },
  [7634] = {
    D = "Приветствую тебя, |3-6($c). Я Хастат, древо мудрости. Я храню память тысячелетий.$B$BЕсли один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже 10 000 лет. Если к этому колчану в пару получить еще и лук Древ, то силе их равных не будет.$B$BПринеси мне жил взрослого синего дракона, и получишь колчан.",
    O = "Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.",
    T = "Перетянутый жилами лист древня",
  },
  [7635] = {
    D = "Вартус, конечно, предложил тебе посох для лука Дерев, но наложить чары на тетиву, без которой лук – не лук, могу только я.$B$BЭто простое дело, совсем плевое. Убей взрослого черного дракона и добудь из него жилу. Принеси мне эту жилу, и я зачарую ее так, что тетива для лука из нее будет, считай, вечной.",
    O = "Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.",
    T = "Подходящая тетива",
  },
  [7636] = {
    D = "Тайные слуги Пылающего Легиона все еще строят козни в нашем мире, |3-6($c). Они оскверняют все, к чему прикасаются. Природа чахнет и стенает от их присутствия.$B$BТы $gдолжен:должна; выследить этих демонических разносчиков порчи, $n. Помни – ты $gдолжен:должна; лично разобраться с ними – иначе сбегут. Пока ты $gодин:одна;, они будут пытаться уничтожить тебя. Ты $gдолжен:должна; сразить их, обратить их надменность в ничтожество!$B$BЯ дам тебе кусок моей коры. Письмена на ней приведут тебя к нашим врагам. Принеси мне их головы.",
    O = "Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи:$B$BСимон Совратительницу.$B$BКлинфрана Безумного.$B$BСоленора Убийцу.$B$BАрториуса Судьбоносного.$B$BУничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами.$B$BВ поисках местонахождения этих демонов сверяйтесь с окаменевшей корой.$B$BВы ОБЯЗАНЫ выполнить это задание в одиночку.",
    T = "Ветвь ходячего Древа",
  },
  [7637] = {
    D = "Чтобы подготовиться к этому заданию, ты $Gдолжен:должна; сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать.$b$bДля выполнения задания ты $Gдолжен:должна; получить курильницу экзорцизма у Верховного жреца Рохана. Несмотря на то, что ее использование будет продиктовано благими намерениями и существенными причинами, за нее должна быть предложена соответственная компенсация.$b$bОтправляйся в Стальгорн и поговори с Верховным жрецом. Если возьмешь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам.$b$bА теперь иди, $n, время терять нельзя.",
    O = "Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет.",
    T = "Жертва необходима",
  },
  [7638] = {
    D = "Пришло твое время, $n, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня.$b$bПоговори с лордом Грейсоном Тенеломом здесь, в Соборном квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня.$b$bЯ желаю тебе всего наилучшего в этом испытании. Во имя Света, $gмой благородный брат:моя благородная сестра;!",
    O = "Поговорите с лордом Грейсоном Тенеломом в Соборном квартале Штормграда.",
    T = "Лорд Грейсон Тенелом",
  },
  [7639] = {
    D = "Прими эту курильницу и будь $Gблагословен:благословенна;. Я сам применял ее в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях.$B$BНыне возвращайся к лорду Грейсону Тенелому в Штормград, $n. Он даст тебе поручение.",
