  },
  [768] = {
    D = "Привет тебе, $Gюноша:девица;. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесешь ты честь своему клану!$B$BЯ работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утеса.$B$BЕсли принесешь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.",
    O = "Принесите 12 кусков тонкой кожи Верену Долгоногу в Громовой Утес.",
    T = "Добывание шкур",
  },
  [7681] = {
    D = "Покормите питомца.",
    O = "Покормите питомца и поговорите с персонажем, давшим вам задание.",
    T = "Тестовое задание охотника",
  },
  [7682] = {
    D = "Покормите питомца.",
    O = "Покормите питомца и поговорите с персонажем, давшим вам задание.",
    T = "Тестовое задание охотника 2",
  },
  [769] = {
    D = "Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы.$B$BИ тогда я поделюсь с тобой своими знаниями.",
    O = "Принесите 4 куска легкой кожи и 4 мотка грубой нити Верену Высокому Страннику в Громовой Утес.",
    T = "Сумка из шкуры кодо",
  },
  [77] = {
    D = "Я понял, про какую тару говорил Дран Дрофферс, у меня такая есть. Я помогу тебе разлить \"Медовую зыбь\" по бутылкам, чтобы этот грубиян, отец Мальтона, остался доволен. Но, разумеется, не бесплатно – взамен я хочу две бутылки \"Зыби\" для себя. Бутылки можно найти в ящиках на заброшенной базе Орды у Осклизлой скалы.$B$BДостать их будет нелегко, потому что в руинах кишмя кишат слизнюки и пиявки, и, говорят, у них там есть какой-то предводитель, что-то вроде верховного слизнюка. Но другого способа нет – придется тебе идти на базу и искать полные бутылки.",
    O = "Найдите заброшенную базу Орды на Осклизлой скале и заберите из ящиков 10 бутылок \"Медовой зыби из Внутренних земель\".",
    T = "Грязное дело",
  },
  [770] = {
    D = "На потрепанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом.$B$BМожет быть, следует рассказать кому-нибудь в Лагере Солнечного Пастбища о кончине Призрачного Воя...",
    O = "Отыщите кого-нибудь, кто слышал о Призрачном Вое.",
    T = "Поцарапанный демоном плащ",
  },
  [7701] = {
    D = "Именем его светлости надзирателя Скользорука должно убить агента Братства Тория надзирателя Мальтория, командира подразделения Шлаковой Ямы войск Черного Железа в Котловане. Его голову должно принести в качестве доказательства. $B$BЗа наградой обращаться к дозорному капитану Лоло Долгобою.",
    O = "Дворф Черного Железа, вероломный надзиратель Мальторий, скрывается в глубине Шлаковой Ямы в Котловане, что в Тлеющем ущелье. $B$BУбейте надзирателя Мальтория и принесите его голову дозорному капитану Лоло Долгобою.",
    T = "РАЗЫСКИВАЕТСЯ: надзиратель Мальторий",
  },
  [7702] = {
    D = "Чтобы подорвать силы Черного Железа в Шлаковой Яме, необходимо нанести удар по самому уязвимому месту. $B$BОткрою тебе секрет: дворфы, а особенно дворфы Черного Железа, крайне нуждаются в регулярном отдыхе. Хорошем отдыхе! $B$BТак вот скажи мне, как они смогут спать, если у них не будет подушек? Правильно! Никак. Поэтому надо прокрасться в Шлаковую Яму и стянуть все их подушки!",
    O = "Найдите спальные кварталы дворфов Черного Железа в глубине Шлаковой Ямы, что в Котловане. $B$BУкрадите 20 подушек дворфов Черного Железа. По выполнении задания вернитесь к Эвонис Сажекурке.",
    T = "Казнь через лишение сна",
  },
  [7703] = {
    D = "Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!$b$bА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!",
    O = "Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.$b$bПо словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.",
    T = "Неоконченное дело Гордоков",
  },
  [7704] = {
    D = "Ну и ну... Вот так сюрприз! У горничной была огромная вышитая подушка, и вот теперь она в ваших руках. Эвонис Сажекурке непременно захочет заполучить ее. Посмотрим, что она сможет предложить взамен...",
    O = "Отнесите подушку горничной Крепкие Тиски Эвонис Сажекурке в Тлеющее ущелье.",
    T = "Размер имеет значение",
  },
  [771] = {
    D = "Чтобы пройти обряд Прозрения, тебе придется собрать некоторые реагенты для создания воды Провидцев.$b$bМне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли.$B$BВ этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведет тебя к следующему этапу священного обряда.",
    O = "Принесите 2 камня, лежащих у источника, и 2 янтарных семени Зарельману Две Луны в деревню Кровавого Копыта.",
    T = "Обряд прозрения",
  },
  [772] = {
    D = "Я вручаю тебе воду Провидцев.$B$BВыпей ее перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнет видение.$B$BПосле этого следуй за ним навстречу своей судьбе...",
    O = "Выпейте воду Провидцев перед костром племени в деревне Кровавого Копыта и следуйте за видением.",
    T = "Обряд прозрения",
  },
  [7721] = {
    D = "Если я поступлю вопреки доводам разума, и все же буду по-прежнему содержать инженерную мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями. Чтоб им провалиться, этим необузданным стихиям!$b$bНо как повезло мне – а теперь и вам, $Gмой уважаемый помощник:моя уважаемая помощница;! Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя! Так что ликвидируйте их, не стесняясь, только, смотрите, не выбрасывайте ядра элементалей воды!",
    O = "Соберите 10 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.",
    T = "Энергия для уменьшения",
  },
  [7722] = {
    D = "Когда этот негодяй Мальторий покинул клан, он унес с собой кое-что поважнее безупречнейшего чародейского кристалла. Он украл рецепт огненного плавня! Полагаю, это была его возможность выслужиться у дворфов Черного Железа. $B$BВерни нам эти секретные документы, $n. Мальторий наверняка держит их при себе, там, в Шлаковой Яме.",
    O = "Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальторием. Инспектор скорее всего находится в Шлаковой Яме в Котловане. Документы верните мастеру-кузнецу Закалону в Тлеющем ущелье.",
    T = "Какой еще плавень?",
