  [7786] = {
    D = "Я рассказал тебе все, что знаю, $n. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя Огня.$b$bЕсли ты справишься, с тобой пребудет благословение Громораана.",
    O = "Чтобы освободить Громораана Искателя Ветра из тюрьмы, отнесите правую и левую половины наручников Искателя Ветра, 10 слитков зачарованного элементия и сущность повелителя огня верховному лорду Демитриану в Силитус.",
    T = "Громораан Искатель Ветра",
