  [7838] = {
    D = "",
    O = "",
    T = "Великий повелитель арены",
  },
  [7839] = {
    D = "Эти негодяи из племени Порочной Ветви напали на нашу деревню и украли мои инструменты! У меня, конечно, есть запасные, но тот набор, что они уволокли, был мне дорог как память. Когда я был еще мальчишкой, мне спас жизнь один гном, а потом он подарил мне тот набор.$B$BЯ очень хочу вернуть их, $n, я без них как без рук!$B$BМархор сказал, что мои инструменты видели в храмах Агол'вата и Шаол'вата, они оба на северо-востоке Внутренних земель.$B$BПожалуйста, верните мне инструменты!",
    O = "Найдите потерянные инструменты кузнеца Углежога из деревни Сломанного Клыка во Внутренних землях.$B$BУглежог сказал, что инструменты могут быть в одном из храмов троллей Порочной Ветви в северо-восточной части Внутренних земель. Также следует проверить на Осклизлой скале.",
    T = "Хулиганы Порочной Ветви",
  },
  [784] = {
    D = "Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда.$b$bВторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров!$b$bПокажи свою доблесть, $n. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей.",
    O = "Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га'Току на Колючий Холм.",
    T = "Бей предателей!",
  },
  [7840] = {
    D = "Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли племени Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдешь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!",
    O = "Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.$B$BЛярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из племени Порочной Ветви.",
    T = "Лярд потерял свой обед",
  },
  [7841] = {
    D = "Клан Громового Молота якшается с нашими врагами и заключает с ними союзы. В этот раз они спутались с высшими эльфами. Убейте любого высшего эльфа из Высокодолья, которого только встретите – пусть их тела послужат предупреждением.$B$BС троллями шутки плохи!",
    O = "Убейте 8 гонцов, 5 разведчиков, 5 стрелков и 2 следопытов Высокодолья по поручению Отхо Можи'ко из деревни Сломанного Клыка.$B$BВысших эльфов из Высокодолья можно найти в Сторожке Кель'Данил в северо-западной части Внутренних земель.",
    T = "Послание клану Громового Молота",
  },
  [7842] = {
    D = "Говорят, что дворфы Громового Молота и их грифоны – друзья не разлей вода. Хоть это и не очень красиво, но нужно воспользоваться этим преимуществом. Сделаем им еще одно предупреждение.$B$BУбей всех грифонов, каких только встретишь во Внутренних землях, и принеси мне длинное элегантное перо – это должно подействовать.",
    O = "Принесите длинное элегантное перо Отхо Можи'ко из деревни Сломанного Клыка во Внутренних землях. Перо нужно собрать с местных грифонов, которых можно найти практически в любом месте Внутренних земель.",
    T = "Еще одно послание клану Громового Молота",
  },
  [7843] = {
    D = "*Отхо вручает вам длинное окровавленное копье, обернутое перьями грифона*$B$BВот, берите. Отнесите это на Заоблачный пик, в самый центр тамошнего поселения. Воткните копье у колодца, пусть эти дворфы знают, что с нами шутки плохи! А потом возвращайтесь ко мне. Надеюсь еще увидеть вас $gживым:живой;.",
    O = "Заберитесь на Заоблачный пик в западной части Внутренних Земель и оставьте возле колодца в центре города последнее послание клану Громового Молота. После выполнения задания возвращайтесь к Отхо Можи'ко в деревню Сломанного Клыка.$B$BБерегитесь дворфов Громового Молота и других сторонников Альянса.",
    T = "Последнее послание клану Громового Молота",
  },
  [7844] = {
    D = "Во Внутренних землях живет три племени троллей, $n. На этом, собственно, сходство и заканчивается – мы все тролли и мы все живем здесь.$B$BПлемя Порочной Ветви, как следует из названия, самое отвратительное – тамошние каннибалы едят и троллей, и вообще всех, кто подвернется.$B$BЕсли бы Зул'джин был здесь, он бы уничтожил все это отродье одним движением руки! Но Зул'джина с нами нет, поэтому приходится справляться самим.$B$BВот вам задание – пойти и убить троллей из племени Порочной Ветви.",
    O = "Убейте 6 охотников за скальпами и 2 ворожеев из племени Порочной Ветви по поручению Яо'джин из деревни Сломанного Клыка.$B$BЯо'джин сказала, что эти тролли живут близ храмов Шаол'вата и Агол'вата в северо-восточной части Внутренних земель.",
    T = "Собратья-каннибалы",
  },
  [7845] = {
    D = "Однажды ночью племя Порочной Ветви совершило набег на нашу деревню и похитило моего мужа. Наши разведчики узнали, что он еще жив и находится в плену на самом верху Джинта'Алора. Они сказали, что коварная жрица Ведьмиса хочет принести его в жертву их безлицему кровавому богу Хаккару.$B$BПрошу вас, $n, спасите его! Наша деревня не переживет такой тяжелой потери.",
    O = "Спасите старейшину Сломанного Клыка из Джинта'Алора по поручению его жены из деревни Сломанного Клыка.$B$BСтарейшину держат в плену на самом верху Джинта'Алор – главного поселения троллей племени Порочной Ветви, расположенного на юге Внутренних земель.",
    T = "Похищен старейшина Сломанный Клык!",
  },
  [7846] = {
    D = "Ключ от моих кандалов у Хита'йи Хранительницы, она в пещере поблизости. Но будь $gосторожен:осторожна;, там полно охраны!$B$BУбей Хранительницу и возьми у нее ключ, иначе мне отсюда не выйти.",
    O = "Убейте хранительницу Хита'йю и заберите у нее ключ от кандалов, после чего возвращайтесь к старейшине Сломанному Клыку и освободите его.",
    T = "Отыскать ключ!",
  },
  [7847] = {
    D = "Вернитесь к моей жене, старейшей Зазубренный Клык! Скажите ей, что со мной все хорошо, и что скоро я буду дома. Она непременно наградит вас за это известие.",
    O = "Возвращайтесь к старейшине Сломанному Клыку и сообщите ей, что ее муж спасен.",
    T = "Возвращение к старейшине племени Сломанного Клыка",
  },
  [7848] = {
    D = "Земля испещрена трещинами и разломами – прямо у нас под ногами, |3-6($r). В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя огня.$B$B$gУдивлен:Удивлена;? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.",
    O = "Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.",
    T = "Сродство с недрами",
  },
  [7849] = {
    D = "Как и многие жители нашей деревни, мой близкий человек погиб в лесу. Это был мой брат-близнец Мальхор – он погиб в бою с троллями Порочной Ветви, тогда же, когда пропал муж старейшей племени Зазубренный Клык.$B$BМоего брата очень быстро казнили, а его останки бросили на съедение слизнюкам и волкам.$B$BЖизнь его мы не уберегли, но душу спасти еще можно. Пожалуйста, принесите мне его останки, $n.",
    O = "Принесите охотнику Мархору из деревни Сломанного Клыка во Внутренних землях кости и череп его брата-близнеца.$B$BМархор сказал, что останки его брата бросили на съедение слизнюкам и волкам Порочной Ветви – все эти твари водятся неподалеку от вершины Джинта'Алор: слизнюки в компостной яме, а волки – в логове.",
    T = "Боль разлуки",
  },
  [785] = {
    D = "Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани.$b$bТролли Черного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне.$b$bИ вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы.$b$bРазыщи Лара и спроси, не нужна ли ему помощь.",
    O = "Разыщите Лара Ночного Клыка на западной окраине деревни Сен'джин.",
    T = "Стратегический союз",
  },
  [7850] = {
    D = "Тролли племени Порочной Ветви проявляют в бою необычайную свирепость! Это все потому, что их околдовала недобрая коварная жрица Ведьмиса.$B$BВ поселении Джинта'Алор можно найти очень много сосудов с порченой кровью, которые излучают темную магию безлицего кровавого бога и наделяют троллей сверхъестественными силами, сводя их с ума.$B$BУкрадите эти сосуды и принесите их мне, чтобы я сняла порчу и ослабила хватку кровавого бога.",
    O = "Принесите 5 сосудов с порченой кровью старейшине племени Сломанного Клыка во Внутренние земли. Сосуды с кровью находятся в поселении Джинта'Алор.",
    T = "Темные сосуды",
  },
  [786] = {
    D = "Говори потише, |3-6($c)! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.$b$bПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!$b$bНельзя допустить, чтобы они это сделали! Достаточно ли ты $gхрабр:храбра, чтобы напасть на Утес Колкар и уничтожить их планы?$b$bЯ заметил, что они хранятся у трех лидеров кентавров.",
    O = "Лар Ночной Клык из деревни Сен'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что на Утесе Колкар.",
    T = "Предотвращение агрессии племени Колкар",
