  },
  [8052] = {
    D = "",
    O = "",
    T = "Всевидящее Око Зулдазара",
  },
  [8053] = {
    D = "Ты – $gязычник:язычница;, но мы не преследуем язычников в нашем племени. Мы уважаем тех, кто не боится гонений и без колебаний готов принять смерть за свою веру. Мы знаем, что ты $gготов:готова; умереть за свои убеждения, наши вольнодумцы тоже были такими.$B$BНам нужны Знаки Силы. Ступай в Зул'Гуруб и уничтожь прислужников Хаккара. Возвращайся, когда найдешь то, что мне нужно. В обмен я отдам тебе одну из деталей брони зандаларских вольнодумцев.",
    O = "Принесите Джин'року Разрушителю изначальные поручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BДжин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: боевые наручи вольнодумца",
  },
  [8054] = {
    D = "Твои верования для нас чужды, $gязычник:язычница;. Но племя Зандалара в свое время тоже называли еретиками. Это было еще во времена расцвета Гурубаши. Тогда язычники осмелились бросить вызов жрецам Хаккара. Их нещадно преследовали и уничтожали, словно диких зверей, но они до самого конца не отступили в своей борьбе против Кровавого бога. Мы понимаем, какую цену им пришлось заплатить, и чтим их мужество. Они были настоящими вольнодумцами. $B$BУничтожь приспешников Хаккара в Зул'Гурубе и принеси мне Знаки Силы. В случае успеха тебя ждет награда.$B$BСтупай.",
    O = "Принесите Джин'року Разрушителю изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BДжин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки силы: пояс вольнодумца",
  },
  [8055] = {
    D = "Боевое снаряжение – это символ могущества. Вольнодумцы же особенно гордятся своими доспехами. Они усиливают кирасы могущественными заклятиями, и даже если во время боя их вера пошатнется, то кирасы выдержат все что угодно.$B$BЕсли ты заслужишь уважение нашего племени, то получишь такую кирасу. Ступай в Зул'Гуруб и принеси мне Знаки Силы. Вырви их у врага безо всякой пощады. Докажи, что ты заслуживаешь звания вольнодумца.",
    O = "Принесите Джин'року Разрушителю Изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BДжин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: кираса вольнодумца",
  },
  [8056] = {
    D = "Авгуры нашего племени очень гордятся своим даром предвидения. Это тебе не знахари, которые только и знают, что проклинать направо и налево! Нет, наши авгуры предсказывают будущее по костям и листьям. Тебе, как $Gшаману:шаманке;, должно быть известно, на что способны авгуры. В Зандаларе их откровения очень ценятся.$B$BПокажи нам, чего ты стоишь, и принеси Знаки Силы из Зул'Гуруба. Если тебе это удастся, я отдам тебе наручи, которыми наши авгуры очень дорожат.",
    O = "Принесите Мейвики Зулдазарской Изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BМейвики Зулдазарская живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: наручи авгура",
  },
  [8057] = {
    D = "Гаруспики играют не последнюю роль в нашем племени; если ты достаточно $Gмудр:мудра;, то обязательно прислушаешься к их предсказаниям. Они читают судьбу по внутренностям животных и приносят их в жертву духам, чтобы узнать божественную волю. Именно мудрость гаруспиков дала нам преимущество в войне с разрозненными племенами империи Гурубаши.$B$BДокажи нашему племени, чего ты стоишь. Принеси из Зул'Гуруба Знаки Силы, и я отдам тебе наручи, от которых не отказался бы никто из гаруспиков Зандалара.",
    O = "Принесите Мейвики Зулдазарской изначальный браслет Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: наручи гаруспика",
  },
  [8058] = {
    D = "Месть – это сила. Именно она движет блюстителями Зандалара. У племени много врагов, и блюстители несут им воздаяние. Ни одно преступление против нас не останется безнаказанным! Враги должны бояться нашей мести! Так было раньше и так будет всегда.$B$BСтань одним из наших блюстителей! Найди Знаки Силы в Зул'Гурубе. Соверши возмездие от имени нашего племени и уничтожь прислужников Хаккара. Ты будешь $Gнагражден:награждена;.",
    O = "Принесите Джин'року Разрушителю изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BДжин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: боевые наручи воздаятеля",
  },
  [8059] = {
    D = "Чернокнижники ступают на опасную почву, заключая сделки с демонами, но наши бесноватые зашли еще дальше. С помощью древнего ритуала они позволяют демону захватить свое тело, а потом пытаются подчинить его своей воле и использовать его силу. Совершить такой подвиг удается не многим.$B$BЕсли хочешь приобщиться к знанию бесноватых, принеси мне Знаки Силы из Зул'Гуруба.",
    O = "Принесите Ал'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: напульсники бесноватого",
  },
  [806] = {
    D = "Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре! Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползется по нашей земле!$b$bЯ провел расследование и выяснил, что один из чернокнижников Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда. Там он и его приспешники сеют хаос!$b$bНайди Пшикса, убей его и принеси мне его коготь в качестве доказательства.",
    O = "Принесите коготь Пшикса Оргнилу Душегрызу из Колючего Холма.",
    T = "Сгущаются черные тучи",
  },
  [8060] = {
    D = "Маги нашего племени – это творцы иллюзий. В свои чары они вплетают заклинания, одурманивающие врагов и сбивающие их с толку.$B$B*Альтабим злорадно хихикает.*$B$BНаблюдать за работой настоящего мастера иллюзий – истинное удовольствие. Ты можешь видеть, как враг уничтожает себя сам, все больше и больше погружаясь в безумие.$B$BЕсли хочешь узнать о мастерах иллюзий побольше, ступай в Зул'Гуруб и принеси мне Знаки Силы. Взамен я отдам тебе напульсники, которые использовали наши мастера иллюзий, творя свои заклинания.",
    O = "Принесите Ал'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: напульсники мастера иллюзий",
  },
  [8061] = {
    D = "В Зандаларе принято одаривать силой тех, кто общается с богами и власть имущими. Наши жрецы не просто целители – они исповедники нашего племени. Зло приходит как снаружи – из Зул'Гуруба, так и изнутри. Наши исповедники – наши судьи, которые оберегают нас от того зла, что поглотило Гурубаши.$B$BСтупай в Зул'Гуруб и принеси Знаки Силы. Узнай, что значит быть исповедником, и охрани нас от зла.",
    O = "Принесите Ал'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: напульсники исповедника",
  },
  [8062] = {
    D = "В темные времена, наставшие после падения империи Гурубаши, зандаларские хищники использовали все свое мастерство, чтобы наше племя сумело выжить. И теперь они воплощают в себе самую сущность охоты. Отправляйся в Зул'Гуруб и докажи, что ты $gдостоин:достойна; занять место среди хищников Зандалара. Принеси мне Знаки Силы из Зул'Гуруба. Тогда ты сможешь еще на один шаг приблизиться к тому, чтобы стать $gодним:одной; из немногих хищников нашего племени.",
    O = "Принесите Фальтиру Слепому из Зул'Гуруба изначальные наручники Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: наручи хищника",
  },
  [8063] = {
    D = "Безумцы Зандалара чем-то сродни разбойникам, но самое главное – они несут с собой Хаос и разрушение. В те жестокие времена, когда наши племена были раздроблены, боевое безумие помогло нам выстоять против врага. Если бы не оно, мы бы не уцелели.$B$BПринеси мне Знаки Силы из Зул'Гуруба, и одна из деталей брони безумцев станет твоей. Впусти боевое безумие в свою душу!",
    O = "Принесите Фальтиру Слепому изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: наручи безумца",
  },
  [8064] = {
    D = "Мы в Зандаларе не следуем путями друидов: мы не подстраиваемся под природу, но меняем ее согласно нашим желаниям. Тем не менее и среди нас есть те, кто близок к природе. Наши гаруспики всегда умели слушать и понимать ее. Чтобы понять дух животного, надо знать, что значит быть одним из них. В этом и заключается истинная сила природы.$B$BПринеси мне Знаки Силы из Зул'Гуруба, докажи племени, что тебе можно доверять. Если ты сделаешь это, я отдам тебе могущественный пояс – из тех, что некогда принадлежали гаруспикам Зандалара.$B$BВ нем сокрыто могучее колдовство!",
    O = "Принесите Мейвики Зулдазарской изначальный кушак Хаккари. Мейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.",
    T = "Знаки Силы: пояс гаруспика",
  },
  [8065] = {
    D = "Одежда гаруспиков, $n, – это символ их могущества. Например, мундир – это символ связи между гаруспиком и постигаемой им божественной мудростью. В мундир зашивают части тел животных, принесенных в жертву. Это напоминает гаруспику о связи с его дарами.$B$BДокажи племени, чего ты стоишь, и принеси Знаки Силы из Зул'Гуруба. Сделай это, и мундир гаруспиков, хранящий их силу, станет твоим.",
    O = "Принесите Мейвики Зулдазарской Изначальную гербовую накидку Хаккари. Мейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: мундир гаруспика",
  },
  [8066] = {
    D = "Любой хищник знает, как подкрадываться к добыче, но самый ловкий умеет выбирать лучший момент для удара. Ты $gдолжен:должна; уметь и подкрадываться, и нападать, чтобы вернуться с добычей из Зул'Гуруба.$B$BПринеси мне Знаки Силы. Я обрету могущество, заключенное в них, а ты получишь пояс зандаларского хищника – вещь, ради которой стоит потрудиться.",
    O = "Принесите Фальтиру Слепому из Зул'Гуруба изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: пояс хищника",
  },
  [8067] = {
    D = "В Зандаларе одежда рассказывает о подвигах того, кто ее носит. При этом символы наших свершений не обязательно должны быть видимы глазом – излучаемая ими сила говорит сама за себя. Одежда хищников Зандалара обладает именно такими свойствами; более же всего они ценят свои оплечья. Они скрывают своего владельца от чужих взглядов, когда он желает остаться невидимым.$B$BВ Зул'Гурубе тебя ждут Знаки Силы. Принеси их мне, и это оплечье станет твоим.",
    O = "Принесите Фальтиру Слепому из Зул'Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: оплечье хищника",
  },
  [8068] = {
    D = "Магия – это бесформенная изначальная сила. Могучие маги управляют ее энергией в своих целях. Мы прибегаем к ней в своих заклятиях, но, чтобы создавать иллюзии, нужно особое могущество. Как можно победить врага, который существует только в твоем воображении? В Зандаларе знают цену подобной магии, и мастера иллюзий пользуются большим уважением в племени.$B$BПринеси из Зул'Гуруба Знаки Силы, и ты заслужишь уважение племени, а также оплечье мастера иллюзий.",
    O = "Принесите Ал'табиму Всевидящему изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАльтабим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: оплечье мастера иллюзий",
  },
  [8069] = {
    D = "В нашем племени одежда – это символ могущества и власти. Она сшита из лучших материалов и усилена заклинаниями, которые дают нам мощь. Одежды мастеров иллюзий отражают самую сущность творимых ими заклятий. Легенды гласят, что одежды мастера иллюзий постоянно меняет свой вид.$B$BЯ могу дать тебе такое одежды, $n... но сначала покажи племени, на что ты $gспособен:способна;. Принеси мне из Зул'Гуруба Знаки Силы!",
    O = "Принесите Ал'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: одеяние мастера иллюзий",
  },
  [807] = {
    D = "My scouts report that some of the Durotar wildlife have become infected with a demonic taint. They were seen to the north and west.$B$BThey wander among their brethren as normal beasts, but evil powers flow through them, and burning within each one is a heart scorched by black magic.$B$BThese beasts must be destroyed!$B$BIf you find such an animal while you explore Durotar, kill it and collect its Scorched Heart. Bring the hearts to me and I will have them studied, then destroyed.",
    O = "Bring 5 Scorched Hearts to Orgnil Soulscar in Razor Hill.",
    T = "<UNUSED>",
  },
  [8070] = {
    D = "После падения имеперии Гурубаши ужасное зло, разъедавшее племя изнутри, охватило и Зандалар. Нас спасли исповедники, которые защищали нас от нас же самих, не давая истреблять себе подобных. До сих пор исповедники охраняют наш дух и стоят на страже наших жизней.$B$BСтупай в Зул'Гуруб и узри глубину падения Хаккара и Гурубаши. Вырви из их грязных лап Знаки Силы. В случае успеха тебя ожидает награда.",
    O = "Принесите Ал'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: пояс исповедника",
  },
  [8071] = {
    D = "Исповедники Зандалара носят особые оплечья, по которым каждый из нас узнает пастырей племени. Эти оплечья усилены могучими заклятиями, которые помогают почувствовать угрозу, исходящую от врагов племени. Тебе, как $Gжрецу:жрице;, они очень бы пригодились.$B$BЕсли ты отправишься в Зул'Гуруб, сразишься с приспешниками Хаккара и принесешь мне нужные Знаки Силы, я отдам тебе оплечье, достойное лучших исповедников.",
    O = "Принесите Ал'табиму Всевидящему изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: оплечье исповедника",
  },
  [8072] = {
    D = "Одним из легендарных безумцев Зандалара был Карвахал Безумный. Легенды гласят, что в боях с врагами племени он применял заклинание \"волна безумия\", наложенное на его оплечья. Врагов поражал ужас, и они видели только мелькание его двойных кинжалов. До сих пор оплечья безумцев – предмет их особой гордости.$B$BПринеси мне Знаки Силы из Зул-Гуруба, и они достанутся тебе, чтобы вселять безумие и трепет в твоих врагов.",
    O = "Принесите Фальтиру Слепому изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: оплечье безумца",
  },
  [8073] = {
    D = "Мои глаза уже давно ничего не видят, но я от этого не страдаю. В нашем племени одежда – символ твоего статуса и могущества, поэтому самые могущественные предметы излучают невидимую глазами силу. Этот мундир зандаларского безумца – не исключение, он пронизан изначальной магией хаоса и безумия, присущих его владельцу.$B$BМне нужны Знаки Силы, которые находятся в Зул'Гурубе. Принеси мне их, и я отдам тебе этот легендарный мундир, который... придется под стать любому сеятелю безумия.",
    O = "Принесите Фальтиру Слепому из Зул-Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: мундир безумца",
  },
  [8074] = {
    D = "Авгуры многое знают о стихиях, дружище, и используют свои знания во славу нашего племени. В темные времена, наступившие после падения империи Гурубаши, именно авгуры привели нас в тихую гавань Южных морей. Они же вернули нас обратно в Долину, в самое сердце зла, свившее себе гнездо в Зул'Гурубе.$B$BПринеси Знаки Силы из Зул'Гуруба и докажи племени, чего ты стоишь. Взамен я дам тебе пояс, который служил нашим авгурам. Это не простой пояс, на нем лежит могучее заклинание.",
    O = "Принесите Мейвики Зулдазарской изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: пояс авгура",
  },
  [8075] = {
    D = "Все авгуры Зандалара носят хауберки. Они сшиты из лучшего шелка и укреплены прочными кольчужными звеньями. Хауберк – не только символ причастности авгуров к божественному, но и знак их власти. Никто не смеет переходить дорогу тем, кто общается с духами.$B$BДокажи свою преданность племени и принеси мне Знаки Силы из Зул'Гуруба. Если тебе удастся сделать это, я отдам тебе лучший из хауберков, который когда-либо носили наши авгуры!",
    O = "Принесите Мейвики Зулдазарской изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: хауберк авгура",
  },
  [8076] = {
    D = "Бесноватые стремятся полностью слиться с силой, а не просто использовать ее. Многие из бесноватых проиграли бой со своим демоном. Но когда враги наступали со всех сторон – особенно в Зул'Гурубе, – победа стоила всех принесенных жертв. От того, сумеем ли мы сокрушить наших врагов, зависит наше существование, – этому нас научило падение империи Гурубаши.$B$BСтупай в Зул'Гуруб и добудь необходимые нам Знаки Силы. Наградой тебе будет оплечье бесноватого.",
    O = "Принесите Ал'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: оплечье бесноватого",
  },
  [8077] = {
    D = "Одеяния, в которые мы облачаемся перед битвой, говорят о нашей силе. Одеяние бесноватого создано из рунической ткани, на которую наложено могучее заклятие. Один его вид вселяет страх в сердца врагов... Особенно его боятся демоны, зная, что рано или поздно бесноватый их одолеет и подчинит своей воле.$B$BПринеси мне Знаки Силы из Зул'Гуруба. Это непросто сделать... но в случае успеха одеяние бесноватого станет твоим.",
    O = "Принесите Ал'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: одеяние бесноватого",
  },
  [8078] = {
    D = "Зул'Гуруб жаждет мести, но Хаккар не должен воцариться! Он подточил империю Гурубаши и разрушил ее, и этому преступлению не может быть оправдания. Из-за Хаккара тролли теперь – лишь тень былой славы.$B$BСтань нашим блюстителем, уничтожь служителей зла. Зул'Гуруб должен отведать мести Зандалара. Как доказательство совершенной мести, принеси мне Знаки Силы. Взамен ты получишь пояс воздаятеля. С ним ты обретешь настоящую мощь.$B$BСтупай.",
    O = "Принесите Джин'року Разрушителю изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BДжин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: пояс воздаятеля",
  },
  [8079] = {
    D = "Символ мощи воздаятеля – его кираса. Ее выковывают, используя могучие заклятия. Подобный доспех носят только те, кто заслужил почет и уважение племени. Кираса воздаятеля – символ отмщения Зандалара.$B$BСтать блюстителем – значит нести отмщение. Добудь в Зул'Гурубе Знаки Силы и принеси их нам. Мы должны вернуть заклинания, которые были у нас украдены. Пусть приспешники Хаккара заплатят за свои преступления кровью! Твоей наградой будет кираса воздаятеля.$B$BСтупай. Отомсти за нас.",
    O = "Принесите Джин'року Разрушителю изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BДжин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    T = "Знаки Силы: кираса воздаятеля",
  },
  [808] = {
    D = "Я слышу голос моего брата, Миншины. Он взывает ко мне из снов.$b$bЕго захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мертв.$b$bНо смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа. В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха. Пока его душа находится в этом месте, она обречена на вечные страдания.$b$bПрошу тебя, $n, отыщи этот круг и похить череп Миншины. Принеси его мне.$b$bОсвободи его!",
    O = "Украдите череп Миншины из магического круга на островах Эха.$b$bПринесите его мастеру Гадрину в деревне Сен'джин.",
    T = "Череп Миншины",
  },
  [8080] = {
    D = "Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо и все это можно добыть там.$B$BИ вот чего я хочу от вас, $n. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.",
    O = "Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.",
    T = "Ресурсы Низины Арати",
  },
  [8081] = {
    D = "",
    O = "",
    T = "Новые ящики с ресурсами",
  },
  [809] = {
    D = "Со времен последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействует на общество орков. И принесенный тобой ошейник подтверждает мои опасения!$b$bОн принадлежит Пылающему Клинку, культу, объединенному вокруг предмета, который наделен демонической силой. Этот предмет называется Демоново семя, и находится он в Степях, на Вершине Багрового Тумана. Его необходимо уничтожить!$b$bОтправляйся на форпост на границе Степей, к западу, и поговори с моим помощником, Ак'Зелотом. Он скажет тебе, что делать дальше.",
    O = "Поговорите с Ак'Зелотом в Степях.",
    T = "Ак'Зелот",
  },
  [81] = {
    D = "Я позаботился о том, чтобы ничего не пропало – ни медовуха из бочонка, ни лишние бутылки. Не то чтобы я так уж тепло относился к Драну, но нет ничего хуже, чем когда пропадает выпивка! Вот, держи.$b$bДоставь этот бочонок Драну Дрофферсу в его забегаловку в Оргриммаре. Да, и пожалуйста, не забудь передать привет Мальтону. Скажи, что если он соскучится по отличной выпивке и великолепным собутыльникам, то мы будем в восторге от его визита.",
    O = "Доставьте бочонок в Оргриммар Драну Дрофферсу.",
    T = "Груз медовухи",
  },
  [810] = {
    D = "You would do well to learn how dangerous this land can be, |3-6($c).$B$BThe wildlife here can teach us such things... if we are wise and observant.$B$BThe scorpids are a perfect example of survival in Durotar. If you are to survive, it would be wise to take on some of their characteristics as your own. Their hardened carapaces can protect you from the harshness of the sun, or even a deadly weapon.$B$BBring me 6 Small Scorpid Carapaces from the Clattering Scorpids, $n, and I shall see about rewarding you justly.",
    O = "Bring 6 Small Scorpid Carapaces to Kor'ghan in Sen'jin Village.",
    T = "<UNUSED>",
  },
  [8101] = {
    D = "",
    O = "",
    T = "Камешек Каджаро",
  },
  [8102] = {
    D = "",
    O = "",
    T = "Камешек Каджаро",
  },
  [8103] = {
    D = "",
    O = "",
    T = "Камешек Каджаро",
  },
  [8104] = {
    D = "",
    O = "",
    T = "Самоцвет Каджаро",
  },
  [8105] = {
    D = "$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.",
    O = "Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.",
    T = "Битва за Низину Арати",
  },
  [8106] = {
    D = "",
    O = "",
    T = "Ожерелье Кезанского порока",
  },
  [8107] = {
    D = "",
    O = "",
    T = "Ожерелье Кезанского порока",
  },
  [8108] = {
    D = "",
    O = "",
    T = "Ожерелье Кезанского порока",
  },
  [8109] = {
    D = "",
    O = "",
    T = "Ожерелье Вечного Кезанского Позора",
  },
  [811] = {
    D = "One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you've probably already seen this behavior in your first scorpid hunt.$B$BYou would do well to heed that lesson and adapt it for yourself: we are stronger as one; we are weak when we are divided into many.$B$BBring me 8 Large Scorpid Carapaces from the Armored Scorpids and I shall reward you for learning this wisdom.",
    O = "Bring 8 Large Scorpid Carapaces to Kor'ghan in Sen'jin Village.",
    T = "<UNUSED>",
  },
  [8110] = {
    D = "",
    O = "",
    T = "Зачарованные водоросли Южных морей",
  },
  [8111] = {
    D = "",
    O = "",
    T = "Зачарованные водоросли Южных морей",
  },
  [8112] = {
    D = "",
    O = "",
    T = "Зачарованные водоросли Южных морей",
  },
  [8113] = {
    D = "",
    O = "",
    T = "Безупречные зачарованные водоросли Южных морей",
  },
  [8114] = {
    D = "$n, ты бесстрашно $gворвался:ворвалась; в самое пекло сражения в Низине Арати и $gзаслужил:заслужила; на этом поле боя великие почести. Ты $gпоказал:показала; нам, чего стоит |3-6($c) вроде тебя, и $gпоказал:показала; нашим врагам, что мы не сдадимся перед их подлостью!$B$BПоскольку ты уже $gдоказал:доказала; нам свою ценность, у меня есть для тебя очень трудное задание. Я хочу, чтобы ты $gзанял и удержал:заняла и удержала; как минимум четыре базы в Низине Арати. Если тебе удастся это сделать, мы не только сумеем собрать стратегически важные ресурсы – мы сможем показать Орде наше превосходство!$B$BИди, $n, и да сопутствует тебе удача.",
    O = "Отправляйтесь в Низину Арати, захватите и удержите контроль над четырьмя базами одновременно, затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.",
    T = "Контроль над четырьмя базами",
  },
  [8115] = {
    D = "$n, битва за Низину Арати – кровавое предприятие. Ваша помощь очень нужна Лиге Аратора и принимается с большой благодарностью.$B$BУ нас есть для вас еще одно задание.$B$BЛига хочет нанести решительный, сильный удар по оккупирующим Низину Арати Осквернителям. Мы хотим выбить их со всех стратегических точек поля боя!$B$BЭто будет нелегко, но если кто и в состоянии это сделать, так это именно вы.",
    O = "Возьмите под контроль одновременно все 5 баз в Низине Арати, а затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.",
    T = "Контроль над пятью базами",
  },
  [8116] = {
    D = "",
    O = "",
    T = "Ожерелье видений Вудресса",
