  },
  [8230] = {
    D = "",
    O = "",
    T = "Пробное задание Коллина",
  },
  [8231] = {
    D = "Волношлеп – земноводное, встречающееся только в Азшаре. Эти твари сильны и очень живучи. $b$bВ их твердой блестящей чешуе, как в зеркале, отражается мастерство охотника. $b$bВыследи и убей нескольких на побережье Азшары и принеси мне их чешую.",
    O = "Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.",
    T = "Охота на волношлепа",
  },
  [8232] = {
    D = "Ты отправляешься на опасную охоту, |3-6($r). Убей зеленого дракона Морфаза и принеси мне его зуб. Морфаз обитает в Храме Атал'Хаккара. Вход в него ты найдешь на Болоте Печали. $b$bНо помни, $gодному:одной; тебе его не осилить. У дракона много врагов – найди соратников и уничтожь его! $b$bМногие, очень многие не прочь добыть зуб этой твари. Принеси его мне, и я достойно награжу тебя.",
    O = "Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.",
    T = "Зеленый дракон",
  },
  [8233] = {
    D = "Лорд Джорах Черный Ворон настоятельно приглашает вас к себе. Приглашение тайное, поэтому никаких подробностей.$b$bПоместье Черный Ворон находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд.",
    O = "Поговорите с лордом Джорахом Черным Вороном в его поместье.",
    T = "Приглашение",
  },
  [8234] = {
    D = "Начнем сначала. Я потерял небольшую сумку голубого цвета. В ней были мои личные вещи. $b$bНет нужды искать воров – они уже мертвы. Мне известно лишь, что эти дураки не сумели открыть сумку и продали ее какому-то шаману из племени Древобрюхов в Азшаре, выдав ее за священную реликвию. Очень умно. $b$bЯ хочу, чтобы ты $gотправился:отправилась; в Азшару и $gзаполучил:заполучила; у шамана мою сумку – хитростью или силой. Полагаю, что лучше все же хитростью. Сумку отнеси верховному магу Ксилему.",
    O = "Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре.",
    T = "Запечатанная лазурная сумка",
  },
  [8235] = {
    D = "Лорд Черный Ворон просил нас с тобой об услуге. Он желает снять заклятие с этой сумки. $B$BК сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями. Каждый клочок, оставшийся от них, невероятно ценен для меня. $B$BЕсли ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг. Чтобы найти фрагменты, поохоться на обитающих в Азшаре зверей – они обычно подбирают все, что плохо лежит.",
    O = "Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару.",
    T = "Зашифрованные фрагменты",
  },
  [8236] = {
    D = "Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие. Когда я закончу, то самолично доставлю сумку лорду Черному Ворону. $b$bОднако нам все еще нужен ключ. Говорят, что ключ присвоил зеленый дракон по имени Морфаз. Его логово находится в глубинах Храма Атал'Хаккара – вход в него ты найдешь на Болоте Печали. $b$bСобери своих сподвижников и отправляйся к логову дракона. Лорд Черный Ворон ждет, когда ты принесешь ему ключ.",
    O = "Принесите лазурный ключ лорду Черному Ворону.",
    T = "Лазурный ключ",
  },
  [8237] = {
    D = "",
    O = "",
    T = "REUSE",
