  [825] = {
    D = "Один из моих лучших разведчиков принес сообщение, что обломки кораблей Праудмура все еще плавают около побережья Дуротара, к востоку от крепости Тирагард.$b$bНи для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой. Нам нужно знать все о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу.$b$bСплавай к обломкам, $n, и добудь мне инструменты Альянса.",
    O = "Га'Ток с Колючего Холма просит вас принести ему 3 комплекта инструментов гномов, найти которые можно в обломках кораблей у побережья.",
    T = "Обломки кораблекрушения",
  },
  [8250] = {
    D = "Верховный маг Ксилем ищет кого-то... Не менее опытного, чем ты.$b$bЕсли хочешь, поговори с ним. Он живет в Азшаре, в башне на вершине утеса. Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо.$b$bСанат живет в лагере ниже башни своего хозяина. Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрешься в скалы.",
    O = "Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему.",
    T = "Магическое искусство",
  },
  [8251] = {
    D = "Эльфы крови в Азшаре изобрели свой способ распылять магические предметы. Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления.$b$bЯ отправил ученика купить этой пыли, но эльфы безжалостно убили его. Они должны заплатить за это! $b$bВремя мирных переговоров прошло, $n. Найди эльфов крови в скалах Азшары и примени к ним более... убедительные методы. Мне нужна эта пыль.",
    O = "Принесите 10 горстей сияющей пыли верховному магу Ксилему.",
    T = "Волшебная пыль",
  },
  [8252] = {
    D = "Оглянись вокруг. Развалины и все побережье кишат тварями Бича Злобы. Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре. $b$bНапример, эти твари почему-то очень интересуются заколдованными кораллами – по совершенно не ясным мне причинам. Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований! Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне.",
    O = "Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.",
    T = "Кораллы сирен",
  },
  [8253] = {
    D = "В глубинах Храма Атал'Хаккара скрывается зеленой дракон по имени Морфаз. $b$bМного лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика. Мне не впервой терять учеников, однако именно этот, проглоченный, нес кристалл тайной магии небывалой мощи. $b$bВыбери достаточно сильных соратников и отправляйся в Затонувший храм. Уничтожь Морфаза и принеси мне мой кристалл.",
    O = "Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.",
    T = "Уничтожить Морфаза",
  },
  [8254] = {
    D = "Служителям богов пристало помогать попавшим в беду. Как именно – неважно, главное – во имя чего.$b$bКругу Кенария необходима помощь. Если ты хочешь протянуть им руку помощи, поговори с Огтинком. Он живет на вершинах скал на северо-востоке от руин Эльдарата в Азшаре.",
    O = "Отыщи Огтинка в Азшаре.",
    T = "Помощь Кенарию",
  },
  [8255] = {
    D = "Мохноногие олени, обитающие в Азшаре, – самые великолепные создания, когда-либо населявшие Оскверненный лес. Они наделены естественной невосприимчивостью ко всем болезням и ядам, поэтому порча не коснулась их. Мудрые животные предпочли покинуть зараженные земли. $b$bК прискорбию своему я должен просить тебя поохотиться на этих прекрасных созданий, поскольку их железы необходимы для изготовления целительного снадобья. Снадобья, которое вернет Оскверненному лесу его прежний облик.",
    O = "Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.",
    T = "Охота на беговых оленей",
  },
  [8256] = {
    D = "Чтобы получить целительное снадобье, воспользуемся простым рецептом: смешаем одну часть яда с двумя благотворными субстанциями. Один целительный компонент у нас уже есть, теперь надо добыть яд. $B$BСамые могущественные твари нежити, такие как неупокоенные высокорожденные, скитающиеся по руинам Эльдарата, часто настолько сильно поражены порчей, что она принимает вполне осязаемую форму зеленой слизи. Среди живых эта субстанция известна как лимфа нежити. $b$bЭто очень мощный яд, поэтому потребуется лишь одна мера.",
    O = "Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.",
    T = "Лимфа нежити",
  },
  [8257] = {
    D = "Теперь нам нужен последний целительный компонент. $b$bИзвестно, что зеленый дракон Морфаз наделен невосприимчивостью ко всем болезням и ядам. Это знание досталось дорогой ценой – не один друид погиб, пытаясь справиться с драконом. Уверен, его кровь послужит отличным компонентом для нашего снадобья.$b$bПосланник Круга Кенария заберет уже собранные тобой компоненты, пока ты будешь добывать последний. Собери соратников и отправляйся в логово зеленого дракона в затонувший Храм Атал'Хаккара. Принеси его кровь Грете Замшелому Копыту в Оскверненный лес.",
    O = "Убейте Морфаза в затонувшем Храме Атал'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на Болоте Печали.",
    T = "Кровь Морфаза",
  },
  [8258] = {
    D = "Темный Терзатель, рыцарь смерти, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.$b$bПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $n! Только его гибель способна исправить урон, нанесенный миру духов!",
    O = "Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.$b$bПринесите голову Темного Терзателя Сагорну Гривастому Страннику на Аллею Мудрости Оргриммара.",
    T = "Угроза Темного Губителя",
  },
  [8259] = {
    D = "",
    O = "",
    T = "Более достойная награда",
  },
  [826] = {
    D = "Знахарь Залазан живет на островах Эха на востоке. Эти острова мы когда-то называли родиной...$b$bА теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону все новых приспешников.$b$bЕго нужно остановить!$b$bУничтожь Залазана и его слуг – бывших троллей Черного Копья, ныне потерянных для нас! Принеси мне его голову – и я буду знать, что владычеству зла пришел конец.",
    O = "Убейте Залазана, убейте 8 троллей-вудуистов и 8 проклятых троллей.$b$bПринесите голову Залазана Гадрину.",
    T = "Залазан",
