  [8269] = {
    D = "",
    O = "",
    T = "Ленты жертвоприношения",
  },
  [827] = {
    D = "$n! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как Скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками.$b$bЯ подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников.$b$bСтупай в Скалу Черепа и отбери у фанатиков, которых там найдешь, их ошейники. Принеси их мне, и я раскрою их тайну!",
    O = "Отберите у фанатиков из Скалы Черепа обжигающие ошейники.$b$bПринесите их в лагерь Маргозу.",
    T = "Скала Черепа",
  },
  [8270] = {
