  },
  [8273] = {
    D = "",
    O = "",
    T = "Благодарность Оран",
  },
  [8274] = {
    D = "У тебя есть свободное времечко? Убей мне мурлоков, и я тебе блестяшечку дам!",
    O = "Убейте 5 мурлоков и вернитесь к испытательному персонажу.",
    T = "Убийственное поручение",
  },
  [8275] = {
    D = "Внемлите, герои Альянса! Мы слишком долго не обращали внимания на опасность, источник которой – силитиды. Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению.$b$bСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$b$bВсе на защиту Азерота! Все способные держать оружие должны пройти инструктаж у призывательницы ветров Гордого Рога в Крепости Кенария!",
    O = "Поговорите с призывательницей ветров Гордый Рог в Крепости Кенария.",
    T = "Отвоевание Силитуса",
  },
  [8276] = {
    D = "Внемлите, герои Орды! Мы слишком долго не обращали внимания на серьезную угрозу. Дрожание земли рядом с ульями силитидов говорит о серьезном возрастании их числа в связи с готовящимся нападением.$b$bСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$b$bВсе, способные держать оружие, должны обратиться к призывательнице ветров Гордыму Рогу в Крепости Кенария! Да сгинут силитиды!",
    O = "Поговорите с призывательницей ветров Гордый Рог в Крепости Кенария.",
    T = "Отвоевание Силитуса",
  },
  [8277] = {
    D = "Битисса Шаткобрус к твоим услугам! Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из Крепости Кенария редкие травы. Точнее, зарабатывал. Из последней вылазки он вернулся отравленный страшным ядом.$b$BЯ сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его.$b$bНоггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстролапов. Принеси мне несколько жал и клыков, и я сделаю противоядие.",
    O = "Принесите Битиссе Шаткобрус из Крепости Кенария 8 жал камнехвостых скорпидов и 8 клыков песчаных пауков-быстролапов.",
    T = "Смертельный яд",
  },
  [8278] = {
    D = "Проклятье! Противоядие не сработало. Наверное, Ноггла укусила одна из тварей на далеком юге, они гораздо страшнее остальных.$b$bПридется попросить тебя отправиться за образцами, $n. В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз. С другой стороны, на юге больше ядовитых тварей, поэтому придется убить по несколько существ разных видов.",
    O = "Принесите Битиссе Шаткобрус из Крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.",
    T = "Последняя надежда Ноггла",
