  [8349] = {
    D = "Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны. Поговори с Бором Буйногривым. Он даст тебе задание.$b$bУдачи, $n. Если тебе снова понадобятся медальоны, возвращайся ко мне.",
    O = "Поговорите с Бором Буйногривым из Крепости Кенария.",
    T = "Бор Буйногривый",
  },
  [835] = {
    D = "Газлоу мне как-то сказал: \"Резлак, заруби себе на носу: если хочешь, чтобы что-то было сделано хорошо, сделай это сам\".$b$bМы не можем и дальше терять караваны, так что я вынужден взять дело в собственные руки. Наши торговые пути заполонены гарпиями. Если удастся их перебить, дороги вновь станут безопасными.$b$bРазумеется, Газлоу учил меня и другому: \"За соответствующую плату тебе сделают что угодно\". Ну что, $n, возьмешься? Отлично... Советую начать с каньона на востоке.",
    O = "Убейте 12 дуротарских гарпий. Подойдут любые разновидности гарпий.",
    T = "Обеспечение безопасного сообщения",
  },
  [8350] = {
    D = "Гибель еще одного нашего курьера – истинная трагедия, но это неизбежные издержки нашего ремесла. Нужно как можно быстрее доставить этот сверток магистру Эроне на постоялый двор на Площади Соколиных Крыльев.$B$BНам недостает курьеров, и мне больше некому дать это поручение.$B$BНе скрою – путь на Площадь Соколиных Крыльев станет чрезвычайно опасен, как только ты покинешь пределы Рассветной улицы. Возьмешься за это дело, $n?",
    O = "Доставьте сверток Эроны хозяйке таверны Деланиель на Площадь Соколиных Крыльев в Лесах Вечной Песни.",
