  },
  [8364] = {
    D = "",
    O = "",
    T = "Скипетры Бездны",
  },
  [8365] = {
    D = "Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдешь. Слушай внимательно, |3-6($c). Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно.$b$bВ общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?",
    O = "Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Хитрой Шестеренки в Танарисе.",
    T = "Пиратские шляпы",
  },
  [8366] = {
    D = "Они требуют от меня невозможного!$b$bКартель Хитрой Шестеренки хочет, чтобы я преподал пиратам Южных Морей урок. Мне что, разорваться?! Я должен поддерживать здесь порядок.$b$bВ последнее время пираты забыли, что картель платит им за защиту. Нужно показать им, что к чему.$b$bПираты поселились в Бухте Сорванных Парусов, неподалеку отсюда, на юге. Спасибо, $n. Я твой должник!",
    O = "Начальник отдела безопасности Чепухастер из Порта Хитрой Шестеренки в Танарисе просит убить 10 пиратов, 10 флибустьеров, 10 рабочих и 10 сорвиголов Южных морей.",
    T = "Покажи этим пиратам",
  },
  [8367] = {
    D = "Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$b$bСтупай же и сокруши противника на всех фронтах. За честь! За Орду!",
    O = "Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.",
    T = "Великая честь",
  },
  [8368] = {
    D = "Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$b$bНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!",
    O = "Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.",
    T = "Битва за Ущелье Песни Войны",
  },
  [8369] = {
    D = "Слушай, $n. Что бы ни болтали про битву в Альтеракской долине, правда состоит в следующем: экспедиция Грозовой Вершины вторглась в земли клана Северного Волка. В тот день, когда мы позволим Альянсу безнаказанно нарушать наши границы, я повешу секиру на стену и примусь посыпать голову пеплом. Отправляйся и сотри в порошок наглых захватчиков!",
    O = "Принесите 3 почетных знака Альтеракской долины ордынскому вестнику войны рядом со входом на поле боя.",
    T = "Вторжение в Альтеракскую долину",
  },
  [837] = {
    D = "Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью! Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно.$b$bНо с нас уже довольно! Мы не можем больше терпеть присутствие Иглогривых в наших землях. Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек. Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!",
    O = "Убейте 4 свинобразов из племени Иглогривых, 4 разведчиков из племени Иглогривых, 4 пылемутов из племени Иглогривых и 4 боевых стражей из племени Иглогривых по просьбе Га'Тока из Колючего Холма.",
    T = "Вторжение",
  },
  [8370] = {
    D = "Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.$b$bВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, $n!",
    O = "Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.",
    T = "Завоевание Низины Арати",
  },
  [8371] = {
    D = "В войне против Орды решающей может оказаться любая битва, $gсынок:дочка;.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$b$bАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.",
    O = "Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.",
    T = "В едином порыве",
  },
  [8372] = {
    D = "Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе.$b$bЭтот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды.$b$bВнеси свой вклад в борьбу со всадниками из клана Песни Войны, $n! За Альянс!",
    O = "Принесите 3 почетных знака Ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.",
    T = "Битва за Ущелье Песни Войны",
  },
  [8373] = {
    D = "Самое гнусное в Тыквовине – это бомбы-вонючки, которые Отрекшиеся бросают на Южнобережье. Кто бы мог подумать, что праздновение свободы требует такой вони?$b$bКогда наступит Тыквовин, убери при помощи этого очистителя любую из мерзких бомб, которые Орда может подкинуть к нам в деревню. Очиститель действует благодаря силе сосен.$b$bПрими участие в поддержании чистоты Южнобережья, и я дам тебе кое-какие тыквовинские вкусности, которым ты несомненно порадуешься. Договорились?",
    O = "Уберите любую бомбу-вонючку Отрекшихся, брошенную в Южнобережье, при помощи очистителя бомб-вонючек. По выполнении задания возвращайтесь к сержанту Дыгалу.",
    T = "Сила сосен",
  },
  [8374] = {
    D = "Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.$b$bРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.$b$bЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!",
