  [8410] = {
    D = "Бат'ра Страж Ветра ищет шамана вроде тебя. Принеси ему по образцу каждой из стихий, чтобы доказать свое мастерство.$b$bБат'ру можно отыскать на востоке от Мельницы Таррен. Иди вдоль реки на север до руин. Там-то Бат'ра и разбил лагерь.",
    O = "Соберите образцы воздуха, огня, земли и воды по поручению Бат'ры Стража Ветра.",
    T = "Покорение стихий",
  },
  [8411] = {
    D = "Добро пожаловать, |3-6($c). Расклад такой: ты несешь мне стихии и только потом я с тобой говорю.$b$bМне нужны от тебя Огонь, Воздух, Вода и Земля. Только потом я тебе буду доверять, дружище. Надо удостовериться, что ты не совсем дундук.",
    O = "Принесите стихии Земли, Воздуха, Огня и Воды Бат'ре Стражу Ветра.",
    T = "Покорение Стихий",
  },
  [8412] = {
    D = "Духи стихий здешних мест меня невзлюбили.$b$bТы знаешь о тотемах больше других, а мне без защитного тотема духов не обойтись. Стихии у нас уже есть, теперь нужно что-то более близкое к природе, первобытное.$b$bВ Западных Чумных землях можно добыть когти медведей и глаза пауков. Падальщики едят и тех, и других, поэтому у них в желудках может быть и то, и другое.",
    O = "Принесите части тотема Духа Бат'ре Стражу Ветра.",
    T = "Тотем духов",
  },
  [8413] = {
    D = "Силы этого тотема духов не достаточно. Нам нужна магия вуду, чтобы сделать верную защиту.$b$bТролли из затонувшего храма делают перья, насыщенные магией вуду. Ступай туда и убей Гашера, Миджана, Золо, Хукку, Зул'Лора и Лоро. Тогда нам хватит магии на настоящий тотем духов.",
    O = "Принесите вудуистские перья Бат'ре Стражу Ветра.",
    T = "Вуду",
  },
  [8414] = {
    D = "Привет тебе, |3-6($c). Отрадно видеть рыцаря вроде тебя в сих безотрадных землях.$b$bМы рассчитваем на твою помощь в борьбе с беконечными полчищами нежити. Собери побольше камней Плети и отнеси их верховному жрецу Тель'данису. Он охраняет гробницу Утера неподалеку отсюда.$b$bКамни Плети находят лишь те, кто получил Жетон Серебряного Рассвета. Если у тебя нет амулета, поговори с офицером Чистосердой.",
    O = "Принесите 20 камней приспешников Плети верховному жрецу Тель'данису в Западные Чумные земли.",
    T = "Борьба со злом",
  },
  [8415] = {
    D = "Командиру Ашламу Неутомимому нужен паладин, не уступающий тебе честью и доблестью, $n. Командир живет в Лагере Промозглого Ветра в южной части Западных Чумных земель. Найди его и помоги делу Света!",
    O = "Обратитесь к командиру Ашламу Неутомимому в Лагере Промозглого Ветра.",
    T = "Лагерь Промозглого Ветра",
  },
  [8416] = {
    D = "Камни очищены от зла, $n.$b$bЯ в курсе планов командира Аслама, и ему понадобится всего лишь один бездействующий камень. Отнеси его, и да сгорит Плеть в праведном огне.",
    O = "Отнесите бездействующий камень командиру Ашламу Неутомимому на Берег Промозглого Ветра.",
    T = "Бездействующие камни Плети",
  },
  [8417] = {
    D = "По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды. Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним.",
    O = "Поговорите с павшим героем Орды у входа в Выжженные земли.",
    T = "Неупокоенный дух",
  },
  [8418] = {
    D = "Теперь мы сможем создать оружие против нежити из бездействующих камней Плети. Задание непростое. Магией, способной вынудить зло обратиться против самого себя, владеют лишь тролли из затонувшего храма.$b$bВ храме есть тролли по имени Ранокол, Миджан, Золо, Хукку, Зул'Лор и Лоро. Не стоит их жалеть... они давно пали и их души запятнаны злом.",
    O = "Добудьте янтарные, синие и зеленые вудуистские перья у троллей из Затонувшего храма.",
    T = "Создание камня силы",
  },
  [8419] = {
    D = "С тобой хочет встретиться один бес из Оскверненного леса по имени Бесенок. Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли. Ты весьма $gмогущественный чернокнижник:могущественная чернокнижница; и наверняка знаешь, что ткань Скверны таскают с собой сатиры Оскверненного леса.$b$bБесенок живет на севере от водопада Ядовитой Крови. Говорят, в это время года там очень красиво.",
    O = "Отнесите Бесенку из Оскверненного леса отрез ткани Скверны.",
    T = "Просьба беса",
  },
  [842] = {
    D = "<Каргал извлекает сильно помятое письмо из-за пазухи и подписывает его, а затем торжественно протягивает его вам.>$b$bНу, $gмолокосос:девчонка;, я увидел, что ты можешь быть грозным противником. Считай, что $gпринят:принята;. Теперь ты потребуешься нам в Перекрестке – если, конечно, доберешься туда $gживым:живой;. Следуй по дороге, ведущей отсюда на запад, а затем на развилке на юг. Если действительно хочешь помочь Орде, поговори с Халгой и отправляйся с ее следующим караваном. Отдашь письмо Сергре Черный Шип сразу же как прибудешь.",
    O = "Отнесите подписанное письмо Сергре Черный Шип в Перекрестке. Можете присоединиться к ближайшему каравану, поговорив с Халгой Кровавый Глаз на Дальней заставе.",
    T = "Рекрутский набор Перекрестка",
  },
  [8420] = {
    D = "Может, ты и не $Gожидал:ожидала; услышать это от беса, но мне хочется завести питомца. Правда-правда. Это же нечестно – у Ниби есть я, а у меня нет никого!$b$bМне даже не надо живого питомца. Мне нужно что-нибудь, из чего я бы мог его себе сделать – например, ткань Скверны. У сатиров тут, в Оскверненном лесу, ткань Скверны-то имеется, так что просто убивай их, пока не найдешь ткань. Звучит не так уж и ужасно, правда?",
    O = "Принесите отрез ткани Скверны Бесенку в Оскверненный лес.",
    T = "Пробирает!",
  },
  [8421] = {
    D = "Теперь, когда у меня есть ткань Скверны, я могу начать изготовление собственного питомца.$b$bНо ему нужны глазки! Может, сумеешь оторвать кусочек гнилой древесины от железного дерева, и я вырежу из нее прелестные глазки? Деревья эти можно найти в Железнолесье.$b$bА еще мне понадобится немного экстракта ядовитой крови, чтобы мой питомец приобрел демонический запах. Этот экстракт можно добыть из нечистых слизнюков, а они ошиваются прямо по соседству со мной и Ниби.",
    O = "Принесите 10 кусков гнилой древесины и 4 порции экстракта ядовитой крови Бесенку в Оскверненный лес.",
    T = "Бросовый материал",
  },
  [8422] = {
    D = "Мой питомец почти готов. Осталось набить его.$b$bТолько вудуистские перья с троллей затонувшего храма помогут делу. Их зовут Ранокол, Миджан, Золо, Хукку, Зул'Лор и Лоро. Убей их. Перебей их всех! $b$bЭто непростое дело, $n, потому я заплачу тебе за услугу, дав тебе кое-что из барахла Ниби – ему это все равно, наверное, не нужно.",
    O = "Принесите 6 вудуистских перьев троллей из затонувшего храма.",
    T = "Тролли Пера",
  },
  [8423] = {
    D = "*Герой окидывает тебя взглядом.*$b$bНет сомнений, ты |3-6($c). У меня для тебя есть почетная задача, но сначала необходимо испытать твою силу.$b$bГоворят, что Рексар проверял остроту своих клинков, убивая зловепря одним быстрым ударом. Теперь же я проверю твою силу, отправив тебя на охоту за зловепрями.",
    O = "Убейте 7 Зловепрей в Выжженных землях и вернитесь к павшему герою Орды.",
    T = "Воинское испытание",
  },
  [8424] = {
    D = "Постоянное присутствие Приверженцев Тени в Выжженных землях причиняет мне сильную боль. Их темные ритуалы и заклинания вызывают мучения, каких я не ведал при жизни.$b$bЧерез тебя я могу передать мое собственное послание боли. Иди и неси мой гнев.",
    O = "Убейте Приверженцев Тени в Выжженных землях и вернитесь к павшему герою Орды.",
    T = "Война против Приверженцев Тени",
  },
  [8425] = {
    D = "Благодаря твоей чести я обрел частицу покоя. Неправильно было бы ничего не предложить взамен.$b$bПри жизни мое оружие и доспехи были великолепны, но теперь они для меня бесполезны. Быть может, тебе они послужат лучше.$b$bОтправляйся к затонувшему храму и уничтожь троллей-охранников Ранокола, Миджана, Золо, Хукку, Зул'Лора и Лоро. У них хранятся магические перья, которые могут восстановить мое материальное тело на достаточно долгое время, чтобы я мог вручить тебе награду.",
    O = "Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем Храме.",
    T = "Вудуистские перья",
  },
  [8426] = {
    D = "Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$b$bНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!",
    O = "Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.",
    T = "Битва за Ущелье Песни Войны",
