  },
  [8468] = {
    D = "Город Луносвет назначает награду за голову Таэлиса Ненасытного, известного главаря Презренных. Он разыскивается за то, что неоднократно совершал преступления против жителей города Луносвета, в том числе убил двух городских стражников.$b$bОтносительно награды осведомляться у сержанта Ка'рена.",
    O = "Принесите голову Таэлиса сержанту Ка'рену на Площадь Соколиных Крыльев в Лесах Вечной Песни.",
    T = "Разыскивается: Таэлис Ненасытный",
  },
  [8469] = {
    D = "",
