  [8475] = {
    D = "Полоса выжженной земли, которая тянется через Леса Вечной Песни, как постоянное напоминание о том дне, когда Артас привел Плеть в наш возлюбленный город...$b$bЭто хуже, чем бельмо на глазу: даже теперь по ней в Луносвет приходят прислужники Плети из Призрачных земель.$b$bСтупай, $n, и помоги моим воинам убивать лишенную разума нежить, которая приходит Тропой Мертвых.",
    O = "Убейте 8 чумнокостных погромщиков и вернитесь к следопыту Джаеле на Тропе Мертвых в Лесах Вечной Песни.",
    T = "Тропа Мертвых",
