  },
  [876] = {
    D = "Гарпии, которых ты $gубил:убила;, упоминали о своем матриархе, Серене Кровавое Перо. Судя по тому, какую ненависть они испытывали к Орде, дело в какой-то давней вражде. Выследи Серену Кровавое Перо и покончи с ней раз и навсегда.",
    O = "Убейте Серену Кровавое Перо и отрубите ей голову.",
    T = "Серена Кровавое Перо",
  },
  [8760] = {
    D = "",
