  [8807] = {
    D = "Исследования геолога Злая Шутка имели огромное значение для нашей деятельности в Силитусе. Недавно она запросила материалы для гадания.$b$bПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает исследования.",
    O = "Принесите 1 большой сверкающий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Злой Шутке в Крепости Кенария в Силитусе. Также принесите тыловое задание V.",
    T = "Материалы для гадания",
  },
  [8808] = {
    D = "У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их Зовущей из клана Гордый Рог.",
    O = "Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину призывательнице ветров Гордый Рог в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.",
    T = "Поставки формы",
  },
  [8809] = {
    D = "Варгус, кузнец Крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в Крепость Кенария, чтобы он снабдил войска всем необходимым.",
    O = "Принесите Варгусу из Крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.",
    T = "Необычные материалы",
  },
  [881] = {
    D = "Ичияки, Белый Туман на языке тауренов, король кошачьих обитателей саванны. Он подкрадывается к жертвам так незаметно, что его уподобили тонкому белому туману, который стелется над землей. Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли.$B$BТаурены говорят, что он воплощает собой одновременно милосердие и смерть.$B$BТы узнаешь это на своем опыте, потому что я отправляю тебя охотиться на Ичияки. Его логово располагается к северо-западу от Перекрестка, на северном склоне небольшой горы среди костей огромного кодо.$B$BСтупай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов.",
    O = "Подуйте в рог возле логова Ичияки, убейте его или подчините.",
    T = "Ичияки",
  },
  [8810] = {
    D = "В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их Зовущей из клана Гордый Рог в Крепость Кенария.",
    O = "Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 бинтов из магической ткани призывательнице ветров Гордый Рог в Крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу X.",
    T = "Запас бинтов",
  },
