  [8827] = {
    D = "Говорят, что Дедушка Зима – не без помощи Пастбищ Дымного Леса – сложил под елку в Стальгорне подарки для всех. Я бы с радостью сходил туда, но мне надо присматривать за PX-238 Чудовольтом Мороза.$b$bА ты непременно туда загляни. Не сомневаюсь, Дедушка Зима и для тебя подарочек припас.",
    O = "Поговорите с Дедушкой Зимой. Он находится в Стальгорне, неподалеку от торговой зоны Пастбищ Дымного Леса.",
    T = "Подарки Дедушки Зимы",
  },
  [8828] = {
    D = "Говорят, что Дедушка Зима – не без помощи Пастбищ Дымного леса – сложил под елку в Оргриммаре подарки для всех. Я бы с радостью сходил туда, но мне надо присматривать за PX-238 Чудовольтом Мороза.$b$bА ты непременно туда загляни. Не сомневаюсь, Дедушка Зима и для тебя подарочек припас.",
    O = "Поговорите с Дедушкой Зимой. Он находится в Оргриммаре, неподалеку от торговой зоны Пастбищ Дымного Леса.",
    T = "Подарки Дедушки Зимы",
  },
  [8829] = {
    D = "Сумеречный Молот действует путем обмана и тайных наветов. Хотя они действуют в нашем мире, их идеи рождаются за его пределами, куда мы прежде не могли добраться.$b$bМы пришли к заключению, что камни, которыми главари Сумеречного Молота пользуются для призывания своих повелителей, работают в обе стороны. Чтобы попытаться воспользоваться ими подобным образом, мы должны изготовить точнейшую копию одеяния посланника культа Сумеречного Молота.$b$bСобери все необходимые материалы и отнеси их Аурэль Золотой Лист, $n.",
    O = "Принесите шкуру тени, 3 истлевшие шовные нити поганища и 1 одеяние сумеречного сектанта Аурэль Золотой Лист в Крепость Кенария в Силитусе. Кроме того, сдайте тыловую задачу XI.",
    T = "Последняя хитрость",
  },
