  [9556] = {
    D = "Ты без сомнения прекрасно $gпроявил:проявила; себя в борьбе за башни, |3-6($r), и непременно получишь свою награду за доблесть. Но сначала ты $gдолжен:должна; доказать, что понимаешь всю глубину разыгравшейся здесь трагедии.$B$BОтправляйся на улицы Стратхольма и найди сосуд со святой водой. Отнеси его в Квартал Магов в Штормград или Подгород... Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег.",
    O = "Найдите бутылку святой воды Стратхольма на улицах Стратхольма и доставьте ее Лордеронскому магу в Квартал Магов в Штормграде или Подгороде, если вашей стороне удалось одержать верх в Восточных Чумных землях.",
    T = "Вода для мага",
  },
  [9557] = {
    D = "Прочесть записи невозможно – изначальный текст нельзя отделить от скорописи картографа. Но, может быть, кто-нибудь все-таки сумеет это сделать?..$B$BАнахорет Пайтеус собрал множество артефактов различных культур: возможно, его опыт поможет расшифровать и эти записи?",
    O = "Отнесите древние записи на Кровавую заставу и покажите анахорету Пайтеусу.",
    T = "Расшифровка книги",
  },
  [9558] = {
    D = "У нас тут проблемы с араккоа, которые нападают на наши караваны с продовольствием, так что пришлось нанять пару дворфов, чтобы они разобрались с птичками.$B$BЭто двое братьев, Гремни Длиннобород из них старший.$B$BНо если честно, я немного беспокоюсь. Эти чокнутые дворфы взяли с собой эля вдвое больше, чем провизии и снаряжения вместе взятых! Может быть, ты проследишь за ними?$B$BАраккоа гнездятся в Логове Хаал'еш, которое находится к западу отсюда – довольно далеко, у Глубокого Разлома. Дворфы должны были разбить там лагерь, к югу от Лощины Пыльного Пера.",
    O = "Найдите Гремни Длинноборода на северо-западе от Логова Хаал'еш на Полуострове Адского Пламени.",
    T = "Длиннобородые",
  },
  [9559] = {
    D = "$GИзбранный:Избранная;, отправляйся на север, к дому моего народа – в логово клана Тихвой. Именно там тебя ждет самое сложное испытание.$B$BСтупай, верховный вождь клана Тихвой ждет твоего прибытия.",
    O = "Поговорите с верховным вождем клана Тихвой в Логове клана.",
    T = "Логово клана Тихвой",
  },
  [956] = {
    D = "Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чем дело. Несомнено эта печать находится во владении сатира, предводительствующего ими.$B$BЯ убежден, что моя догадка верна, $n. Она наверняка у одного из сатиров. Если ты сможешь ее добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слез...",
    O = "Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал'Аран.",
    T = "Башал'Аран",
  },
  [9560] = {
    D = "Мы с братом охотились в лесах на востоке, и на нас неожиданно напали странные твари, похожие на насекомых. Такого в Лазурной Дымке еще не видали! Может, грядет Судный день? И именно тебе суждено его предотвратить?$B$BЕсли ты в самом деле $gИзбранный:Избранная;, то легко поразишь тварей Судного дня... и принесешь мне их шкуры. Из таких шкур я смогу сделать великолепные доспехи!$B$BЗверей ты можешь найти на востоке, за дорогой.",
    O = "Принесите 8 шкур опустошителей Мурдо в логово клана Тихвой.",
    T = "Звери Судного дня!",
  },
  [9561] = {
    D = "Ну вот, $n, перевод готов.$B$B<Анахорет Пайтеус указывает на последний переведенный фрагмент.>$B$B\"Враги уже близко. Мы собрали всех, кто выжил, и отошли на восток, к храму. Храм – наш последний оплот на этом острове. Многие думают, что именно здесь нам суждено принять последний бой. Я спрятал то немногое, что у меня было, у подножия храма – надеюсь, кто-нибудь найдет мой тайник и узнает, что здесь произошло...\"",
    O = "Найдите место, описанное в дневнике Нолкаи, и отыщите его тайник.",
    T = "Записи Нолкаи",
  },
  [9562] = {
    D = "Темные настали дни, $GИзбранный:Избранная;. Даже мурлоки наступают нам на пятки – в прямом смысле слова. К сожалению, недавно они посягнули не только на мое самолюбие.$B$BУ нас всегда были напряженные отношения с племенем Илистых Плавников, но я и помыслить не мог, что они осмелятся напасть на нас и похитить запасы продовольствия! Отправляйся на запад, к Илистому берегу, и верни наши припасы!$B$BИ если тебе попадется темнокожий мурлок с клоком белой шерсти, застрявшим между пальцами...",
    O = "Верните 5 мешков зерна клана Тихвой.",
    T = "Мурлоки... За что нам эта напасть?",
  },
  [9563] = {
    D = "Хочешь, чтобы мы тебе доверяли? Да в наше время никому верить нельзя!$B$BНе так давно араккоа прикончили одного из наших, это меня здорово разозлило.$B$BВот что я тебе скажу. Если ты хочешь доказать свою верность Оплоту Чести... и... и... вообще! – то принеси мне кружку горькой настойки Стражей Пустоты... Да, пожалуй, это было бы недурно. Может быть, потом я и доверю тебе какое-нибудь несложное дело.$B$BНастойку можно достать у Берни из Крепости Стражей Пустоты, у него всегда есть запасы.",
    O = "Принесите Миррену Длиннобороду 1 кружку горькой настойки Стражей Пустоты. Для выполнения этого задания необходимо иметь дружелюбное отношение Оплота Чести.",
    T = "Доверие Миррена",
  },
  [9564] = {
    D = "Вы нашли клок шерсти, потерянный Гурфом в борьбе с мурлоками. Отнесите его Гурфу и сообщите, что ужасный Мургургул убит.",
