  [9571] = {
    D = "Отнесите шкуру Куркена Мурдо на другою сторону деревни. Он сделает из нее все, что вы захотите.",
    O = "Отнесите шкуру Куркена Мурдо в логово клана Тихвой.",
    T = "Шкура Куркена",
