  [9870] = {
    D = "Приветствую тебя, |3-6($r). Я – повелитель стихий Ялхан из Служителей Земли. Я пришел в Гарадар, чтобы проинформировать маг'харов о состоянии стихий.$B$BМогу я попросить тебя об одной небольшой услуге? Ты не $gмог:могла; бы сходить к Трону Стихий – это в северных холмах Награнда, за озером Небесной Песни – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Гарадара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.",
    O = "Поговорите с повелительницей стихий Шарвак у Трона Стихий.",
    T = "Трон Стихий",
  },
  [9871] = {
    D = "На пергаменте нарисована грубая и схематичная карта Награнда. Телаар обозначен большим красным \"X\". Похоже, Падшие Темной Крови готовят вторжение в город. Передайте планы вторжения Темной Крови Арехрону в Телааре.",
    O = "Передайте планы вторжения Темной Крови Арехрону в Телаар, что в Награнде.",
    T = "Захватчики из племени Темной Крови",
  },
  [9872] = {
    D = "На пергаменте нарисована грубая и схематичная карта Награнда. Гарадар обозначен большим красным \"X\". Похоже, Падшие Темной Крови готовят вторжение в город. Передайте планы вторжения Темной Крови Гаррошу в Гарадаре.",
    O = "Передайте планы вторжения Темной Крови Гаррошу.",
    T = "Захватчики из племени Темной Крови",
  },
  [9873] = {
    D = "Эти планы вторжения составлял мой давний знакомый. Ортор Темная Кровь, некогда знатный Сломленный, посвященный в науку стихий, теперь сделался лизоблюдом Мусел'ека, этого царя пиявок.$B$BИз плана следует, что они захватили Заставу Солнечного Источника, деревушку орков к северо-западу отсюда.$B$BОтправляйся на Заставу Солнечного Источника и избавь мир от Ортора. Так будет лучше для всех...",
    O = "Арехрон из Телаара в Награнде поручил вам убить Ортора Темную Кровь.",
    T = "Ортор, мой старый друг...",
  },
  [9874] = {
    D = "Мне только что стало известно о катастрофе поистине устрашающего масштаба, $n. Эти мерзавцы Темной Крови захватили орочью Заставу Солнечного Источника... это к северо-западу отсюда... перебили всех тамошних жителей, а тела принялись сбрасывать в озеро Солнечного Источника. Если все эти тела начнут разлагаться в озере, наш главный источник пресной воды в этой области будет отравлен.$B$BЯ понимаю, что это работа не из приятных, но ее надо сделать. Возьми этот зачарованный факел, иди на заставу и сожги все трупы орков...",
    O = "Сожгите 10 трупов селян Солнечного Источника с помощью факела жидкого огня. Когда исполните поручение, верните факел Отонбу Ведуну.",
    T = "Остановить заразу",
  },
  [9875] = {
    D = "А вот это растение Лауранна, очевидно, упустила из виду. Ты $gуверен:уверена;, что $gобнаружил:обнаружила; вид, еще не описанный Лауранной. Стоит показать это растение Лауранне и посмотреть, что она скажет...",
    O = "Принесите неизвестный науке вид Лауранне Тар'вел в Кенарийский оплот в Зангартопи.",
    T = "Неизвестный науке вид",
  },
  [9876] = {
    D = "Я отправила небольшой отряд наших друидов, чтобы исследовать обнаруженную тобой трубу в Змеином озере. Я рассчитывала на их скорое возвращение. Нужно ли говорить, что они не вернулись до сих пор?$b$bТы – $gодин:одна; из самых способных наших союзников. Пожалуйста, отыщи их и выясни, что с ними стало.",
    O = "По просьбе Исиэли Песни Ветра отыщите следы друидов из Кенарийской экспедиции у входа в Резервуар Кривого Клыка, что в Зангартопи.",
    T = "Провалившийся рейд",
  },
  [9877] = {
    D = "В битве с Плетью не избежать потерь. Каждый день многие погибают, но еще большему числу выпадает куда более страшный удел.$B$BПлеть захватывает пленников. И лучше им умереть, чем испытать то, что ждет их в Смертхольме. Их допрашивают и пытают, используя ужасный, ломающий волю яд. $B$BАптекарь Рензитен из Транквиллиона разработал противоядие – ступай к нему и принеси его приводящее в сознание зелье.",
    O = "Поговорите с аптекарем Рензитеном в Транквиллионе.",
    T = "Приводящее в сознание зелье",
  },
  [9878] = {
    D = "Появление клана Темной Крови в Награнде отрицательно сказалось на наших землях. Стихии пришли в движение, что, в свою очередь, вызвало беспокойство среди животных. Мало того, разрушение Заставы Солнечного Источника разбудило старую вражду между орками и моим народом.$B$BКуренай и Темная Кровь – разные кланы, но орки видят в них лишь Падших.$B$BЭту проблему надо устранить. Поезжай на северо-запад, на Заставу Солнечного Источника, и реши этот вопрос.",
    O = "Убейте 10 падальщиков и 5 налетчиков из племени Темной Крови.",
    T = "Устранение проблемы",
  },
  [9879] = {
    D = "Если бы не ты, $gнезнакомец:прекрасная незнакомка;, меня бы точно убили. Они перебили уже стольких куренаев в поисках своей утерянной реликвии!$B$BОни ищут тотем Кардаша. Не понимаю, с чего они взяли, что мы что-то знаем о нем. Этот тотем, как я понимаю, – реликвия орков, и уже в силу своей природы он может быть только орочьим орудием.$B$BЭти сведения нужно немедленно сообщить Арехрону. Быть может, он знает, почему Падшие из клана Темной Крови похищают куренаев и пытают их, чтобы добыть информацию об орудии орков.$B$BПомоги мне бежать.",
    O = "Куренайскому пленнику бежать с заставы Солнечного Источника. Расскажите Арехрону из Телаара обо всем, что вам удалось узнать.",
    T = "Тотем Кардаша",
  },
  [988] = {
    D = "I noticed the cloak you are wearing, $n. If you'd be willing to sacrifice it, I can renew its magics, and use it to escape. The problem with that, though, is you'll be left here in the cave alone.$B$BAre you able to make it out of here on your own if we choose that course?$B$BI can assure you that Terenthis will reward you for aiding me, if that is your concern.$B$BThe choice is yours, but I could really use your help.",
    O = "Speak to Volcor.",
    T = "<UNUSED>",
  },
  [9880] = {
    D = "",
    O = "",
    T = "Hellfire Penninsula: -pn – A – ToWoW – Hellfire Turnin Cap",
  },
  [9881] = {
    D = "",
    O = "",
    T = "Hellfire Penninsula: -pn – H – ToWoW – Hellfire Turnin Cap",
  },
  [9882] = {
    D = "Принц Харамад пока не разрешает нам работать внутри Ошу'гуна, поскольку это может разозлить некоторых влиятельных наару. Так что время идет, а работа стоит.$B$BНо я, кажется, нашел лазейку.$B$BПонимаешь, мы не единственные, кого тянет к этому гигантскому алмазу. Вор по имени Гава'кси возглавил банду головорезов, которые проникли в Ошу'гун и принялись откалывать от камня крупные куски.$B$BТвоя задача, |3-6($r), найти их и забрать то, что принадлежит нам по праву.",
    O = "Раздобудьте 10 осколков кристалла Ошу'гуна и отдайте их Гезхе в Небесном лагере в Награнде.",
    T = "Украсть у вора",
  },
  [9883] = {
    D = "",
    O = "",
    T = "Снова осколки кристалла",
  },
  [9884] = {
    D = "",
    O = "",
    T = "Выгодное сотрудничество",
  },
  [9885] = {
    D = "",
    O = "",
    T = "Выгодное сотрудничество",
  },
  [9886] = {
    D = "",
    O = "",
    T = "Выгодное сотрудничество",
  },
  [9887] = {
    D = "",
    O = "",
    T = "Выгодное сотрудничество",
  },
  [9888] = {
    D = "Я избежал верной смерти. Эти трусливые сволочи из клана Тяжелого Кулака ночью напали на наш городок, и я чудом уцелел.$B$BНо скажи, $gнезнакомец:незнакомка;: кто виноват в нашей беде?!$B$B*Джорин указывает на Гарроша.*$B$BОн отказал нам в помощи. Огры разоряют мой город, а он сидит тут и размазывает сопли. Что с нами стало? Во что мы превратились?! И что будет дальше?$B$BЯ отправил разведчика Килрата в город, который теперь называют руинами Кровавой Глазницы. Сможешь разыскать Килрата и помочь ему, если нужно? Он скрывается на границе Награнда и леса Тероккар.",
    O = "Джорин Мертвый Глаз просит вас найти Килрата и поговорить с ним.",
    T = "Слабосильный владыка",
  },
  [9889] = {
    D = "Я уже несколько дней слежу за этими тварями. Толстяк говорит, что чего-то ждет. Чего конкретно – неизвестно.$B$BУ меня есть план, но тут придется применить насилие. Нужно убить нескольких его подчиненных, а потом избить его до полусмерти. После этого, я уверен, он выложит все, что нам надо узнать.",
    O = "Убейте 10 захватчиков из клана Тяжелого Кулака, затем избейте и допросите Анкора Безжалостного.",
    T = "Толстяка не убивать",
  },
  [989] = {
    D = "If we decide to fight our way out, the plan is simple: we'll make our way down to the road and kill any furbolgs that get in our way... or anything else that decides it wants to stop us.$B$BI wish there was another way, but sooner or later the furbolg threat would have to be dealt with. Better it be by our own hands, so we know the job is done.$B$BTake a moment to prepare any magic or weapons you have at your disposal, then speak to me again.",
    O = "Speak to Volcor.",
    T = "<UNUSED>",
  },
  [9890] = {
    D = "Долгие годы клан Тяжелого Кулака правил над всеми ограми в Запределье. При Кроле огры объединились и жили дружно. Они довольствовались теми землями, которые им были даны. Однако в последние месяцы многие огры погибли от рук их же сородичей из Боевого Молота. Этот клан захватил почти все наши земли в Награнде и перебил многих наших собратьев.$B$BМы должны были взять этот город. У нас просто не было выбора. Нас истребляют...$B$BКрол пропал без вести, клан Тяжелого Кулака в полной растерянности. Лантрезор Клинок правит в его отсуствие.",
    O = "Передайте все сведения, которые вы выбили из Анкора, Килрату в лес Тероккар.",
    T = "Успех!",
  },
  [9891] = {
    D = "Расскажи обо всем Джорину в Гарадаре. Уверяю тебя, его не обрадует известие об уничтожении деревни и почти поголовном истреблении ее жителей из-за претензий огров на территорию.$B$BДа хранят тебя предки... Если я тебе снова понадоблюсь, я буду прятаться здесь в кустах. В общем, ты знаешь, где меня найти.",
    O = "Передайте информацию, которую вы выбили из Анкора, Джорину Мертвому Глазу в Гарадаре.",
    T = "Потому что Килрат – трус",
  },
  [9892] = {
    D = "",
    O = "",
    T = "Поиски обсидиановых боевых ожерелий",
  },
  [9893] = {
    D = "Гора Ошу'гун еще не готова к раскопкам, и мы теряем немалую прибыль, $n.$B$BК счастью, я обнаружил дополнительный источник дохода. Огры Награнда носят боевые ожерелья из обсидиана – минерала, который во многих мирах ценится весьма высоко.$B$BЗерид уже разобрался с парочкой этих громил – в интересах безопасности, разумеется. В данном случае ожерелья можно рассматривать как дополнительные премиальные... А еще лучше вообще никак их не рассматривать, а просто собрать и принести мне сюда.",
    O = "Принесите 10 обсидиановых боевых ожерелий Гезхе в Небесный лагерь в Награнде.",
    T = "Обсидиановое боевое ожерелье",
  },
  [9894] = {
    D = "В путешествиях тебе наверняка не раз доводилось встречать наблюдателей экспедиции. Они выполняют основную часть полевых работ: собирают образцы, описывают новые виды обитателей болот, устанавливают контакт с разумными существами...$b$b$C, нам необходимо обеспечить безопасность наблюдателей! Нам пришлось отозвать тех, кого мы отправили исследовать пещеру Грибгор на юге из-за нападений болотных обитателей. Страж-смотритель Хамуут считает, что, если убить их предводителя, Лорда Клака, нападения быстро прекратятся.",
    O = "Убейте Лорда Клака и вернитесь к призывательнице ветров Черное Копыто в Кенарийский оплот.",
    T = "Защита наблюдателей",
  },
  [9895] = {
    D = "Приглядись внимательно к природе вокруг нас, $n. Эти болота умирают. Они отчаянно борются за то, чтобы сохранить экологическое равновесие, но терпят поражение в этой борьбе.$b$bПризнаки этого очевидны, если знать, где искать. Представители отдельных видов достигают гигантских размеров и становятся все агрессивнее.$b$bВот взять, к примеру, болотоброда Топехлыста. Если хочешь на него посмотреть, далеко ходить не надо: достаточно выйти на болота к югу от Оплота.$b$bТолько без оружия не ходи! Эта тварь не ведает пощады.",
    O = "Найдите Топехлыста и уничтожьте его, потом вернитесь к Летин Лунному Пламени в Кенарийский оплот.",
    T = "Гибнущее равновесие",
  },
  [9896] = {
    D = "Жарковато здесь, клянусь огненным чревом Каз'горота! Вполне понимаю первую экспедицию, которая отсюда сбежала. Впрочем, все знают, что сбежали они не из-за жары. Их выжила черная браконида, хотя, конечно, они в этом ни за что не признаются!$b$bОни встали лагерем на юг от светящихся дренейских башен, что к западу отсюда, чуть на север от деревни Дикотопь. И тут, откуда ни возьмись, появляется гигантская оса и нападает на них! Жду не дождусь увидеть, какие у них будут лица, когда я привезу в Стальгорн жало этой самой осы!",
    O = "Принесите жало черной бракониды геологу Коналлу в Телредор.",
    T = "Проклятие черной бракониды",
  },
  [9897] = {
    D = "Я не жадная. Могу поделиться. Главное, я спаслась от этого паршивца Ганкли! С Зангартопи я притащила целую тонну шкур, так что с меня не убудет!",
    O = "Отнесите сверток шкур Гарольду Лейну в лагерь Эрнестуэя в Награнде.",
    T = "Я спасена!",
  },
  [9898] = {
    D = "Она будет моя. Лопни мои глаза, будет!$b$bСкажи, Магаша – самая прекрасная троллиха на свете? Мне только надо найти способ завоевать ее сердце. Ей, конечно, Зурай нравится, но мы это исправим. Я придумал абсолютно надежный план.$b$bМне надо ей показать, что я – самый крутой охотник. И для этого мне понадобишься ты! На болотах живет гигантское насекомое, известное как черная браконида. Ее встречали к югу от светящихся дренейских башен, которые стоят к западу отсюда. Принеси мне жало этой осы, и я пущу в ход свою магию!",
    O = "Принесите жало черной бракониды Реавижу на заставу Болотной Крысы.",
    T = "Лучшее доказательство любви!",
  },
  [9899] = {
    D = "Хотелось бы, чтобы кто-нибудь нашел способ вразумить этого Реавижа! Он совершенно забыл про свои обязанности, а вместо этого посвящает все свое время и силы тому, чтобы добиться моего расположения. Я пыталась не обращать на него внимания, я умоляла его перестать, – ничто не помогает!$b$bА до тех пор, пока он не придет в себя, мне приходится разгребать за ним несделанную работу! Например, он должен был разобраться со Спорокрылом, но могу поручиться, что это чудовище до сих пор летает на свободе! Послушай, если у тебя есть время, не сходишь ли ты в западную часть Мертвой трясины, чтобы убить этого ската? А я пока что разберусь с Реавижем...",
    O = "Убейте Спорокрыла по просьбе Магаши с заставы Болотной Крысы.",
    T = "Несделанное дело",
  },
  [99] = {
    D = "По мере того, как растет мое понимание магии Аругала, растет и мое презрение к этому злосчастному глупцу. Я уже почти закончил исследование его так называемого \"лекарственного зелья\". $b$bУ меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров. Днем живущие там крестьяне выглядят по-человечески. Но когда солнце заходит, деревенский люд превращается в воргенов Лунной Ярости. $b$bМне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом. Принеси мне 6 заколдованных кандалов из деревни Погребальных Костров, $n.",
    O = "Принесите 6 кандалов из деревни Погребальных Костров Далару Ткачу Рассвета в Гробницу.",
    T = "Безрассудство Аругала",
  },
  [990] = {
    D = "$n, моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни.$B$BОтправляйся отсюда на юг и держись дороги – ты легко найдешь путь, если будешь держаться этого направления.",
    O = "Найдите в Ясеневом лесу Раэну Волкопас.",
    T = "Путь в Ясеневый лес",
  },
  [9900] = {
    D = "Присутствие эфириалов-мошенников в этих краях, может быть, и забавляет Гезхе, который во всем ищет выгоду... однако это серьезная угроза безопасности нашей операции.$B$BИх вождь Гава'кси – опасный преступник, и сейчас моя главная задача – нейтрализовать его как можно скорее.$B$BЕсли хочешь быть нам $gполезным:полезной;, убей мерзавца Гава'кси. Я лично прослежу за тем, чтобы ты $gполучил:получила; достойное вознаграждение.",
